class _CompassRoseWidget extends StatelessWidget {
  final double size;
  final double rotationDegrees;
  final bool isHeadingUp;
  final VoidCallback? onTap;

  const _CompassRoseWidget({
    this.size = 36,
    this.rotationDegrees = 0.0,
    this.isHeadingUp = false,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final container = Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: const Color(0xCC06152D),
        shape: BoxShape.circle,
        border: Border.all(
          color: isHeadingUp ? const Color(0xff00D9FF) : const Color(0x5000D9FF),
          width: isHeadingUp ? 1.4 : 1.2,
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xff00D9FF).withValues(alpha: isHeadingUp ? 0.28 : 0.18),
            blurRadius: isHeadingUp ? 10 : 8,
          ),
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.40),
            blurRadius: 6,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Transform.rotate(
        angle: rotationDegrees * math.pi / 180.0,
        child: CustomPaint(
          size: Size(size, size),
          painter: _CompassNeedlePainter(),
        ),
      ),
    );

    final interactiveChild = onTap != null
        ? Material(
            color: Colors.transparent,
            shape: const CircleBorder(),
            child: InkWell(
              customBorder: const CircleBorder(),
              onTap: onTap,
              child: container,
            ),
          )
        : container;

    return Tooltip(
      message: onTap != null
          ? (isHeadingUp
              ? 'Compass: Heading-Up (Tap for North-Up)'
              : 'Compass: North-Up (Tap for Heading-Up)')
          : 'Compass',
      waitDuration: const Duration(milliseconds: 300),
      child: interactiveChild,
    );
  }
}

class _CompassNeedlePainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final cx = size.width / 2;
    final cy = size.height / 2;
    final needleLength = size.height * 0.38;
    final halfWidth = size.width * 0.12;

    // North Needle (Red)
    final northPath = Path()
      ..moveTo(cx, cy - needleLength)
      ..lineTo(cx + halfWidth, cy)
      ..lineTo(cx, cy - 2)
      ..close();
    final northPaint = Paint()..color = const Color(0xffFF4D5A);
    canvas.drawPath(northPath, northPaint);

    final northLeftPath = Path()
      ..moveTo(cx, cy - needleLength)
      ..lineTo(cx - halfWidth, cy)
      ..lineTo(cx, cy - 2)
      ..close();
    final northLeftPaint = Paint()..color = const Color(0xffE02434);
    canvas.drawPath(northLeftPath, northLeftPaint);

    // South Needle (White)
    final southPath = Path()
      ..moveTo(cx, cy + needleLength)
      ..lineTo(cx + halfWidth, cy)
      ..lineTo(cx, cy + 2)
      ..close();
    final southPaint = Paint()..color = Colors.white;
    canvas.drawPath(southPath, southPaint);

    final southLeftPath = Path()
      ..moveTo(cx, cy + needleLength)
      ..lineTo(cx - halfWidth, cy)
      ..lineTo(cx, cy + 2)
      ..close();
    final southLeftPaint = Paint()..color = const Color(0xffCBD5E1);
    canvas.drawPath(southLeftPath, southLeftPaint);

    // Center pivot circle
    final centerPaint = Paint()..color = const Color(0xff00D9FF);
    canvas.drawCircle(Offset(cx, cy), 2.5, centerPaint);

    // Small 'N' label at top
    final textPainter = TextPainter(
      text: const TextSpan(
        text: 'N',
        style: TextStyle(
          color: Colors.white,
          fontSize: 7.5,
          fontWeight: FontWeight.w900,
          letterSpacing: 0.2,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    textPainter.paint(
      canvas,
      Offset(cx - textPainter.width / 2, 2.5),
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

class _CyanLightRibbonPainter extends CustomPainter {
  final double pulseProgress;
  final bool isAnimated;

  const _CyanLightRibbonPainter({
    this.pulseProgress = 0.0,
    this.isAnimated = false,
  });

  @override
  void paint(Canvas canvas, Size size) {
    if (size.width <= 0 || size.height <= 0) return;

    final path = Path();
    path.moveTo(0, size.height * 0.40);
    path.cubicTo(
      size.width * 0.25,
      size.height * 0.04,
      size.width * 0.65,
      size.height * 0.12,
      size.width,
      size.height * 0.60,
    );

    // 1. Base Resting Ribbon Track
    // Outer cyan bloom
    final glowPaint = Paint()
      ..color = const Color(0xff00D9FF).withValues(alpha: 0.16)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 14.0
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12.0);
    canvas.drawPath(path, glowPaint);

    // Electric blue mid-stroke
    final midPaint = Paint()
      ..color = const Color(0xff1687FF).withValues(alpha: 0.35)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 6.0
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4.0);
    canvas.drawPath(path, midPaint);

    // Bright core white/cyan stroke
    final corePaint = Paint()
      ..color = const Color(0xffE0F7FF).withValues(alpha: 0.70)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.8;
    canvas.drawPath(path, corePaint);

    // 2. Animated Traveling Cyan/Electric-Blue Energy Pulse
    if (isAnimated) {
      final metrics = path.computeMetrics().toList();
      if (metrics.isNotEmpty) {
        final metric = metrics.first;
        final totalLength = metric.length;
        if (totalLength > 0) {
          final pulseLength = totalLength * 0.25;
          final headPos = pulseProgress * (totalLength + pulseLength);
          final startPos = math.max(0.0, headPos - pulseLength);
          final endPos = math.min(totalLength, headPos);

          if (endPos > startPos) {
            final pulseSubPath = metric.extractPath(startPos, endPos);

            // Intense pulse outer bloom
            final pulseGlowPaint = Paint()
              ..color = const Color(0xff00D9FF).withValues(alpha: 0.45)
              ..style = PaintingStyle.stroke
              ..strokeWidth = 16.0
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8.0);
            canvas.drawPath(pulseSubPath, pulseGlowPaint);

            // Electric blue mid-pulse
            final pulseMidPaint = Paint()
              ..color = const Color(0xff2563EB).withValues(alpha: 0.75)
              ..style = PaintingStyle.stroke
              ..strokeWidth = 6.0
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3.0);
            canvas.drawPath(pulseSubPath, pulseMidPaint);

            // Radiant white/cyan core
            final pulseCorePaint = Paint()
              ..color = Colors.white
              ..style = PaintingStyle.stroke
              ..strokeWidth = 2.8;
            canvas.drawPath(pulseSubPath, pulseCorePaint);

            // Leading photon head
            if (headPos <= totalLength) {
              final tangent = metric.getTangentForOffset(headPos);
              if (tangent != null) {
                final headHaloPaint = Paint()
                  ..color = const Color(0xff00D9FF).withValues(alpha: 0.60)
                  ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6.0);
                canvas.drawCircle(tangent.position, 6.0, headHaloPaint);

                final headCorePaint = Paint()..color = Colors.white;
                canvas.drawCircle(tangent.position, 3.0, headCorePaint);
              }
            }
          }
        }
      }
    }
  }

  @override
  bool shouldRepaint(covariant _CyanLightRibbonPainter oldDelegate) {
    return oldDelegate.pulseProgress != pulseProgress ||
        oldDelegate.isAnimated != isAnimated;
  }
}

class _AnimatedCyanLightRibbon extends StatefulWidget {
  const _AnimatedCyanLightRibbon();

  @override
  State<_AnimatedCyanLightRibbon> createState() =>
      _AnimatedCyanLightRibbonState();
}

class _AnimatedCyanLightRibbonState extends State<_AnimatedCyanLightRibbon>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 3800),
    );
    _controller.repeat();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final disableAnimations =
        MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    if (disableAnimations && _controller.isAnimating) {
      _controller.stop();
    } else if (!disableAnimations && !_controller.isAnimating) {
      _controller.repeat();
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final disableAnimations =
        MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    if (disableAnimations) {
      return const CustomPaint(
        painter: _CyanLightRibbonPainter(isAnimated: false),
      );
    }

    return AnimatedBuilder(
      animation: _controller,
      builder: (context, _) {
        return CustomPaint(
          painter: _CyanLightRibbonPainter(
            pulseProgress: _controller.value,
            isAnimated: true,
          ),
        );
      },
    );
  }
}

class _NetworkNodeSeed {
  final double baseX;
  final double baseY;
  final double ampX;
  final double ampY;
  final double freq;
  final double phase;
  final double radius;
  final int colorType; // 0: Cyan, 1: Electric Blue, 2: Violet

  const _NetworkNodeSeed(
    this.baseX,
    this.baseY,
    this.ampX,
    this.ampY,
    this.freq,
    this.phase,
    this.radius,
    this.colorType,
  );
}

