class _SafeRouteNavLogoPainter extends CustomPainter {
  final bool showGlow;
  final double glowFactor;

  _SafeRouteNavLogoPainter({this.showGlow = true, this.glowFactor = 1.0});

  @override
  void paint(Canvas canvas, Size size) {
    final scale = size.width / 100.0;
    canvas.save();
    canvas.scale(scale, scale);

    // 1. Sleek Aerodynamic Pin-Shield Silhouette Base
    final outerPinShield = Path()
      ..moveTo(50, 4)
      ..cubicTo(68, 4, 88, 16, 90, 36)
      ..cubicTo(91, 52, 78, 72, 50, 96)
      ..cubicTo(22, 72, 9, 52, 10, 36)
      ..cubicTo(12, 16, 32, 4, 50, 4)
      ..close();

    if (showGlow) {
      final glowPaint = Paint()
        ..color = _NeonTheme.neonCyan.withValues(alpha: (0.32 * glowFactor).clamp(0.0, 1.0))
        ..maskFilter = MaskFilter.blur(BlurStyle.normal, (7 * glowFactor).clamp(3.0, 12.0));
      canvas.drawPath(outerPinShield, glowPaint);
    }

    // Outer Background with Deep Cyber Gradient
    final bgPaint = Paint()
      ..shader = const LinearGradient(
        colors: [Color(0xff06101E), Color(0xff0B1B36), Color(0xff081426)],
        stops: [0.0, 0.6, 1.0],
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
      ).createShader(const Rect.fromLTWH(0, 0, 100, 100));
    canvas.drawPath(outerPinShield, bgPaint);

    // 2. Left Protective Shield Wing (Electric Cyan to Sapphire)
    final leftWing = Path()
      ..moveTo(50, 8)
      ..cubicTo(32, 8, 16, 20, 15, 38)
      ..cubicTo(14, 50, 24, 66, 44, 84)
      ..cubicTo(32, 68, 24, 52, 26, 38)
      ..cubicTo(28, 24, 38, 14, 50, 8)
      ..close();

    final leftWingPaint = Paint()
      ..shader = const LinearGradient(
        colors: [_NeonTheme.neonCyan, Color(0xff2563EB)],
        begin: Alignment.topCenter,
        end: Alignment.bottomLeft,
      ).createShader(const Rect.fromLTWH(15, 8, 35, 76))
      ..style = PaintingStyle.fill;
    canvas.drawPath(leftWing, leftWingPaint);

    // 3. Right Protective Shield Wing (Safe Emerald to Cyan)
    final rightWing = Path()
      ..moveTo(50, 8)
      ..cubicTo(68, 8, 84, 20, 85, 38)
      ..cubicTo(86, 50, 76, 66, 56, 84)
      ..cubicTo(68, 68, 76, 52, 74, 38)
      ..cubicTo(72, 24, 62, 14, 50, 8)
      ..close();

    final rightWingPaint = Paint()
      ..shader = const LinearGradient(
        colors: [_NeonTheme.safeGreen, _NeonTheme.neonCyan],
        begin: Alignment.topCenter,
        end: Alignment.bottomRight,
      ).createShader(const Rect.fromLTWH(50, 8, 35, 76))
      ..style = PaintingStyle.fill;
    canvas.drawPath(rightWing, rightWingPaint);

    // 4. Central Perspective Highway / Route (Emerging from bottom to destination beacon)
    final highwayBed = Path()
      ..moveTo(40, 84)
      ..lineTo(60, 84)
      ..lineTo(54, 36)
      ..lineTo(46, 36)
      ..close();

    final highwayBedPaint = Paint()
      ..shader = const LinearGradient(
        colors: [Color(0xff0F223D), Color(0xff1A365D)],
        begin: Alignment.bottomCenter,
        end: Alignment.topCenter,
      ).createShader(const Rect.fromLTWH(40, 36, 20, 48));
    canvas.drawPath(highwayBed, highwayBedPaint);

    // Dynamic S-curve Route Line
    final centerRoute = Path()
      ..moveTo(50, 82)
      ..cubicTo(45, 68, 55, 52, 50, 36);

    final routeGlow = Paint()
      ..color = _NeonTheme.neonCyan.withValues(alpha: 0.6)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 4.0
      ..strokeCap = StrokeCap.round
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2);
    canvas.drawPath(centerRoute, routeGlow);

    final routeLine = Paint()
      ..shader = const LinearGradient(
        colors: [_NeonTheme.neonCyan, Colors.white, _NeonTheme.safeGreen],
        begin: Alignment.bottomCenter,
        end: Alignment.topCenter,
      ).createShader(const Rect.fromLTWH(45, 36, 10, 46))
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.2
      ..strokeCap = StrokeCap.round;
    canvas.drawPath(centerRoute, routeLine);

    // 5. AI Route Intelligence Waypoint Beacon & Star Apex
    final beaconCenter = const Offset(50, 32);

    // Radiant outer pulse ring
    final beaconPulse = Paint()
      ..color = _NeonTheme.neonCyan.withValues(alpha: 0.3)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.2;
    canvas.drawCircle(beaconCenter, 7.0, beaconPulse);

    // 4-Point AI Intelligence Star Diamond
    final aiStar = Path()
      ..moveTo(50, 24)
      ..quadraticBezierTo(50, 32, 58, 32)
      ..quadraticBezierTo(50, 32, 50, 40)
      ..quadraticBezierTo(50, 32, 42, 32)
      ..quadraticBezierTo(50, 32, 50, 24)
      ..close();

    final aiStarPaint = Paint()
      ..color = Colors.white
      ..style = PaintingStyle.fill;
    canvas.drawPath(aiStar, aiStarPaint);

    final beaconCore = Paint()
      ..color = _NeonTheme.safeGreen
      ..style = PaintingStyle.fill;
    canvas.drawCircle(beaconCenter, 2.5, beaconCore);

    // 6. Crisp Aerodynamic Outer Rim
    final borderPaint = Paint()
      ..shader = const LinearGradient(
        colors: [_NeonTheme.neonCyan, Color(0xff2563EB), _NeonTheme.safeGreen],
        stops: [0.0, 0.5, 1.0],
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
      ).createShader(const Rect.fromLTWH(0, 0, 100, 100))
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.0;
    canvas.drawPath(outerPinShield, borderPaint);

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _SafeRouteNavLogoPainter oldDelegate) =>
      oldDelegate.showGlow != showGlow || oldDelegate.glowFactor != glowFactor;
}

class _NeonScoreRingPainter extends CustomPainter {
  final double scorePercent;
  final bool isDark;
  final Color activeColor;

  _NeonScoreRingPainter({
    required this.scorePercent,
    required this.isDark,
    required this.activeColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final strokeWidth = size.width * 0.088;
    final center = Offset(size.width / 2, size.height / 2);
    final radius = (size.width - strokeWidth) / 2;

    // Ambient radial halo behind the ring disc
    if (isDark && scorePercent > 0) {
      final ambientGlowPaint = Paint()
        ..shader = RadialGradient(
          colors: [
            activeColor.withValues(alpha: 0.15 * (scorePercent / 100).clamp(0.2, 1.0)),
            _NeonTheme.neonCyan.withValues(alpha: 0.06 * (scorePercent / 100).clamp(0.2, 1.0)),
            Colors.transparent,
          ],
          stops: const [0.45, 0.85, 1.0],
        ).createShader(Rect.fromCircle(center: center, radius: radius * 1.35));
      canvas.drawCircle(center, radius * 1.35, ambientGlowPaint);
    }

    // Track Paint
    final trackPaint = Paint()
      ..color = isDark ? const Color(0x2238BDF8) : const Color(0x250D5BD8)
      ..style = PaintingStyle.stroke
      ..strokeWidth = strokeWidth;

    canvas.drawCircle(center, radius, trackPaint);

    if (scorePercent <= 0) return;

    final sweepAngle = 2 * math.pi * (scorePercent / 100).clamp(0.0, 1.0);
    final rect = Rect.fromCircle(center: center, radius: radius);

    // Glow Paint (Dark Mode only to preserve crisp contrast in Light Mode)
    if (isDark) {
      final glowPaint = Paint()
        ..color = activeColor.withValues(alpha: 0.45)
        ..style = PaintingStyle.stroke
        ..strokeWidth = strokeWidth + 4.5
        ..strokeCap = StrokeCap.round
        ..maskFilter = const MaskFilter.blur(BlurStyle.solid, 4.5);
      canvas.drawArc(rect, -math.pi / 2, sweepAngle, false, glowPaint);
    }

    // Active Arc Paint with vibrant neon sweep gradient
    final arcPaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = strokeWidth
      ..strokeCap = StrokeCap.round;

    final List<Color> gradientColors;
    if (isDark) {
      if (activeColor == _NeonTheme.safeGreen ||
          activeColor == const Color(0xff00E59B) ||
          activeColor == const Color(0xff10B981)) {
        gradientColors = [_NeonTheme.neonCyan, activeColor];
      } else {
        gradientColors = [activeColor.withValues(alpha: 0.85), activeColor];
      }
    } else {
      gradientColors = [const Color(0xff2563EB), activeColor];
    }

    arcPaint.shader = SweepGradient(
      startAngle: -math.pi / 2,
      endAngle: 3 * math.pi / 2,
      colors: gradientColors,
      transform: const GradientRotation(-math.pi / 2),
    ).createShader(rect);

    canvas.drawArc(rect, -math.pi / 2, sweepAngle, false, arcPaint);
  }

  @override
  bool shouldRepaint(_NeonScoreRingPainter oldDelegate) {
    return oldDelegate.scorePercent != scorePercent ||
        oldDelegate.isDark != isDark ||
        oldDelegate.activeColor != activeColor;
  }
}

