      _PulsingDestinationMarkerState();
}

class _PulsingDestinationMarkerState extends State<_PulsingDestinationMarker>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<double> _pulse;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1600),
    )..repeat(reverse: true);
    _pulse = Tween<double>(begin: 0.0, end: 1.0).animate(
      CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _pulse,
      builder: (context, _) {
        return SizedBox(
          width: 30,
          height: 38,
          child: Stack(
            clipBehavior: Clip.none,
            alignment: Alignment.topCenter,
            children: [
              // Subtle pulsing halo behind the pin head (centered at x=15, y=15)
              Positioned(
                top: 15.0 - (15.0 + 4.5 * _pulse.value),
                left: 15.0 - (15.0 + 4.5 * _pulse.value),
                child: Container(
                  width: (15.0 + 4.5 * _pulse.value) * 2,
                  height: (15.0 + 4.5 * _pulse.value) * 2,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: _NeonTheme.dangerRed.withValues(
                      alpha: 0.35 * (1.0 - _pulse.value * 0.6),
                    ),
                  ),
                ),
              ),
              // Grounded vector pin body (tip at exact x=15, y=38)
              const CustomPaint(
                size: Size(30, 38),
                painter: _MapPinPainter(pinColor: _NeonTheme.dangerRed),
              ),
              // Centered icon inside pin head
              const Positioned(
                top: 6.5,
                child: Icon(
                  Icons.location_on_rounded,
                  size: 17,
                  color: Colors.white,
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class _AnimatedScoreRing extends StatelessWidget {
  final double? targetScore;
  final bool isDark;
  final Color activeColor;
  final Object? animationKey;

  const _AnimatedScoreRing({
    required this.targetScore,
    required this.isDark,
    required this.activeColor,
    this.animationKey,
  });

  @override
  Widget build(BuildContext context) {
    final disableMotion = MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    const double size = 76.0;

    if (targetScore == null) {
      return Stack(
        alignment: Alignment.center,
        children: [
          CustomPaint(
            size: Size(size, size),
            painter: _NeonScoreRingPainter(
              scorePercent: 0,
              isDark: isDark,
              activeColor: activeColor,
            ),
          ),
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                '--',
                style: TextStyle(
                  fontSize: (size * 0.23).clamp(16.0, 26.0),
                  fontWeight: FontWeight.w900,
                  letterSpacing: -0.5,
                  color: isDark ? Colors.white38 : const Color(0xff94A3B8),
                ),
              ),
              const SizedBox(height: 1),
              Text(
                'DATA PENDING',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: (size * 0.082).clamp(6.0, 9.0),
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.6,
                  color: isDark ? Colors.white38 : const Color(0xff94A3B8),
                ),
              ),
            ],
          ),
        ],
      );
    }

    final scoreVal = targetScore!.clamp(0.0, 100.0);

    return TweenAnimationBuilder<double>(
      key: ValueKey('score_ring_${scoreVal.toStringAsFixed(1)}_${animationKey ?? key ?? ""}'),
      tween: Tween<double>(begin: disableMotion ? scoreVal : 0.0, end: scoreVal),
      duration: disableMotion ? Duration.zero : const Duration(milliseconds: 950),
      curve: Curves.easeOutCubic,
      builder: (context, animatedScore, child) {
        final glowFactor = (animatedScore / 100.0).clamp(0.0, 1.0);
        final glowAlpha = ((isDark ? 0.24 : 0.14) * glowFactor).clamp(0.04, 0.25);

        return Stack(
          alignment: Alignment.center,
          children: [
            // Ambient outer glow container
            Container(
              width: size - 4,
              height: size - 4,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                boxShadow: [
                  BoxShadow(
                    color: activeColor.withValues(alpha: glowAlpha),
                    blurRadius: 16,
                    spreadRadius: 2,
                  ),
                  if (isDark)
                    BoxShadow(
                      color: _NeonTheme.neonCyan.withValues(alpha: glowAlpha * 0.5),
                      blurRadius: 22,
                      spreadRadius: -2,
                    ),
                ],
              ),
            ),
            CustomPaint(
              size: Size(size, size),
              painter: _NeonScoreRingPainter(
                scorePercent: animatedScore,
                isDark: isDark,
                activeColor: activeColor,
              ),
            ),
            Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  '${animatedScore.round()}%',
                  style: TextStyle(
                    fontSize: (size * 0.224).clamp(16.0, 26.0),
                    fontWeight: FontWeight.w900,
                    letterSpacing: -0.5,
                    color: isDark ? Colors.white : const Color(0xff0F172A),
                  ),
                ),
                Text(
                  'SAFETY SCORE',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontSize: (size * 0.086).clamp(6.2, 9.0),
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.5,
                    color: isDark ? _NeonTheme.neonCyan : const Color(0xff2563EB),
                  ),
                ),
              ],
            ),
          ],
        );
      },
    );
  }
}

class AnimatedCounterText extends StatelessWidget {
  final num value;
  final String suffix;
  final String prefix;
  final TextStyle? style;
  final Duration duration;
  final Curve curve;

  const AnimatedCounterText({
    super.key,
    required this.value,
    this.suffix = '',
    this.prefix = '',
    this.style,
    this.duration = const Duration(milliseconds: 650),
    this.curve = Curves.easeOutCubic,
  });

  @override
  Widget build(BuildContext context) {
    final disableAnimations = MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    if (disableAnimations) {
      final text = value is int ? '$prefix$value$suffix' : '$prefix${value.toStringAsFixed(1)}$suffix';
      return Text(text, style: style);
    }

    return TweenAnimationBuilder<double>(
      tween: Tween<double>(begin: 0.0, end: value.toDouble()),
      duration: duration,
      curve: curve,
      builder: (context, val, child) {
        final display = value is int ? val.round().toString() : val.toStringAsFixed(1);
        return Text('$prefix$display$suffix', style: style);
      },
    );
  }
}

class _StaggeredEntrance extends StatefulWidget {
  final Widget child;
  final int delayMs;
  final Offset slideOffset;
  final bool animateScale;
  final Object? trigger;
  const _StaggeredEntrance({
    super.key,
    required this.child,
    this.delayMs = 0,
    this.slideOffset = const Offset(0, 16.0),
    this.animateScale = false,
    this.trigger,
  });

  static const Duration _duration = Duration(milliseconds: 360);

  @override
  State<_StaggeredEntrance> createState() => _StaggeredEntranceState();
}

class _StaggeredEntranceState extends State<_StaggeredEntrance> {
  bool _isHovered = false;

  @override
  Widget build(BuildContext context) {
    final disableAnimations = MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    final isDesktop = MediaQuery.sizeOf(context).width >= 1050;

    final staggeredContent = TweenAnimationBuilder<double>(
      key: ValueKey('stagger_${widget.trigger ?? widget.key ?? ""}_${widget.delayMs}'),
      tween: Tween<double>(begin: disableAnimations ? 1.0 : 0.0, end: 1.0),
      duration: disableAnimations
          ? Duration.zero
          : (_StaggeredEntrance._duration + Duration(milliseconds: widget.delayMs)),
      curve: Curves.easeOutCubic,
      builder: (context, progress, childWidget) {
        if (disableAnimations) return childWidget!;

        final totalMs = _StaggeredEntrance._duration.inMilliseconds + widget.delayMs;
        final startFrac = totalMs > 0 ? (widget.delayMs / totalMs) : 0.0;
        final effectiveFrac = progress <= startFrac
            ? 0.0
            : ((progress - startFrac) / (1.0 - startFrac)).clamp(0.0, 1.0);
        final curvedVal = Curves.easeOutCubic.transform(effectiveFrac);

        final dyPixels = widget.slideOffset.dy.abs() <= 1.0
            ? widget.slideOffset.dy * 450.0
            : widget.slideOffset.dy;
        final dxPixels = widget.slideOffset.dx.abs() <= 1.0
            ? widget.slideOffset.dx * 450.0
            : widget.slideOffset.dx;

        Widget result = Opacity(
          opacity: curvedVal,
          child: Transform.translate(
            offset: Offset(
              dxPixels * (1.0 - curvedVal),
              dyPixels * (1.0 - curvedVal),
            ),
            child: childWidget,
          ),
        );
        if (widget.animateScale) {
          result = Transform.scale(
            scale: 0.97 + (0.03 * curvedVal),
            child: result,
          );
        }
        return result;
      },
      child: widget.child,
    );

    if (!isDesktop || disableAnimations) {
      return staggeredContent;
    }

    return MouseRegion(
      onEnter: (_) => setState(() => _isHovered = true),
      onExit: (_) => setState(() => _isHovered = false),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 220),
        curve: Curves.easeOutCubic,
        transform: Matrix4.translationValues(0.0, _isHovered ? -2.5 : 0.0, 0.0),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(16),
          border: _isHovered
              ? Border.all(
                  color: const Color(0xff00D9FF).withValues(alpha: 0.28),
                  width: 1.0,
                )
              : Border.all(
                  color: Colors.transparent,
                  width: 1.0,
                ),
          boxShadow: _isHovered
              ? [
                  BoxShadow(
                    color: const Color(0xff00E5FF).withValues(alpha: 0.20),
                    blurRadius: 16,
                    spreadRadius: 1.0,
                    offset: const Offset(0, 4),
                  ),
                ]
              : null,
        ),
        child: staggeredContent,
      ),
    );
  }
}

class _InteractivePressButton extends StatefulWidget {
  final Widget child;
  final VoidCallback? onPressed;

  const _InteractivePressButton({
    required this.child,
    this.onPressed,
  });

  @override
  State<_InteractivePressButton> createState() => _InteractivePressButtonState();
}

class _InteractivePressButtonState extends State<_InteractivePressButton> {
  bool _isPressed = false;
  bool _isHovered = false;

  @override
  Widget build(BuildContext context) {
    final double targetScale = _isPressed
        ? 0.97
        : (_isHovered ? 1.01 : 1.0);

    return MouseRegion(
      cursor: SystemMouseCursors.click,
      onEnter: (_) => setState(() => _isHovered = true),
      onExit: (_) => setState(() => _isHovered = false),
      child: GestureDetector(
        onTapDown: (_) => setState(() => _isPressed = true),
        onTapUp: (_) {
          setState(() => _isPressed = false);
          widget.onPressed?.call();
        },
        onTapCancel: () => setState(() => _isPressed = false),
        child: AnimatedScale(
          scale: targetScale,
          duration: Duration(milliseconds: _isPressed ? 100 : 160),
          curve: Curves.easeOutCubic,
          child: widget.child,
        ),
      ),
    );
  }
}

class _BreathingGlowBorderCard extends StatefulWidget {
  final Widget child;
  final bool isDarkMode;

  const _BreathingGlowBorderCard({
    required this.child,
    required this.isDarkMode,
  });

  @override
  State<_BreathingGlowBorderCard> createState() => _BreathingGlowBorderCardState();
}

class _BreathingGlowBorderCardState extends State<_BreathingGlowBorderCard>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<double> _glow;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2800),
    );
    if (widget.isDarkMode) {
      _ctrl.repeat(reverse: true);
    }
    _glow = Tween<double>(begin: 0.12, end: 0.38).animate(
      CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut),
    );
  }

  @override
  void didUpdateWidget(covariant _BreathingGlowBorderCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.isDarkMode && !_ctrl.isAnimating) {
      _ctrl.repeat(reverse: true);
    } else if (!widget.isDarkMode && _ctrl.isAnimating) {
      _ctrl.stop();
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final disableAnimations = MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    if (disableAnimations || !widget.isDarkMode) {
      return widget.child;
    }

    return AnimatedBuilder(
      animation: _glow,
      builder: (context, _) {
        return Container(
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(16),
            boxShadow: [
              BoxShadow(
                color: const Color(0xff00D9FF).withValues(alpha: _glow.value * 0.45),
                blurRadius: 10 + (_glow.value * 12),
                spreadRadius: 0.5,
              ),
            ],
          ),
          child: widget.child,
        );
      },
    );
  }
}

/// Reusable premium glassmorphic container for SafeRoute TN 2.0.
///
/// Features:
/// - Translucent deep navy base (#020B1C / #06152D) for dark mode.
/// - Crisp translucent white for light mode.
/// - Subtle backdrop blur (10-14px) clipped cleanly to rounded bounds.
/// - Thin translucent cyan border (#00D9FF with alpha) with subtle specular shine.
/// - Soft shadow that does not get clipped by BackdropFilter.
/// - Optional interactive hover glow and scale.
/// - Respects [MediaQuery.disableAnimations] for accessibility.
typedef _GlassCard = GlassCard;

class GlassCard extends StatefulWidget {
  final Widget child;
  final EdgeInsetsGeometry? padding;
  final EdgeInsetsGeometry? margin;
  final double? width;
  final double? height;
  final BoxConstraints? constraints;
  final BorderRadius? borderRadius;
  final double blurSigma;
  final Color? backgroundColor;
  final Gradient? gradient;
  final BoxBorder? border;
  final List<BoxShadow>? boxShadow;
  final Clip clipBehavior;
  final bool enableHover;
  final VoidCallback? onTap;

  const GlassCard({
    super.key,
    required this.child,
    this.padding,
    this.margin,
    this.width,
    this.height,
    this.constraints,
    this.borderRadius,
    this.blurSigma = 12.0,
    this.backgroundColor,
    this.gradient,
    this.border,
    this.boxShadow,
    this.clipBehavior = Clip.antiAlias,
    this.enableHover = false,
    this.onTap,
  });

  @override
  State<GlassCard> createState() => _GlassCardState();
}

class _GlassCardState extends State<GlassCard> {
  bool _isHovered = false;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final disableAnimations = MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    final effectiveRadius = widget.borderRadius ?? BorderRadius.circular(20);

    // Deep navy base (#020B1C), secondary navy (#06152D), or crisp white
    final defaultBgColor = isDark
        ? const Color(0xC206152D)
        : const Color(0xE8FFFFFF);

    final defaultGradient = isDark
        ? const LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              Color(0xCC0E2242), // Top-left subtle electric-navy highlight
              Color(0xBD06152D), // Center deep translucent navy
              Color(0xD1020B1C), // Bottom-right deep base
            ],
            stops: [0.0, 0.55, 1.0],
          )
        : const LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              Color(0xF5FFFFFF),
              Color(0xEBFAFBFD),
            ],
          );

    final defaultBorder = Border.all(
      color: isDark
          ? (_isHovered
              ? const Color(0x6000D9FF)
              : const Color(0x3500D9FF))
          : (_isHovered
              ? const Color(0x602563EB)
              : const Color(0xffE2E8F0)),
      width: 1.0,
    );

    final defaultShadows = [
      BoxShadow(
        color: Colors.black.withValues(alpha: isDark ? 0.32 : 0.05),
        blurRadius: _isHovered ? 26 : 20,
        offset: Offset(0, _isHovered ? 8 : 6),
      ),
      if (isDark)
        BoxShadow(
          color: const Color(0xff00D9FF).withValues(alpha: _isHovered ? 0.08 : 0.04),
          blurRadius: _isHovered ? 18 : 12,
          spreadRadius: 0,
        ),
    ];

    Widget innerContent = AnimatedContainer(
      duration: const Duration(milliseconds: 200),
      curve: Curves.easeOutCubic,
      padding: widget.padding,
      decoration: BoxDecoration(
        color: widget.gradient == null
            ? (widget.backgroundColor ?? defaultBgColor)
            : null,
        gradient: widget.gradient ??
            (widget.backgroundColor != null ? null : defaultGradient),
        borderRadius: effectiveRadius,
        border: widget.border ?? defaultBorder,
      ),
      child: widget.child,
    );

    if (widget.blurSigma > 0 && !disableAnimations) {
      innerContent = ClipRRect(
        borderRadius: effectiveRadius,
        clipBehavior: widget.clipBehavior,
        child: BackdropFilter(
          filter: ImageFilter.blur(
            sigmaX: widget.blurSigma,
            sigmaY: widget.blurSigma,
          ),
          child: innerContent,
        ),
      );
    } else {
      innerContent = ClipRRect(
        borderRadius: effectiveRadius,
        clipBehavior: widget.clipBehavior,
        child: innerContent,
      );
    }

    Widget card = Container(
      width: widget.width,
      height: widget.height,
      constraints: widget.constraints,
      margin: widget.margin,
      decoration: BoxDecoration(
        borderRadius: effectiveRadius,
        boxShadow: widget.boxShadow ?? defaultShadows,
      ),
      child: innerContent,
    );

    if (!widget.enableHover && widget.onTap == null) {
      return card;
    }

    return MouseRegion(
      cursor: widget.onTap != null ? SystemMouseCursors.click : MouseCursor.defer,
      onEnter: widget.enableHover ? (_) => setState(() => _isHovered = true) : null,
      onExit: widget.enableHover ? (_) => setState(() => _isHovered = false) : null,
      child: widget.onTap != null
          ? GestureDetector(onTap: widget.onTap, child: card)
          : card,
    );
  }
}

