class SafeRoutePageHeader extends StatelessWidget {
  final String title;
  final String subtitle;
  final String? badge;
  final Color? badgeColor;
  final IconData? icon;
  final Widget? trailing;

  const SafeRoutePageHeader({
    super.key,
    required this.title,
    required this.subtitle,
    this.badge,
    this.badgeColor,
    this.icon,
    this.trailing,
  });

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final effectiveBadgeColor = badgeColor ?? _NeonTheme.neonCyan;

    return Padding(
      padding: const EdgeInsets.only(bottom: 24),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final isCompact = constraints.maxWidth < 680;
          final headerContent = Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              if (badge != null) ...[
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                  decoration: BoxDecoration(
                    color: effectiveBadgeColor.withValues(alpha: 0.14),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: effectiveBadgeColor.withValues(alpha: 0.40),
                      width: 1.0,
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (icon != null) ...[
                        Icon(icon, size: 12, color: effectiveBadgeColor),
                        const SizedBox(width: 5),
                      ],
                      Text(
                        badge!,
                        style: TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.w800,
                          letterSpacing: 0.8,
                          color: effectiveBadgeColor,
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 10),
              ],
              Text(
                title,
                style: TextStyle(
                  fontSize: isCompact ? 22 : 28,
                  fontWeight: FontWeight.w900,
                  letterSpacing: -0.6,
                  color: isDark ? _NeonTheme.textPrimaryDark : _NeonTheme.textPrimaryLight,
                ),
              ),
              const SizedBox(height: 6),
              Text(
                subtitle,
                style: TextStyle(
                  fontSize: isCompact ? 12.5 : 14,
                  height: 1.45,
                  fontWeight: FontWeight.w500,
                  color: isDark ? _NeonTheme.textSecondaryDark : _NeonTheme.textSecondaryLight,
                ),
              ),
            ],
          );

          if (trailing == null) return headerContent;

          if (isCompact) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                headerContent,
                const SizedBox(height: 16),
                trailing!,
              ],
            );
          }

          return Row(
            crossAxisAlignment: CrossAxisAlignment.end,
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Expanded(child: headerContent),
              const SizedBox(width: 20),
              trailing!,
            ],
          );
        },
      ),
    );
  }
}

