      safetyScore: (json['safety_score'] as num?)?.toDouble(),
      routeIndex: (json['route_index'] as num?)?.toInt() ?? 0,
      vehicleMode: json['vehicle_mode'] as String? ?? 'Car',
      travelTimeMode: json['travel_time_mode'] as String? ?? 'Day',
