          ? DateTime.tryParse(json['created_at'] as String) ?? DateTime.now()
          : DateTime.now(),
      trafficStatus: json['traffic_status'] as String?,
      weatherScore: (json['weather_score'] as num?)?.toDouble(),
      routeLabel: json['route_label'] as String?,
    );
  }
}

