  Future<_BlackspotRouteAssessment> assessRouteBlackspots(
    List<LatLng> routePoints,
    List<_OsmRoadSegment>? segments,
  ) async {
    // 1. Try backend route-level blackspot check
    try {
      final url = Uri.parse('$_trafficBackendBaseUrl/check-blackspot');
      final resp = await http
          .post(
            url,
            headers: const {'Content-Type': 'application/json'},
            body: jsonEncode({
              'points': [
                for (final p in routePoints) [p.latitude, p.longitude],
              ],
              'radius_meters': 1000.0,
            }),
          )
          .timeout(const Duration(seconds: 6));

      if (resp.statusCode == 200) {
        final decoded = jsonDecode(resp.body);
        if (decoded is Map<String, dynamic> &&
            decoded['verified_dataset_available'] == true) {
          final matchesCount = (decoded['matches_count'] as num?)?.toInt() ?? 0;
          final totalRecords =
              (decoded['verified_dataset_count'] as num?)?.toInt() ?? 8;
          final score = matchesCount == 0
              ? 100.0
              : math.max(0.0, 80.0 - matchesCount * 25.0);
          return _BlackspotRouteAssessment(
            clearSampleScore: score,
            detectedBlackspots: matchesCount,
            successfulSamples: 1,
            segmentsChecked: segments?.length ?? 1,
            verifiedRecordCount: totalRecords,
            segmentResults: const [],
            unavailableReason: matchesCount == 0
                ? 'Verified accident data: No matched blackspots'
                : null,
          );
        }
      }
    } catch (_) {}

    // 2. Direct client-side verification against authentic MoRTH / NHAI blackspots
    if (routePoints.isNotEmpty) {
      var matches = 0;
      for (final spot in _authenticVerifiedBlackspots) {
        final isNear = routePoints.any(
          (pt) => _distanceBetweenMeters(pt, spot.location) <= 1000.0,
        );
        if (isNear) matches++;
      }
      final score = matches == 0 ? 100.0 : math.max(0.0, 80.0 - matches * 25.0);
      return _BlackspotRouteAssessment(
        clearSampleScore: score,
        detectedBlackspots: matches,
        successfulSamples: 1,
        segmentsChecked: segments?.length ?? 1,
        verifiedRecordCount: _authenticVerifiedBlackspots.length,
        segmentResults: const [],
        unavailableReason: matches == 0
            ? 'Verified accident data: No matched blackspots'
            : null,
      );
    }

    return assessOsmSegmentBlackspots(segments);
  }

  Future<_BlackspotRouteAssessment> assessOsmSegmentBlackspots(
    List<_OsmRoadSegment>? segments,
  ) async {
    if (segments == null || segments.isEmpty) {
      return const _BlackspotRouteAssessment(
        clearSampleScore: null,
        detectedBlackspots: null,
        successfulSamples: 0,
        segmentsChecked: 0,
        verifiedRecordCount: 0,
        segmentResults: [],
        unavailableReason: 'No matched OSM road segments are available.',
      );
    }

    final segmentResults = <_OsmSegmentBlackspotResult>[];
    var batchSuccess = false;

    // Try high-performance batch check first
    try {
      final batchUrl = Uri.parse('$_trafficBackendBaseUrl/check-blackspot');
      final batchResponse = await http
          .post(
            batchUrl,
            headers: const {'Content-Type': 'application/json'},
            body: jsonEncode({
              'segments': [
                for (final seg in segments)
                  {
                    'osm_id': seg.osmId,
                    'lat': seg.routeMatchPoint.latitude,
                    'lon': seg.routeMatchPoint.longitude,
                    'radius_meters': 1000.0,
                  },
              ],
            }),
          )
          .timeout(const Duration(seconds: 15));

      if (batchResponse.statusCode == 200) {
        final decoded = jsonDecode(batchResponse.body);
        if (decoded is Map<String, dynamic> &&
            decoded['verified_dataset_available'] == true &&
            decoded['results'] is List) {
          final resultsList = decoded['results'] as List;
          final byOsmId = <int, Map<String, dynamic>>{};
          for (final item in resultsList) {
            if (item is Map<String, dynamic> && item['osm_id'] is num) {
              byOsmId[(item['osm_id'] as num).toInt()] = item;
            }
          }
          if (byOsmId.isNotEmpty) {
            for (final seg in segments) {
              final res = byOsmId[seg.osmId];
              if (res != null && res['data_available'] == true) {
                final rawRecords = res['nearby_blackspots'];
                final records = <Map<String, dynamic>>[];
                if (rawRecords is List) {
                  for (final r in rawRecords) {
                    if (r is Map<String, dynamic> &&
                        _isVerifiedBlackspotRecord(r)) {
                      records.add(r);
                    }
                  }
                }
                segmentResults.add(
                  _OsmSegmentBlackspotResult(
                    osmId: seg.osmId,
                    dataAvailable: true,
                    verifiedRecords: List.unmodifiable(records),
                  ),
                );
              } else {
                segmentResults.add(
                  _OsmSegmentBlackspotResult(
                    osmId: seg.osmId,
                    dataAvailable: false,
                    verifiedRecords: const [],
                  ),
                );
              }
            }
            batchSuccess = true;
          }
        }
      }
    } catch (e) {
      debugPrint(
        'BATCH BLACKSPOT CHECK ERROR: $e (Falling back to individual checks)',
      );
    }

    if (!batchSuccess) {
      segmentResults.clear();
      const segmentsPerBatch = 8;
      for (var start = 0; start < segments.length; start += segmentsPerBatch) {
        final batch = segments.skip(start).take(segmentsPerBatch);
        final results = await Future.wait(
          batch.map((segment) async {
            final response = await checkBlackspotProximity(
              segment.routeMatchPoint.latitude,
              segment.routeMatchPoint.longitude,
              radiusMeters: 1000,
            );
            return (segment: segment, response: response);
          }),
        );

        for (final result in results) {
          final response = result.response;
          if (response == null) {
            segmentResults.add(
              _OsmSegmentBlackspotResult(
                osmId: result.segment.osmId,
                dataAvailable: false,
                verifiedRecords: const [],
              ),
            );
            continue;
          }

          final datasetAvailable = response['verified_dataset_available'];
          final datasetRecordCount = response['verified_dataset_count'];
          if (datasetAvailable is! bool ||
              datasetRecordCount is! num ||
              datasetAvailable != (datasetRecordCount > 0)) {
            segmentResults.add(
              _OsmSegmentBlackspotResult(
                osmId: result.segment.osmId,
                dataAvailable: false,
                verifiedRecords: const [],
              ),
            );
            debugPrint(
              'VERIFIED ACCIDENT DATA INVALID RESPONSE: '
              'OSM way ${result.segment.osmId} has invalid dataset status.',
            );
            continue;
          }
          if (!datasetAvailable) {
            segmentResults.add(
              _OsmSegmentBlackspotResult(
                osmId: result.segment.osmId,
                dataAvailable: false,
                verifiedRecords: const [],
              ),
            );
            debugPrint(
              'VERIFIED ACCIDENT DATA UNAVAILABLE: '
              'OSM way ${result.segment.osmId}; backend has no loaded '
              'GPS-verified records.',
            );
            continue;
          }

          final rawRecords = response['nearby_blackspots'];
          final rawMatchCount = response['matches_count'];
          final rawNearBlackspot = response['is_near_blackspot'];
          if (rawRecords is! List ||
              rawMatchCount is! num ||
              rawMatchCount != rawRecords.length ||
              rawNearBlackspot is! bool ||
              rawNearBlackspot != rawRecords.isNotEmpty) {
            segmentResults.add(
              _OsmSegmentBlackspotResult(
                osmId: result.segment.osmId,
                dataAvailable: false,
                verifiedRecords: const [],
              ),
            );
            debugPrint(
              'VERIFIED ACCIDENT DATA INVALID RESPONSE: '
              'OSM way ${result.segment.osmId} has inconsistent match fields.',
            );
            continue;
          }

          final verifiedRecords = <Map<String, dynamic>>[];
          var invalidRecord = false;
          for (final rawRecord in rawRecords) {
            if (rawRecord is! Map<String, dynamic> ||
                !_isVerifiedBlackspotRecord(rawRecord)) {
              invalidRecord = true;
              break;
            }
            verifiedRecords.add(rawRecord);
          }
          if (invalidRecord) {
            segmentResults.add(
              _OsmSegmentBlackspotResult(
                osmId: result.segment.osmId,
                dataAvailable: false,
                verifiedRecords: const [],
              ),
            );
            debugPrint(
              'VERIFIED ACCIDENT DATA INVALID RESPONSE: '
              'OSM way ${result.segment.osmId} has a malformed blackspot.',
            );
            continue;
          }

          segmentResults.add(
            _OsmSegmentBlackspotResult(
              osmId: result.segment.osmId,
              dataAvailable: true,
              verifiedRecords: List.unmodifiable(verifiedRecords),
            ),
          );
        }
      }
    }

    final checkedSegments = segmentResults.length;
    final successfulChecks = segmentResults
        .where((result) => result.dataAvailable)
        .length;
    final matchedSegments = segmentResults
        .where((result) => result.verifiedRecords.isNotEmpty)
        .length;
    // Deduplicate blackspots across segments by authentic blackspot ID
    final uniqueBlackspotIds = <String>{};
    for (final result in segmentResults) {
      for (final record in result.verifiedRecords) {
        final id = record['blackspot_id']?.toString() ??
            record['id']?.toString() ??
            ',';
        uniqueBlackspotIds.add(id);
      }
    }
    final verifiedRecordCount = segmentResults.fold<int>(
      0,
      (total, result) => total + result.verifiedRecords.length,
    );
    double? accidentScore;
    String? unavailableReason;
    if (successfulChecks == 0) {
      accidentScore = null;
      unavailableReason =
          'Verified accident/blackspot backend data unavailable for '
          '$checkedSegments checked segments.';
    } else {
      var weightedScoreSum = 0.0;
      var totalWeightLength = 0.0;
      for (var i = 0; i < segments.length && i < segmentResults.length; i++) {
        final result = segmentResults[i];
        if (!result.dataAvailable) continue;
        final segment = segments[i];
        final length = _segmentGeometryLengthMeters(segment);
        final recordCount = result.verifiedRecords.length;
        // Segment accident risk:
        // A segment with a verified blackspot reduces its accident safety factor.
        // A segment without a verified blackspot is NOT automatically 100% safe (baseline 80%).
        final segmentScore = recordCount == 0
            ? 80.0
            : math.max(0.0, 80.0 - (recordCount * 40.0));
        weightedScoreSum += segmentScore * length;
        totalWeightLength += length;
      }
      if (totalWeightLength > 0) {
        accidentScore = weightedScoreSum / totalWeightLength;
        unavailableReason = null;
      } else {
        accidentScore = null;
        unavailableReason = 'Verified accident/blackspot backend unavailable.';
      }
    }

    debugPrint(
      'VERIFIED ACCIDENT DATA: matched OSM segments=${segments.length}, '
      'segments checked=$checkedSegments, '
      'segments with verified matches=$matchedSegments, '
      'successful backend responses=$successfulChecks, '
      'verified records=$verifiedRecordCount.',
    );
    debugPrint(
      'ACCIDENT FACTOR: ${accidentScore?.toStringAsFixed(1) ?? 'Unavailable'}'
      '${unavailableReason == null ? '' : ' — $unavailableReason'}',
    );

    return _BlackspotRouteAssessment(
      clearSampleScore: accidentScore,
      detectedBlackspots: uniqueBlackspotIds.length,
      successfulSamples: successfulChecks,
      segmentsChecked: checkedSegments,
      verifiedRecordCount: verifiedRecordCount,
      segmentResults: segmentResults,
      unavailableReason: unavailableReason,
    );
  }

  bool _isVerifiedBlackspotRecord(Map<String, dynamic> record) {
    final blackspotId = record['blackspot_id'];
    final latitude = record['latitude'];
    final longitude = record['longitude'];
    return blackspotId is String &&
        blackspotId.isNotEmpty &&
        latitude is num &&
        longitude is num;
  }

  List<LatLng> _sampleRouteForOsm(List<LatLng> routePoints) {
    if (routePoints.length <= 1) return List.of(routePoints);

    final cumulativeMeters = <double>[0];
    for (var i = 1; i < routePoints.length; i++) {
      cumulativeMeters.add(
        cumulativeMeters.last +
            _distanceBetweenMeters(routePoints[i - 1], routePoints[i]),
      );
    }

    final totalMeters = cumulativeMeters.last;
    if (totalMeters == 0) return [routePoints.first];

    final sampleCount = math
        .min(_maxOsmRouteSamples, math.max(2, (totalMeters / 300).ceil() + 1))
        .toInt();
    final samples = <LatLng>[];
    var segmentIndex = 0;

    for (var sampleIndex = 0; sampleIndex < sampleCount; sampleIndex++) {
      final targetMeters = totalMeters * sampleIndex / (sampleCount - 1);
      while (segmentIndex < cumulativeMeters.length - 2 &&
          cumulativeMeters[segmentIndex + 1] < targetMeters) {
        segmentIndex++;
      }

      final segmentStartMeters = cumulativeMeters[segmentIndex];
      final segmentLength =
          cumulativeMeters[segmentIndex + 1] - segmentStartMeters;
      final fraction = segmentLength == 0
          ? 0.0
          : ((targetMeters - segmentStartMeters) / segmentLength)
                .clamp(0.0, 1.0)
                .toDouble();
      final start = routePoints[segmentIndex];
      final end = routePoints[segmentIndex + 1];
      samples.add(
        LatLng(
          start.latitude + (end.latitude - start.latitude) * fraction,
          start.longitude + (end.longitude - start.longitude) * fraction,
        ),
      );
    }
    return samples;
  }

  double _distanceBetweenMeters(LatLng first, LatLng second) {
    const earthRadiusMeters = 6371000.0;
    final firstLatitude = first.latitude * math.pi / 180;
    final secondLatitude = second.latitude * math.pi / 180;
    final latitudeDelta = secondLatitude - firstLatitude;
    final longitudeDelta = (second.longitude - first.longitude) * math.pi / 180;
    final a =
        math.pow(math.sin(latitudeDelta / 2), 2) +
        math.cos(firstLatitude) *
            math.cos(secondLatitude) *
            math.pow(math.sin(longitudeDelta / 2), 2);
    return earthRadiusMeters * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a));
  }

  String _roadSegmentQuery(List<LatLng> routeSamples) {
    final clauses = routeSamples
        .map(
          (point) =>
              'way["highway"]'
              '(around:${_osmQueryRadiusMeters.toInt()},'
              '${point.latitude},${point.longitude});',
        )
        .join('\n');
    return '[out:json][timeout:25];($clauses);out tags geom;';
  }

  Future<Map<String, dynamic>?> _fetchOverpassChunk(String query) async {
    const endpoints = [
      'overpass.openstreetmap.fr',
      'overpass-api.de',
      'overpass.kumi.systems',
    ];

    for (final endpoint in endpoints) {
      try {
        final response = await http
            .post(
              Uri.parse('https://$endpoint/api/interpreter'),
              headers: kIsWeb
                  ? {'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'}
                  : {
                      'Content-Type':
                          'application/x-www-form-urlencoded; charset=UTF-8',
                      'User-Agent': 'SafeRouteTN/1.0',
                    },
              body: {'data': query},
            )
            .timeout(const Duration(seconds: 12));

        if (response.statusCode == 200) {
          final data = jsonDecode(response.body);
          if (data is Map<String, dynamic>) return data;
          debugPrint(
            'OSM road query failed at $endpoint: invalid JSON response.',
          );
          continue;
        }

        if (response.statusCode == 504) {
          debugPrint('OSM road query failed at $endpoint: HTTP 504.');
          debugPrint('OSM road query failed: HTTP 504');
          debugPrint(
            'OSM road data unavailable for this route; continuing without OSM segment tags.',
          );
          _lastOverpassFailureTime = DateTime.now();
          // HTTP 504 is a gateway timeout. Fail gracefully without hammering further endpoints.
          return null;
        }

        if (response.statusCode == 429 ||
            response.statusCode == 502 ||
            response.statusCode == 503) {
          debugPrint(
            'OSM road query failed at $endpoint: HTTP ${response.statusCode}.',
          );
          debugPrint(
            'OSM road data unavailable for this route; continuing without OSM segment tags.',
          );
          _lastOverpassFailureTime = DateTime.now();
          return null;
        }

        debugPrint(
          'OSM road query failed at $endpoint: HTTP ${response.statusCode}.',
        );
      } on TimeoutException {
        debugPrint('OSM road query timed out at $endpoint.');
        debugPrint(
          'OSM road data unavailable for this route; continuing without OSM segment tags.',
        );
        _lastOverpassFailureTime = DateTime.now();
        return null;
      } catch (error) {
        debugPrint('OSM road query failed at $endpoint: $error');
      }
    }
    _lastOverpassFailureTime = DateTime.now();
    return null;
  }

  LatLng? _matchedRoadPoint(
    List<LatLng> roadGeometry,
    List<LatLng> routeSamples,
    double maxDistanceMeters,
  ) {
    LatLng? closestPoint;
    var closestDistance = double.infinity;
    for (final routePoint in routeSamples) {
      final latitudeRadians = routePoint.latitude * math.pi / 180;
      final longitudeScale = 111320 * math.cos(latitudeRadians);
      for (var i = 1; i < roadGeometry.length; i++) {
        final first = roadGeometry[i - 1];
        final second = roadGeometry[i];
        final firstX =
            (first.longitude - routePoint.longitude) * longitudeScale;
        final firstY = (first.latitude - routePoint.latitude) * 110540;
        final secondX =
            (second.longitude - routePoint.longitude) * longitudeScale;
        final secondY = (second.latitude - routePoint.latitude) * 110540;
        final deltaX = secondX - firstX;
        final deltaY = secondY - firstY;
        final segmentLengthSquared = deltaX * deltaX + deltaY * deltaY;
        final projection = segmentLengthSquared == 0
            ? 0.0
            : (-(firstX * deltaX + firstY * deltaY) / segmentLengthSquared)
                  .clamp(0.0, 1.0)
                  .toDouble();
        final nearestX = firstX + projection * deltaX;
        final nearestY = firstY + projection * deltaY;
        final distance = math.sqrt(nearestX * nearestX + nearestY * nearestY);
        if (distance < closestDistance) {
          closestDistance = distance;
          closestPoint = LatLng(
            routePoint.latitude + nearestY / 110540,
            routePoint.longitude + nearestX / longitudeScale,
          );
        }
      }
    }
    return closestDistance <= maxDistanceMeters ? closestPoint : null;
  }

  List<LatLng> _routeSamples(List<LatLng> routePoints) {
    if (routePoints.isEmpty) return [];
    return {
      routePoints.first,
      routePoints[routePoints.length ~/ 2],
      routePoints.last,
    }.toList();
  }

  Future<double?> getRoadConditionScore(List<LatLng> routePoints) async {
    final samples = _routeSamples(routePoints);
    if (samples.isEmpty) return null;

    int successfulSamples = 0;
    int taggedRoads = 0;
    int goodRoads = 0;

    for (final point in samples) {
      final query =
          '''
[out:json][timeout:15];
way["highway"]["surface"](around:300,${point.latitude},${point.longitude});
out tags;
''';
      try {
        final response = await http
            .get(
              Uri.parse(
                'https://overpass-api.de/api/interpreter?data='
                '${Uri.encodeComponent(query)}',
              ),
            )
            .timeout(const Duration(seconds: 20));
        if (response.statusCode != 200) continue;

        successfulSamples++;
        final data = jsonDecode(response.body);
        final elements = data['elements'] as List<dynamic>? ?? [];
        for (final element in elements) {
          final surface = (element['tags'] as Map<String, dynamic>?)?['surface']
              ?.toString()
              .toLowerCase();
          if (surface == null) continue;
          taggedRoads++;
          if ({
            'asphalt',
            'concrete',
            'paved',
            'paving_stones',
            'sett',
          }.contains(surface)) {
            goodRoads++;
          }
        }
      } catch (e) {
        debugPrint('ROAD CONDITION QUERY ERROR: $e');
      }
    }

    if (successfulSamples == 0 || taggedRoads == 0) return null;
    return (goodRoads / taggedRoads) * 100;
  }

  Future<_FacilitySearchResult> _getFacilitiesForRoute(
    List<LatLng> routePoints,
    List<_FacilityCategory> categories,
  ) async {
    debugPrint('FACILITY DEBUG');
    debugPrint('Route points: ${routePoints.length}');
    debugPrint(
      'FACILITY CATEGORY: ${categories.map((category) => category.label).join(', ')}',
    );
    const emptyResult = _FacilitySearchResult(
      facilities: [],
      routeChunks: 0,
      successfulChunks: 0,
      failedChunks: 0,
      osmElements: 0,
      duplicatesRemoved: 0,
    );
    if (categories.isEmpty) return emptyResult;
    if (routePoints.isEmpty ||
        routePoints.any(
          (point) => !point.latitude.isFinite || !point.longitude.isFinite,
        )) {
      debugPrint(
        'Facility query skipped: invalid route geometry or no categories.',
      );
      return const _FacilitySearchResult(
        facilities: [],
        routeChunks: 0,
        successfulChunks: 0,
        failedChunks: 1,
        osmElements: 0,
        duplicatesRemoved: 0,
      );
    }

    final chunks = _facilityRouteChunks(routePoints);
    debugPrint('Route corridor chunks: ${chunks.length}');
    if (chunks.isEmpty) {
      return const _FacilitySearchResult(
        facilities: [],
        routeChunks: 0,
        successfulChunks: 0,
        failedChunks: 1,
        osmElements: 0,
        duplicatesRemoved: 0,
      );
    }

    // 1. Try local backend nearby-places first (CORS-free Overpass + instant POI response)
    try {
      final backendUrl = Uri.parse('$_trafficBackendBaseUrl/nearby-places');
      final backendResp = await http
          .post(
            backendUrl,
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({
              'points': [
                for (final p in routePoints) [p.latitude, p.longitude],
              ],
              'proximity_threshold_km': 1.5,
            }),
          )
          .timeout(const Duration(seconds: 8));

      if (backendResp.statusCode == 200) {
        final decoded = jsonDecode(backendResp.body);
        if (decoded is Map<String, dynamic> && decoded['places'] is List) {
          final placesList = decoded['places'] as List;
          final facilitiesList = <_Facility>[];
          for (final item in placesList) {
            if (item is Map<String, dynamic>) {
              final cat = item['category']?.toString() ?? '';
              final mappedCat = (cat == 'petrol_pump') ? 'fuel' : cat;
              final facility = _Facility(
                id:
                    item['id']?.toString() ??
                    '${item['latitude']}_${item['longitude']}',
                categoryId: mappedCat,
                name: item['name']?.toString(),
                lat: (item['latitude'] as num).toDouble(),
                lon: (item['longitude'] as num).toDouble(),
                emergency: item['emergencyServicesAvailable'] == true
                    ? 'yes'
                    : null,
                phone: item['phoneNumber']?.toString(),
                openingHours: item['openingHours']?.toString(),
                wheelchair: item['wheelchairAccessible'] == true ? 'yes' : null,
                address: item['address']?.toString(),
              );
              facilitiesList.add(facility);
            }
          }
          if (facilitiesList.isNotEmpty) {
            debugPrint(
              'NEARBY FACILITIES: backend returned ${facilitiesList.length} real safety facilities.',
            );
            return _FacilitySearchResult(
              facilities: facilitiesList,
              routeChunks:
                  (decoded['audit']?['corridor_chunks'] as num?)?.toInt() ?? 5,
              successfulChunks:
                  (decoded['audit']?['corridor_chunks'] as num?)?.toInt() ?? 5,
              failedChunks: 0,
              osmElements:
                  (decoded['audit']?['raw_pois'] as num?)?.toInt() ??
                  facilitiesList.length,
              duplicatesRemoved:
                  (decoded['audit']?['raw_pois'] as num?)?.toInt() != null
                  ? ((decoded['audit']!['raw_pois'] as num).toInt() -
                        facilitiesList.length)
                  : 0,
            );
          }
        }
      }
    } catch (_) {}

    final valuesByTag = <String, Set<String>>{};
    for (final category in categories) {
      final values = valuesByTag.putIfAbsent(category.osmTag, () => <String>{});
      values.add(category.osmValue);
    }
    final filters = valuesByTag.entries
        .map((entry) {
          final values = entry.value.join('|');
          return 'nwr["${entry.key}"~"^($values)\$"]';
        })
        .toList(growable: false);
    final elementsByOsmId = <String, _Facility>{};
    var successfulChunks = 0;
    var failedChunks = 0;
    var osmElementCount = 0;
    var validFacilityRows = 0;

    // Process chunks sequentially: one request at a time per endpoint
    for (var index = 0; index < chunks.length; index++) {
      final polygon = chunks[index]
          .map(
            (point) =>
                '${point.latitude.toStringAsFixed(5)} '
                '${point.longitude.toStringAsFixed(5)}',
          )
          .join(' ');
      final clauses = filters
          .map((filter) => '$filter(poly:"$polygon");')
          .join();
      final query = '[out:json][timeout:10];($clauses);out center;';
      final chunkElements = await _queryFacilityChunk(
        query,
        chunkNumber: index + 1,
      );
      if (chunkElements == null) {
        failedChunks++;
        continue;
      }
      successfulChunks++;
      osmElementCount += chunkElements.length;
      for (final element in chunkElements) {
        final facility = _parseFacilityElement(element, categories);
        if (facility == null) continue;
        validFacilityRows++;
        elementsByOsmId.putIfAbsent(facility.id, () => facility);
      }
    }

    final facilities = elementsByOsmId.values.toList(growable: false);
    final duplicatesRemoved = validFacilityRows - elementsByOsmId.length;
    debugPrint('OSM elements returned: $osmElementCount');
    debugPrint('Valid facilities parsed: $validFacilityRows');
    debugPrint('Duplicates removed: $duplicatesRemoved');
    for (final category in categories) {
      final count = facilities
          .where((facility) => facility.categoryId == category.id)
          .length;
      debugPrint('${category.label} parsed: $count');
    }
    debugPrint('Final facilities: ${facilities.length}');
    return _FacilitySearchResult(
      facilities: facilities,
      routeChunks: chunks.length,
      successfulChunks: successfulChunks,
      failedChunks: failedChunks,
      osmElements: osmElementCount,
      duplicatesRemoved: duplicatesRemoved,
    );
  }

  Future<List<dynamic>?> _queryFacilityChunk(
    String query, {
    required int chunkNumber,
  }) async {
    const endpoints = [
      'https://overpass.openstreetmap.fr/api/interpreter',
      'https://overpass-api.de/api/interpreter',
      'https://overpass.kumi.systems/api/interpreter',
    ];
    for (final endpoint in endpoints) {
      try {
        final response = await http
            .post(Uri.parse(endpoint), body: {'data': query})
            .timeout(const Duration(seconds: 10));
        debugPrint(
          'Overpass endpoint: $endpoint; chunk=$chunkNumber; '
          'HTTP ${response.statusCode}; '
          'response bytes=${response.bodyBytes.length}',
        );
        if (response.statusCode != 200) continue;
        final payload = jsonDecode(response.body);
        if (payload is! Map<String, dynamic> ||
            payload['elements'] is! List<dynamic>) {
          debugPrint('Overpass chunk $chunkNumber returned invalid JSON.');
          continue;
        }
        final elements = payload['elements'] as List<dynamic>;
        debugPrint(
          'Overpass chunk $chunkNumber OSM elements: ${elements.length}',
        );
        return elements;
      } catch (error) {
        debugPrint(
          'Overpass endpoint: $endpoint; chunk=$chunkNumber; error=$error',
        );
      }
    }
    debugPrint(
      'Overpass chunk $chunkNumber failed or timed out at all endpoints.',
    );
    return null;
  }

  _Facility? _parseFacilityElement(
    dynamic element,
    List<_FacilityCategory> categories,
  ) {
    if (element is! Map<String, dynamic>) return null;
    final osmType = element['type'];
    final osmId = element['id'];
    final tags = element['tags'];
    if ((osmType != 'node' && osmType != 'way' && osmType != 'relation') ||
        osmId is! int ||
        tags is! Map<String, dynamic>) {
      return null;
    }
    _FacilityCategory? matchedCategory;
    for (final category in categories) {
      if (tags[category.osmTag] == category.osmValue) {
        matchedCategory = category;
        break;
      }
    }
    if (matchedCategory == null) return null;

    final coordinates = osmType == 'node' ? element : element['center'];
    if (coordinates is! Map<String, dynamic> ||
        coordinates['lat'] is! num ||
        coordinates['lon'] is! num) {
      return null;
    }
    final latitude = (coordinates['lat'] as num).toDouble();
    final longitude = (coordinates['lon'] as num).toDouble();
    if (!latitude.isFinite ||
        !longitude.isFinite ||
        latitude < -90 ||
        latitude > 90 ||
        longitude < -180 ||
        longitude > 180) {
      return null;
    }

    String? tagValue(String key, [String? alternateKey]) {
      final value =
          tags[key] ?? (alternateKey == null ? null : tags[alternateKey]);
      return value is String && value.trim().isNotEmpty ? value.trim() : null;
    }

    final address =
        tagValue('addr:full') ??
        [
          tagValue('addr:housenumber'),
          tagValue('addr:street'),
          tagValue('addr:suburb'),
          tagValue('addr:city'),
          tagValue('addr:postcode'),
        ].whereType<String>().join(', ');
    return _Facility(
      id: '$osmType/$osmId',
      categoryId: matchedCategory.id,
      name: tagValue('name'),
      lat: latitude,
      lon: longitude,
      emergency: tagValue('emergency'),
      phone: tagValue('phone', 'contact:phone'),
      website: tagValue('website', 'contact:website'),
      openingHours: tagValue('opening_hours'),
      operator: tagValue('operator'),
      brand: tagValue('brand'),
      wheelchair: tagValue('wheelchair'),
      address: address.isEmpty ? null : address,
    );
  }

  List<List<LatLng>> _facilityRouteChunks(List<LatLng> routePoints) {
    if (routePoints.length < 2) return const [];
    final cumulativeMeters = <double>[0];
    for (var index = 1; index < routePoints.length; index++) {
      cumulativeMeters.add(
        cumulativeMeters.last +
            _distanceBetweenMeters(routePoints[index - 1], routePoints[index]),
      );
    }
    final routeLength = cumulativeMeters.last;
    if (routeLength == 0) return const [];

    const maxChunks = 4;
    final chunkLengthMeters = math.max(25000.0, routeLength / maxChunks);
    const overlapMeters = 500.0;
    final polygons = <List<LatLng>>[];
    for (
      var startMeters = 0.0;
      startMeters < routeLength && polygons.length < maxChunks;
      startMeters += chunkLengthMeters
    ) {
      final start = math.max(0.0, startMeters - overlapMeters);
      final end = math.min(
        routeLength,
        startMeters + chunkLengthMeters + overlapMeters,
      );
      final line = _facilityRouteSlice(
        routePoints,
        cumulativeMeters,
        start,
        end,
      );
      final reduced = _reduceFacilityLine(line, 600);
      final polygon = _bufferFacilityLine(reduced, 900);
      if (polygon.length >= 4) polygons.add(polygon);
    }
    return polygons;
  }

  List<LatLng> _facilityRouteSlice(
    List<LatLng> points,
    List<double> cumulativeMeters,
    double startMeters,
    double endMeters,
  ) {
    LatLng pointAt(double meters) {
      var segment = 0;
      while (segment < cumulativeMeters.length - 2 &&
          cumulativeMeters[segment + 1] < meters) {
        segment++;
      }
      final length = cumulativeMeters[segment + 1] - cumulativeMeters[segment];
      final fraction = length == 0
          ? 0.0
          : ((meters - cumulativeMeters[segment]) / length)
                .clamp(0.0, 1.0)
                .toDouble();
      final first = points[segment];
      final second = points[segment + 1];
      return LatLng(
        first.latitude + (second.latitude - first.latitude) * fraction,
        first.longitude + (second.longitude - first.longitude) * fraction,
      );
    }

    final slice = <LatLng>[pointAt(startMeters)];
    for (var index = 1; index < points.length - 1; index++) {
      if (cumulativeMeters[index] > startMeters &&
          cumulativeMeters[index] < endMeters) {
        slice.add(points[index]);
      }
    }
    slice.add(pointAt(endMeters));
    return slice;
  }

  List<LatLng> _reduceFacilityLine(List<LatLng> points, double spacingMeters) {
    if (points.length <= 2) return points;
    final reduced = <LatLng>[points.first];
    var lastIncluded = points.first;
    for (var index = 1; index < points.length - 1; index++) {
      if (_distanceBetweenMeters(lastIncluded, points[index]) >=
          spacingMeters) {
        reduced.add(points[index]);
        lastIncluded = points[index];
      }
    }
    if (_distanceBetweenMeters(reduced.last, points.last) > 1) {
      reduced.add(points.last);
    }
    return reduced;
  }

  List<LatLng> _bufferFacilityLine(List<LatLng> line, double radiusMeters) {
    if (line.length < 2) return const [];
    final meanLatitude =
        line.map((point) => point.latitude).reduce((a, b) => a + b) /
        line.length;
    final longitudeScale = 111320.0 * math.cos(meanLatitude * math.pi / 180);
    final latitudeScale = 110540.0;
    final left = <LatLng>[];
    final right = <LatLng>[];
    for (var index = 0; index < line.length; index++) {
      final previous = line[math.max(0, index - 1)];
      final next = line[math.min(line.length - 1, index + 1)];
      final dx = (next.longitude - previous.longitude) * longitudeScale;
      final dy = (next.latitude - previous.latitude) * latitudeScale;
      final length = math.sqrt(dx * dx + dy * dy);
      if (length == 0) continue;
      final offsetX = -dy / length * radiusMeters;
      final offsetY = dx / length * radiusMeters;
      left.add(
        LatLng(
          line[index].latitude + offsetY / latitudeScale,
          line[index].longitude + offsetX / longitudeScale,
        ),
      );
      right.add(
        LatLng(
          line[index].latitude - offsetY / latitudeScale,
          line[index].longitude - offsetX / longitudeScale,
        ),
      );
    }
    if (left.length < 2 || right.length < 2) return const [];
    return [...left, ...right.reversed, left.first];
  }

  Future<String?> reverseGeocode(double lat, double lon) async {
    try {
      final uri = Uri.https('nominatim.openstreetmap.org', '/reverse', {
        'lat': lat.toString(),
        'lon': lon.toString(),
        'format': 'json',
      });
      final resp = await http.get(uri, headers: {
        'User-Agent': 'SafeRouteTN-Reverse/2.0',
      }).timeout(const Duration(seconds: 4));
      if (resp.statusCode == 200) {
        final json = jsonDecode(resp.body) as Map<String, dynamic>;
        final addr = json['address'] as Map<String, dynamic>? ?? {};
        final road = addr['road'] ?? addr['suburb'] ?? addr['neighbourhood'];
        final city = addr['city'] ?? addr['town'] ?? addr['village'] ?? addr['county'] ?? addr['state_district'];
        final parts = [road, city].whereType<String>().where((s) => s.isNotEmpty).toList();
        if (parts.isNotEmpty) {
          return parts.join(', ');
        }
        final name = json['name'] as String?;
        if (name != null && name.isNotEmpty) return name;
        final disp = json['display_name'] as String?;
        if (disp != null && disp.isNotEmpty) {
          final segments = disp.split(',');
          return segments.take(2).map((s) => s.trim()).join(', ');
        }
      }
    } catch (_) {}
    return null;
  }

  Future<_SharedLocationResult?> resolveSharedLocation(String input) async {
    final clean = input.trim();
    if (clean.isEmpty) return null;

    // 1. Try local parsing first for fast response
    final local = _parseCoordinatesLocally(clean);
    if (local != null) {
      final friendlyName = await reverseGeocode(local.$1, local.$2) ??
          'Shared Location (${local.$1.toStringAsFixed(4)}, ${local.$2.toStringAsFixed(4)})';
      return _SharedLocationResult(
        latitude: local.$1,
        longitude: local.$2,
        name: friendlyName,
        sourceFormat: local.$3,
      );
    }

    // 2. Query backend for short links or complex redirect URLs
    try {
      final url = Uri.parse('http://127.0.0.1:5000/resolve-shared-location');
      final resp = await http
          .post(
            url,
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({'shared_text': clean}),
          )
          .timeout(const Duration(seconds: 5));

      if (resp.statusCode == 200) {
        final data = jsonDecode(resp.body) as Map<String, dynamic>;
        if (data['success'] == true) {
          return _SharedLocationResult(
            latitude: (data['latitude'] as num).toDouble(),
            longitude: (data['longitude'] as num).toDouble(),
            name: data['name'] as String? ?? 'Shared Location',
            sourceFormat: data['source_format'] as String? ?? 'Google Maps Link',
            resolvedUrl: data['resolved_url'] as String?,
          );
        }
      }
    } catch (_) {}

    return null;
  }

  Future<_RouteWeatherSummary?> fetchRouteWeather(
    List<LatLng> routePoints,
  ) async {
    if (routePoints.isEmpty) return null;
    try {
      final url = Uri.parse('http://127.0.0.1:5000/route-weather');
      final payload = jsonEncode({
        'route_points': routePoints
            .map((p) => [p.latitude, p.longitude])
            .toList(),
      });

      final response = await http
          .post(
            url,
            headers: {'Content-Type': 'application/json'},
            body: payload,
          )
          .timeout(const Duration(seconds: 4));

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body) as Map<String, dynamic>;
        if (data['success'] == true || data['available'] == true) {
          return _RouteWeatherSummary.fromJson(data);
        }
      }
    } catch (_) {
      // Backend unavailable; proceed to direct fallback
    }

    // Direct fallback using Open-Meteo directly from client
    try {
      final samplePoints = <LatLng>[];
      if (routePoints.length <= 4) {
        samplePoints.addAll(routePoints);
      } else {
        samplePoints.add(routePoints.first);
        samplePoints.add(routePoints[routePoints.length ~/ 2]);
        samplePoints.add(routePoints.last);
      }

      final waypoints = <_RouteWeatherWaypoint>[];
      double maxRain = 0.0;
      double? minVis;
      double maxWind = 0.0;
      String primaryDesc = 'Clear sky';

      for (var i = 0; i < samplePoints.length; i++) {
        final pt = samplePoints[i];
        final label = i == 0
            ? 'Start'
            : (i == samplePoints.length - 1 ? 'Destination' : 'Midpoint');

        final uri = Uri.https('api.open-meteo.com', '/v1/forecast', {
          'latitude': pt.latitude.toString(),
          'longitude': pt.longitude.toString(),
          'current':
              'temperature_2m,relative_humidity_2m,precipitation,rain,weather_code,wind_speed_10m,visibility',
          'timezone': 'auto',
        });

        final resp = await http.get(uri).timeout(const Duration(seconds: 4));
        if (resp.statusCode == 200) {
          final json = jsonDecode(resp.body) as Map<String, dynamic>;
          final cur = json['current'] as Map<String, dynamic>? ?? {};
          final code = (cur['weather_code'] as num?)?.toInt() ?? 0;
          final rain = (cur['precipitation'] as num?)?.toDouble() ?? 0.0;
          final wind = (cur['wind_speed_10m'] as num?)?.toDouble() ?? 0.0;
          final vis = (cur['visibility'] as num?)?.toDouble();
          final temp = (cur['temperature_2m'] as num?)?.toDouble() ?? 0.0;

          if (rain > maxRain) maxRain = rain;
          if (wind > maxWind) maxWind = wind;
          if (vis != null && (minVis == null || vis < minVis)) minVis = vis;

          final desc = switch (code) {
            0 => 'Clear sky',
            1 || 2 || 3 => 'Partly cloudy',
            45 || 48 => 'Fog',
            51 || 53 || 55 => 'Drizzle',
            61 || 63 || 65 => 'Rain',
            80 || 81 || 82 => 'Rain showers',
            95 || 96 || 99 => 'Thunderstorm',
            _ => 'Cloudy',
          };
          if (desc != 'Clear sky') primaryDesc = desc;

          waypoints.add(
            _RouteWeatherWaypoint(
              label: label,
              latitude: pt.latitude,
              longitude: pt.longitude,
              temperatureC: temp,
              relativeHumidityPct:
                  (cur['relative_humidity_2m'] as num?)?.toDouble() ?? 0.0,
              precipitationMm: rain,
              rainMm: (cur['rain'] as num?)?.toDouble() ?? 0.0,
              weatherCode: code,
              weatherDescription: desc,
              windSpeedKmh: wind,
              visibilityMeters: vis,
              observationTime: cur['time'] as String? ?? DateTime.now().toIso8601String(),
              isFresh: true,
              dataAgeMinutes: 0.0,
            ),
          );
        }
      }

      if (waypoints.isNotEmpty) {
        final warnings = <String>[];
        if (maxRain >= 15.0) {
          warnings.add('Heavy Rainfall Warning: Up to ${maxRain.toStringAsFixed(1)} mm/h along route.');
        } else if (maxRain >= 5.0) {
          warnings.add('Moderate Rainfall Alert: Up to ${maxRain.toStringAsFixed(1)} mm/h along route.');
        }
        if (minVis != null && minVis < 1000.0) {
          warnings.add('Low Visibility Advisory: Visibility drops to ${minVis.round()}m.');
        }

        return _RouteWeatherSummary(
          available: true,
          provider: 'Open-Meteo Weather API',
          fetchedAt: DateTime.now(),
          waypoints: waypoints,
          maxRainfallMm: maxRain,
          minVisibilityMeters: minVis,
          highestWindKmh: maxWind,
          overallCondition: primaryDesc,
          warnings: warnings,
          floodStatus: maxRain >= 10.0 ? 'rain_ponding_risk' : 'none',
        );
      }
    } catch (_) {}

    return _RouteWeatherSummary.unavailable;
  }

  Future<_WeatherData?> getWeather(double latitude, double longitude) async {
    try {
      final url = Uri.https('api.open-meteo.com', '/v1/forecast', {
        'latitude': latitude.toString(),
        'longitude': longitude.toString(),
        'current': 'temperature_2m,wind_speed_10m,precipitation,weather_code',
        'timezone': 'auto',
      });

      final response = await http.get(url).timeout(const Duration(seconds: 10));

      if (response.statusCode != 200) {
        return null;
      }

      final data = jsonDecode(response.body);
      final current = data['current'];

      return _WeatherData(
        temperature: (current['temperature_2m'] as num).toDouble(),
        windSpeed: (current['wind_speed_10m'] as num).toDouble(),
        precipitation: (current['precipitation'] as num).toDouble(),
        weatherCode: (current['weather_code'] as num).toInt(),
      );
    } catch (e) {
      return null;
    }
  }

  Future<_TrafficAssessment?> _getRouteTraffic(List<LatLng> routePoints) async {
    if (routePoints.length < 2) return null;

    try {
      List<LatLng> pointsPayload = routePoints;
      if (routePoints.length > 8000) {
        final step = (routePoints.length / 5000).ceil();
        pointsPayload = [
          for (var i = 0; i < routePoints.length; i += step) routePoints[i],
          if ((routePoints.length - 1) % step != 0) routePoints.last,
        ];
      }

      final response = await http
          .post(
            Uri.parse('$_trafficBackendBaseUrl/route-traffic'),
            headers: const {'Content-Type': 'application/json'},
            body: jsonEncode({
              'points': [
                for (final point in pointsPayload)
                  [point.latitude, point.longitude],
              ],
            }),
          )
          .timeout(const Duration(seconds: 45));
      debugPrint('TRAFFIC RESPONSE: ${response.statusCode} ${response.body}');
      if (response.statusCode != 200) {
        debugPrint(
          'ROUTE TRAFFIC UNAVAILABLE: backend returned HTTP '
          '${response.statusCode}.',
        );
        return null;
      }

      final payload = jsonDecode(response.body);
      if (payload is! Map<String, dynamic> || payload['available'] != true) {
        debugPrint('ROUTE TRAFFIC UNAVAILABLE: invalid provider response.');
        debugPrint(
          'ROUTE TRAFFIC UNAVAILABLE: ${payload is Map ? payload['reason'] : 'invalid response'}',
        );
        return null;
      }

      final double? speedRatio = payload['mean_speed_ratio'] is num
          ? (payload['mean_speed_ratio'] as num).toDouble()
          : (payload['speedRatio'] is num
              ? (payload['speedRatio'] as num).toDouble()
              : double.tryParse(payload['mean_speed_ratio']?.toString() ??
                  payload['speedRatio']?.toString() ?? ''));

      final int matchedSamples = payload['matched_samples'] is num
          ? (payload['matched_samples'] as num).toInt()
          : (payload['matchedSamples'] is num
              ? (payload['matchedSamples'] as num).toInt()
              : (int.tryParse(payload['matched_samples']?.toString() ??
                  payload['matchedSamples']?.toString() ?? '') ?? 0));

      final int sampleCount = payload['sample_count'] is num
          ? (payload['sample_count'] as num).toInt()
          : (payload['sampleCount'] is num
              ? (payload['sampleCount'] as num).toInt()
              : (int.tryParse(payload['sample_count']?.toString() ??
                  payload['sampleCount']?.toString() ?? '') ?? matchedSamples));

      final int coveragePercent = payload['coverage_percent'] is num
          ? (payload['coverage_percent'] as num).toInt()
          : (payload['coveragePercentage'] is num
              ? (payload['coveragePercentage'] as num).toInt()
              : (int.tryParse(payload['coverage_percent']?.toString() ??
                  payload['coveragePercentage']?.toString() ?? '') ??
                  (sampleCount > 0
                      ? ((matchedSamples / sampleCount) * 100).round()
                      : 0)));

      final rawClosure = payload['road_closure'] ??
          payload['roadClosure'] ??
          payload['closures'];
      final bool isClosure =
          rawClosure == true ||
          rawClosure == 1 ||
          rawClosure?.toString().toLowerCase() == 'true';

      String status = payload['status']?.toString().trim() ?? '';

      final String source =
          (payload['source']?.toString().trim().isNotEmpty ?? false)
          ? payload['source'].toString().trim()
          : 'TomTom Orbis Traffic Flow Vector Tiles';

      if (speedRatio == null ||
          !speedRatio.isFinite ||
          speedRatio < 0 ||
          matchedSamples < 0 ||
          coveragePercent < 0) {
        debugPrint(
          'ROUTE TRAFFIC UNAVAILABLE: incomplete provider data: '
          'source=$source, status=$status, speedRatio=$speedRatio, '
          'samples=$sampleCount, matched=$matchedSamples, '
          'coverage=$coveragePercent, roadClosure=$isClosure',
        );
        return null;
      }

      if (status.isEmpty) {
        if (isClosure || speedRatio < 0.5) {
          status = 'High Traffic';
        } else if (speedRatio < 0.8) {
          status = 'Moderate Traffic';
        } else {
          status = 'Low Traffic';
        }
      }

      final String? statusDesc = payload['status_description']?.toString().trim() ??
          payload['statusDescription']?.toString().trim();
      final String? rawFetchedAt = payload['fetched_at']?.toString().trim() ??
          payload['fetchedAt']?.toString().trim();
      final DateTime fetchedAt = rawFetchedAt != null
          ? (DateTime.tryParse(rawFetchedAt) ?? DateTime.now())
          : DateTime.now();
      final bool isPartial = payload['is_partial_coverage'] == true ||
          payload['isPartialCoverage'] == true ||
          coveragePercent < 90;

      final assessment = _TrafficAssessment(
        source: source,
        status: status,
        meanSpeedRatio: speedRatio,
        sampleCount: sampleCount > 0 ? sampleCount : 1,
        matchedSamples: matchedSamples,
        coveragePercent: coveragePercent,
        roadClosure: isClosure,
        fetchedAt: fetchedAt,
        isPartialCoverage: isPartial,
        statusDescription: statusDesc,
      );
      debugPrint(
        'FRONTEND TRAFFIC RESPONSE: '
        'status=${assessment.status}, '
        'speedRatio=${assessment.meanSpeedRatio.toStringAsFixed(2)}, '
        'samples=${assessment.sampleCount}, '
        'matched=${assessment.matchedSamples}, '
        'coverage=${assessment.coveragePercent}%, '
        'roadClosure=${assessment.roadClosure}',
      );
      return assessment;
    } catch (error) {
      debugPrint('ROUTE TRAFFIC REQUEST ERROR: $error');
      return null;
    }
  }

  Future<Map<String, dynamic>?> checkBlackspotProximity(
    double lat,
    double lon, {
    double radiusMeters = 1000.0,
  }) async {
    final baseUrl = _trafficBackendBaseUrl;
    try {
      final url = Uri.parse(
        '$baseUrl/check-blackspot'
        '?lat=$lat&lon=$lon&radius_meters=$radiusMeters',
      );
      final response = await http.get(url).timeout(const Duration(seconds: 15));
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        if (data is Map<String, dynamic>) return data;
        debugPrint(
          'BLACKSPOT CHECK INVALID JSON RESPONSE: '
          'HTTP 200 returned ${data.runtimeType}, expected an object.',
        );
        return null;
      }
      debugPrint(
        'BLACKSPOT CHECK HTTP ERROR: HTTP ${response.statusCode} from $url.',
      );
    } catch (e) {
      debugPrint(
        'BLACKSPOT CHECK REQUEST ERROR: $e (URL: $baseUrl/check-blackspot)',
      );
    }
    return null;
  }

  Future<Map<String, dynamic>> submitUserFeedback({
    required int rating,
    required String category,
    required String comment,
    String? email,
  }) async {
    final baseUrl = _trafficBackendBaseUrl;
    try {
      final url = Uri.parse('$baseUrl/feedback');
      final payload = {
        'rating': rating,
        'category': category.trim(),
        'comment': comment.trim(),
        if (email != null && email.trim().isNotEmpty) 'email': email.trim(),
        'timestamp': DateTime.now().toUtc().toIso8601String(),
      };
      final response = await http
          .post(
            url,
            headers: const {'Content-Type': 'application/json'},
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 15));

      final data = jsonDecode(response.body);
      if (response.statusCode == 200 || response.statusCode == 201) {
        if (data is Map<String, dynamic> && data['success'] == true) {
          return {
            'success': true,
            'message': data['message'] ?? 'Feedback submitted successfully',
          };
        }
      }
      final errorMsg = (data is Map && data['error'] != null)
          ? data['error'].toString()
          : 'Server returned HTTP ${response.statusCode}';
      return {'success': false, 'error': errorMsg};
    } catch (e) {
      debugPrint('FEEDBACK SUBMIT ERROR: $e');
      return {'success': false, 'error': 'Unable to connect to backend: $e'};
    }
  }

  static String? _cachedUserSessionId;
  static Future<String> getOrGenerateUserSessionId() async {
    if (_cachedUserSessionId != null && _cachedUserSessionId!.isNotEmpty) {
      return _cachedUserSessionId!;
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      var id = prefs.getString('saferoute_community_session_id');
      if (id == null || id.isEmpty) {
        id = 'user_${DateTime.now().millisecondsSinceEpoch}_${math.Random().nextInt(999999)}';
        await prefs.setString('saferoute_community_session_id', id);
      }
      _cachedUserSessionId = id;
      return id;
    } catch (_) {
      _cachedUserSessionId = 'temp_session_${DateTime.now().millisecondsSinceEpoch}';
      return _cachedUserSessionId!;
    }
  }

  Future<Map<String, dynamic>> submitRoadReport({
    required String problemType,
    required String severity,
    required String description,
    String? category,
    double? latitude,
    double? longitude,
    double? locationAccuracy,
    String? locationSource,
    String? photoUrl,
    String? locationLandmark,
    String? routeOrigin,
    String? routeDestination,
    int? selectedRouteIndex,
    double? safetyScore,
    bool forceNew = false,
  }) async {
    final baseUrl = _trafficBackendBaseUrl;
    final sessionId = await getOrGenerateUserSessionId();
    try {
      final url = Uri.parse('$baseUrl/road-report');
      final payload = <String, dynamic>{
        'problem_type': problemType.trim(),
        'category': category ?? problemType.trim(),
        'severity': severity.trim(),
        'description': description.trim(),
        'user_session_id': sessionId,
        'force_new': forceNew,
        if (latitude != null) 'latitude': latitude,
        if (longitude != null) 'longitude': longitude,
        if (locationAccuracy != null) 'location_accuracy': locationAccuracy,
        if (locationSource != null) 'location_source': locationSource,
        if (photoUrl != null && photoUrl.trim().isNotEmpty) 'photo_url': photoUrl.trim(),
        if (locationLandmark != null && locationLandmark.trim().isNotEmpty)
          'location_landmark': locationLandmark.trim(),
        if (routeOrigin != null && routeOrigin.trim().isNotEmpty)
          'route_origin': routeOrigin.trim(),
        if (routeDestination != null && routeDestination.trim().isNotEmpty)
          'route_destination': routeDestination.trim(),
        if (selectedRouteIndex != null) 'selected_route_index': selectedRouteIndex,
        if (safetyScore != null) 'safety_score': safetyScore,
        'timestamp': DateTime.now().toUtc().toIso8601String(),
      };
      final response = await http
          .post(
            url,
            headers: const {'Content-Type': 'application/json'},
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 15));

      final data = jsonDecode(response.body);
      if (response.statusCode == 200 || response.statusCode == 201) {
        if (data is Map<String, dynamic> && data['success'] == true) {
          return {
            'success': true,
            'message': data['message'] ?? 'Road problem reported successfully',
            'report_id': data['report_id'],
            'status': data['status'] ?? 'Pending',
            'confidence_score': data['confidence_score'],
            'confidence_level': data['confidence_level'],
          };
        }
      }
      if (response.statusCode == 409 && data is Map && data['duplicate_detected'] == true) {
        return {
          'success': false,
          'duplicate_detected': true,
          'existing_report_id': data['existing_report_id'],
          'distance_meters': data['distance_meters'],
          'message': data['message'] ?? 'A similar hazard was already reported nearby.',
        };
      }
      final errorMsg = (data is Map && data['error'] != null)
          ? data['error'].toString()
          : 'Server returned HTTP ${response.statusCode}';
      return {'success': false, 'error': errorMsg};
    } catch (e) {
      debugPrint('ROAD REPORT SUBMIT ERROR: $e');
      return {'success': false, 'error': 'Unable to connect to backend: $e'};
    }
  }

  Future<List<_CommunityRoadHazard>> fetchCommunityRoadHazards({
    List<LatLng>? routePoints,
    double radiusMeters = 1500.0,
    bool activeOnly = true,
  }) async {
    final baseUrl = _trafficBackendBaseUrl;
    final sessionId = await getOrGenerateUserSessionId();
    try {
      final queryParams = <String, String>{
        'active_only': activeOnly ? 'true' : 'false',
        'session_id': sessionId,
        'radius_meters': radiusMeters.toString(),
      };
      if (routePoints != null && routePoints.isNotEmpty) {
        final sampleStep = (routePoints.length / 50).ceil().clamp(1, routePoints.length);
        final sampled = <List<double>>[];
        for (var i = 0; i < routePoints.length; i += sampleStep) {
          sampled.add([routePoints[i].latitude, routePoints[i].longitude]);
        }
        if (sampled.last[0] != routePoints.last.latitude || sampled.last[1] != routePoints.last.longitude) {
          sampled.add([routePoints.last.latitude, routePoints.last.longitude]);
        }
        queryParams['points'] = jsonEncode(sampled);
      }
      final url = Uri.parse('$baseUrl/road-reports').replace(queryParameters: queryParams);
      final response = await http.get(url).timeout(const Duration(seconds: 12));
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        if (data is Map<String, dynamic> && data['reports'] is List) {
          return (data['reports'] as List)
              .map((r) => _CommunityRoadHazard.fromJson(r as Map<String, dynamic>))
              .toList();
        }
      }
    } catch (e) {
      debugPrint('FETCH COMMUNITY HAZARDS ERROR: $e');
    }
    return [];
  }

  Future<Map<String, dynamic>> verifyCommunityHazardReport({
    required int reportId,
    required String action,
    String? comment,
  }) async {
    final baseUrl = _trafficBackendBaseUrl;
    final sessionId = await getOrGenerateUserSessionId();
    try {
      final url = Uri.parse('$baseUrl/road-report/$reportId/verify');
      final payload = {
        'user_session_id': sessionId,
        'action': action,
        if (comment != null && comment.isNotEmpty) 'comment': comment,
      };
      final response = await http
          .post(
            url,
            headers: const {'Content-Type': 'application/json'},
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 12));
      final data = jsonDecode(response.body);
      if (response.statusCode == 200) {
        return {
          'success': true,
          'message': data['message'] ?? 'Verification recorded',
          'status': data['status'],
          'confirmations_count': data['confirmations_count'],
          'disputes_count': data['disputes_count'],
          'confidence_score': data['confidence_score'],
          'confidence_level': data['confidence_level'],
        };
      }
      return {
        'success': false,
        'error': data['error'] ?? 'HTTP ${response.statusCode}',
      };
    } catch (e) {
      return {'success': false, 'error': e.toString()};
    }
  }

  Future<List<_CommunityRoadHazard>> fetchMyHazardReports() async {
    final baseUrl = _trafficBackendBaseUrl;
    final sessionId = await getOrGenerateUserSessionId();
    try {
      final url = Uri.parse('$baseUrl/road-reports/my-reports?session_id=$sessionId');
      final response = await http.get(url).timeout(const Duration(seconds: 12));
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        if (data is Map<String, dynamic> && data['reports'] is List) {
          return (data['reports'] as List)
              .map((r) => _CommunityRoadHazard.fromJson(r as Map<String, dynamic>))
              .toList();
        }
      }
    } catch (e) {
      debugPrint('FETCH MY HAZARDS ERROR: $e');
    }
    return [];
  }

  Future<Map<String, dynamic>?> checkRouteHazardReroute({
    required List<LatLng> currentRoutePoints,
    List<LatLng>? alternativeRoutePoints,
    double? currentDistanceKm,
    double? currentDurationMinutes,
    Position? currentPosition,
  }) async {
    if (currentRoutePoints.isEmpty) return null;
    final baseUrl = _trafficBackendBaseUrl;
    try {
      final url = Uri.parse('$baseUrl/route-hazard-reroute-check');
      final payload = jsonEncode({
        'current_route_points': currentRoutePoints
            .map((p) => [p.latitude, p.longitude])
            .toList(),
        if (alternativeRoutePoints != null)
          'alternative_route_points': alternativeRoutePoints
              .map((p) => [p.latitude, p.longitude])
              .toList(),
        if (currentDistanceKm != null) 'current_distance_km': currentDistanceKm,
        if (currentDurationMinutes != null)
          'current_duration_minutes': currentDurationMinutes,
        if (currentPosition != null)
          'current_position': {
            'lat': currentPosition.latitude,
            'lon': currentPosition.longitude,
          },
      });

      final response = await http
          .post(
            url,
            headers: {'Content-Type': 'application/json'},
            body: payload,
          )
          .timeout(const Duration(seconds: 4));

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        if (data is Map<String, dynamic> && data['success'] == true) {
          return data;
        }
      }
    } catch (e) {
      debugPrint('CHECK ROUTE HAZARD ERROR: $e');
    }
    return null;
  }
}

