    'Restaurants',
    'Hotels',
    'Parking',
    'Restrooms',
  ];

  late AnimationController animationController;

  @override
  void initState() {
    super.initState();

    _fromFocusNode.addListener(() => setState(() {}));
    _toFocusNode.addListener(() => setState(() {}));

    animationController = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 2),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _fromFocusNode.dispose();
    _toFocusNode.dispose();
    fromController.dispose();
    toController.dispose();
    animationController.dispose();
    super.dispose();
  }

  void searchRoute() {
    final from = fromController.text.trim();
    final to = toController.text.trim();

    if ((!useCurrentLocationForStart && from.isEmpty) || to.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter a starting point and destination'),
        ),
      );
      return;
    }

    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => MapPage(
          from: from,
          fromIsCurrentLocation: useCurrentLocationForStart,
          to: to,
          preference: selectedPreference,
          travelTime: selectedTravelTime,
          vehicle: selectedVehicle,
          mainPriority: selectedMainPriority,
          optionalFacilities: selectedFacilities.toList(growable: false),
          onToggleTheme: widget.onToggleTheme,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    final wide = MediaQuery.sizeOf(context).width >= 900;

    return Scaffold(
      appBar: AppBar(
        title: Row(
          children: [
            _buildSafeRouteLogo(size: 34),
            const SizedBox(width: 10),
            const Text(
              'SafeRoute TN',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
          ],
        ),
        actions: [
          if (wide)
            TextButton.icon(
              onPressed: () {},
              icon: const Icon(Icons.home_rounded, size: 18),
              label: const Text('Home'),
            ),
          if (wide)
            TextButton.icon(
              onPressed: () {
                Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) =>
                        AboutPage(onToggleTheme: widget.onToggleTheme),
                  ),
                );
              },
              icon: const Icon(Icons.info_outline_rounded, size: 18),
              label: const Text('About'),
            ),
          IconButton(
            tooltip: _isDarkMode ? 'Use light theme' : 'Use dark theme',
            onPressed: widget.onToggleTheme,
            icon: Icon(
              _isDarkMode ? Icons.light_mode_rounded : Icons.dark_mode_rounded,
            ),
          ),
          const SizedBox(width: 12),
        ],
      ),
      body: LayoutBuilder(
        builder: (context, constraints) {
          final content = wide
              ? Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    Expanded(child: _heroPanel(colors, wide: true)),
                    const SizedBox(width: 36),
                    Expanded(child: _searchCard()),
                  ],
                )
              : Column(
                  children: [
                    _heroPanel(colors, wide: false),
                    const SizedBox(height: 22),
                    _searchCard(),
                  ],
                );

          return SingleChildScrollView(
            padding: EdgeInsets.symmetric(
              horizontal: wide ? 56 : 20,
              vertical: wide ? 36 : 18,
            ),
            child: Center(
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 1220),
                child: content,
              ),
            ),
          );
        },
      ),
      bottomNavigationBar: MediaQuery.sizeOf(context).width < 900
          ? SafeArea(
              top: false,
              child: Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: TextButton.icon(
                  onPressed: () {
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (_) =>
                            AboutPage(onToggleTheme: widget.onToggleTheme),
                      ),
                    );
                  },
                  icon: const Icon(Icons.info_outline_rounded, size: 18),
                  label: const Text('About SafeRoute TN'),
                ),
              ),
            )
          : null,
    );
  }

