      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: colors.primary.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Icon(
                  Icons.tune_rounded,
                  color: colors.primary,
                  size: 19,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Travel Preferences',
                      style: TextStyle(
                        color: colors.onSurface,
                        fontSize: 16,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    Text(
                      'Personalize your trip',
                      style: TextStyle(
                        color: colors.onSurfaceVariant,
                        fontSize: 12,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              _preferenceGroupLabel('TRAVEL TIME', colors),
              InkWell(
                onTap: _toggleSmartNightMode,
                borderRadius: BorderRadius.circular(12),
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                  decoration: BoxDecoration(
                    color: _isSmartNightModeActive
                        ? const Color(0xff7C3AED).withValues(alpha: 0.22)
                        : colors.surfaceContainerHighest.withValues(alpha: 0.4),
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color: _isSmartNightModeActive
                          ? const Color(0xffA78BFA)
                          : colors.outlineVariant.withValues(alpha: 0.6),
                      width: 1,
                    ),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(
                        _isSmartNightModeActive ? Icons.nightlight_round : Icons.nightlight_outlined,
                        size: 13,
                        color: _isSmartNightModeActive
                            ? const Color(0xffA78BFA)
                            : colors.onSurfaceVariant,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        'Smart Night Mode',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w700,
                          color: _isSmartNightModeActive
                              ? const Color(0xffA78BFA)
                              : colors.onSurfaceVariant,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 7),
          Wrap(
            spacing: 8,
            runSpacing: 2,
            children: _travelTimeOptions.map((option) {
              return ChoiceChip(
                label: Text(option),
                selected: selectedTravelTime == option,
                onSelected: (_) => setState(() {
                  selectedTravelTime = option;
                  _isSmartNightModeActive = (option == 'Night');
                }),
              );
            }).toList(),
          ),
          const SizedBox(height: 12),
          _preferenceGroupLabel('VEHICLE', colors),
          const SizedBox(height: 7),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            decoration: BoxDecoration(
              color: colors.surfaceContainerHighest.withValues(alpha: 0.55),
              borderRadius: BorderRadius.circular(16),
            ),
            child: DropdownButtonHideUnderline(
              child: DropdownButton<String>(
                value: selectedVehicle,
                isExpanded: true,
                borderRadius: BorderRadius.circular(16),
                style: TextStyle(
                  fontSize: 15,
                  fontWeight: FontWeight.w600,
                  color: colors.onSurface,
                ),
                items: _vehicleOptions
                    .map(
                      (vehicle) => DropdownMenuItem(
                        value: vehicle,
                        child: Text(vehicle),
                      ),
                    )
                    .toList(),
                onChanged: (value) {
                  if (value != null) {
                    setState(() => selectedVehicle = value);
                  }
                },
              ),
            ),
          ),
          const SizedBox(height: 12),
          _preferenceGroupLabel('MAIN PRIORITY', colors),
          const SizedBox(height: 7),
          Wrap(
            spacing: 8,
            runSpacing: 2,
            children: _mainPriorityOptions.map((option) {
              return ChoiceChip(
                label: Text(option),
                selected: selectedMainPriority == option,
                onSelected: (_) =>
                    setState(() => selectedMainPriority = option),
              );
            }).toList(),
          ),
          const SizedBox(height: 12),
          _preferenceGroupLabel('OPTIONAL FACILITIES', colors),
          const SizedBox(height: 7),
          Wrap(
            spacing: 8,
            runSpacing: 2,
            children: _facilityOptions.map((facility) {
              final selected = selectedFacilities.contains(facility);
              final category = _facilityCategories.firstWhere(
                (c) => c.selectorLabel == facility,
                orElse: () => _facilityCategories.first,
              );
              return FilterChip(
                avatar: Container(
                  width: 18,
                  height: 18,
                  decoration: BoxDecoration(
                    color: category.color.withValues(
                      alpha: selected ? 0.22 : 0.12,
                    ),
                    shape: BoxShape.circle,
                  ),
                  child: Center(
                    child: Icon(category.icon, size: 11, color: category.color),
                  ),
                ),
                label: Text(
                  facility,
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: selected ? FontWeight.w600 : FontWeight.w500,
                  ),
                ),
                selected: selected,
                onSelected: (value) {
                  setState(() {
                    if (value) {
                      selectedFacilities.add(facility);
                    } else {
                      selectedFacilities.remove(facility);
                    }
                  });
                },
              );
            }).toList(),
          ),
        ],
      ),
    );
  }

  Widget _preferenceGroupLabel(String label, ColorScheme colors) {
    return Text(
      label,
      style: TextStyle(
        color: colors.onSurfaceVariant,
        fontSize: 10,
        fontWeight: FontWeight.w800,
        letterSpacing: 0.8,
      ),
    );
  }
}

