class MapPage extends StatefulWidget {
  final String from;
  final bool fromIsCurrentLocation;
  final String to;
  final String preference;
  final String travelTime;
  final String vehicle;
  final String mainPriority;
  final List<String> optionalFacilities;
  final VoidCallback onToggleTheme;

  const MapPage({
    super.key,
    this.from = '',
    this.fromIsCurrentLocation = false,
    this.to = '',
    this.preference = 'Safety First',
    this.travelTime = 'Now',
    this.vehicle = 'Car',
    this.mainPriority = 'Safety First',
    this.optionalFacilities = const [],
    required this.onToggleTheme,
  });

  @override
  State<MapPage> createState() => _MapPageState();
}

class _MapPageState extends State<MapPage> with TickerProviderStateMixin {
  bool get _isDarkMode => Theme.of(context).brightness == Brightness.dark;

  final SafeRouteService service = SafeRouteService();
  final MapController mapController = MapController();

  late String currentFrom;
  late String currentTo;
  late String currentPreference;
  late String currentTravelTime;
  late String currentVehicle;
  late String currentMainPriority;
  late bool currentFromIsCurrentLocation;

  final TextEditingController fromController = TextEditingController();
  final TextEditingController toController = TextEditingController();
  bool _searchCardExpanded = false;
  _DashboardTab _currentTab = _DashboardTab.home;
  bool _hasSearchedRoute = false;
  late AnimationController _heroAnimController;

