  Future<void> _loadPersonalSafetyProfile() async {
    try {
      final loaded = await PersonalSafetyProfileStorage.loadProfile();
      if (mounted) {
        setState(() {
          _personalProfile = loaded;
          if (routeEvaluations.isNotEmpty) {
            final evals = routeEvaluations.values.toList();
            if (evals.length > 1) {
              routeRecommendation = _recommendRoutes(evals);
            }
            final eval = routeEvaluations[selectedRouteIndex];
            if (eval != null) {
              personalizedSafetyResult = calculatePersonalizedSafetyScore(
                accidentScore: _factorScore(eval.safety, 'Accident Risk'),
                roadConditionScore: _factorScore(eval.safety, 'Road Condition'),
                trafficScore: _calculateTrafficSafetyScore(eval.traffic),
                weatherScore: _calculateWeatherSafetyScore(eval.weather),
                lightingScore: _factorScore(eval.safety, 'Lighting'),
                accessibilityScore: _factorScore(eval.safety, 'Accessibility'),
                accidentSegmentsWithMatches:
                    eval.blackspots.detectedBlackspots ?? 0,
                accidentVerifiedRecordCount:
                    eval.blackspots.verifiedRecordCount,
                accidentUnavailableReason: eval.blackspots.unavailableReason,
                roadConditionSegments: eval.roadSegments?.length ?? 0,
                lightingSegments: eval.roadSegments?.length ?? 0,
                accessibilitySegments: eval.roadSegments?.length ?? 0,
                traffic: eval.traffic,
                weather: eval.weather,
                priority: _effectivePriority,
                profile: loaded,
              );
              safetyScore = personalizedSafetyResult.score;
            }
          }
        });
      }
    } catch (_) {}
  }

  Future<void> _loadSavedTrips() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final rawList = prefs.getStringList(_savedTripsStorageKey);
      if (rawList != null) {
        final List<_SavedTrip> loaded = [];
        for (final item in rawList) {
          try {
            final decoded = jsonDecode(item);
            if (decoded is Map<String, dynamic>) {
              loaded.add(_SavedTrip.fromJson(decoded));
            }
          } catch (e) {
            debugPrint('Error decoding saved trip: $e');
          }
        }
        if (mounted) {
          setState(() {
            _savedTrips = loaded;
            _savedTripsLoaded = true;
          });
        }
        return;
      }
    } catch (e) {
      debugPrint('Error loading saved trips from SharedPreferences: $e');
    }
    if (mounted) {
      setState(() {
        _savedTripsLoaded = true;
      });
    }
  }

  Future<void> _persistSavedTrips() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final stringList = _savedTrips
          .map((t) => jsonEncode(t.toJson()))
          .toList();
      await prefs.setStringList(_savedTripsStorageKey, stringList);
    } catch (e) {
      debugPrint('Error saving trips to SharedPreferences: $e');
    }
  }

  bool _isCurrentRouteSaved() {
    final from = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : currentFrom.trim();
    final to = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : currentTo.trim();
    if (from.isEmpty || to.isEmpty) return false;
    return _savedTrips.any(
      (t) =>
          t.origin.toLowerCase() == from.toLowerCase() &&
          t.destination.toLowerCase() == to.toLowerCase(),
    );
  }

  double? _extractFactorScore(RouteEvaluation? eval, String key) {
    if (eval == null) return null;
    for (final f in eval.safety.factors) {
      if (f.title == key ||
          (key == 'Accident Risk' && f.title == 'Verified blackspots') ||
          (key == 'Road Condition' && f.title == 'Road condition') ||
          (key == 'Traffic' && f.title == 'Live Traffic')) {
        return f.score;
      }
    }
    return null;
  }

  Future<void> _saveCurrentTrip() async {
    final from = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : currentFrom.trim();
    final to = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : currentTo.trim();

    if (from.isEmpty || to.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('No active route to save'),
          backgroundColor: _NeonTheme.dangerRed,
        ),
      );
      return;
    }

    final existingIndex = _savedTrips.indexWhere(
      (t) =>
          t.origin.toLowerCase() == from.toLowerCase() &&
          t.destination.toLowerCase() == to.toLowerCase(),
    );

    if (existingIndex >= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Trip already saved'),
          backgroundColor: _NeonTheme.electricBlue,
        ),
      );
      return;
    }

    final eval = routeEvaluations[selectedRouteIndex];
    final trip = _SavedTrip(
      id: '${DateTime.now().millisecondsSinceEpoch}',
      origin: from,
      destination: to,
      distanceKm: distanceKm,
      durationMinutes: durationMinutes,
      safetyScore: safetyScore ?? eval?.safety.score,
      routeIndex: selectedRouteIndex,
      vehicleMode: currentVehicle,
      travelTimeMode: currentTravelTime,
      createdAt: DateTime.now(),
      trafficStatus: eval?.traffic?.status,
      weatherScore: eval != null
          ? _calculateWeatherSafetyScore(eval.weather)
          : null,
      routeLabel: 'Route ${selectedRouteIndex + 1}',
    );

    setState(() {
      _savedTrips.insert(0, trip);
    });

    await _persistSavedTrips();

    try {
      final analyticsRecord = SafetyAnalyticsRecord(
        id: trip.id,
        origin: trip.origin,
        destination: trip.destination,
        distanceKm: trip.distanceKm,
        durationMinutes: trip.durationMinutes,
        safetyScore: trip.safetyScore,
        vehicleMode: trip.vehicleMode,
        travelTimeMode: trip.travelTimeMode,
        routeLabel: trip.routeLabel,
        createdAt: trip.createdAt,
        trafficStatus: trip.trafficStatus,
        weatherScore: trip.weatherScore,
        accidentRiskScore:
            eval?.blackspots.clearSampleScore ??
            _extractFactorScore(eval, 'Accident Risk'),
        roadConditionScore: _extractFactorScore(eval, 'Road Condition'),
        lightingScore: _extractFactorScore(eval, 'Lighting'),
        accessibilityScore: _extractFactorScore(eval, 'Accessibility'),
      );
      await SafetyAnalyticsStorage.saveRecord(analyticsRecord);
    } catch (_) {}

    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Trip saved to My Trips'),
          backgroundColor: _NeonTheme.safeGreen,
        ),
      );
    }
  }

  void _autoSaveRouteTrip({
    required String origin,
    required String destination,
    required double distanceKm,
    required double durationMinutes,
    required double? safetyScore,
    required int routeIndex,
    required String vehicleMode,
    required String travelTimeMode,
    String? trafficStatus,
    double? weatherScore,
  }) {
    if (origin.trim().isEmpty || destination.trim().isEmpty) return;
    final exists = _savedTrips.any(
      (t) =>
          t.origin.toLowerCase() == origin.trim().toLowerCase() &&
          t.destination.toLowerCase() == destination.trim().toLowerCase(),
    );
    if (!exists) {
      final trip = _SavedTrip(
        id: '${DateTime.now().millisecondsSinceEpoch}',
        origin: origin.trim(),
        destination: destination.trim(),
        distanceKm: distanceKm,
        durationMinutes: durationMinutes,
        safetyScore: safetyScore,
        routeIndex: routeIndex,
        vehicleMode: vehicleMode,
        travelTimeMode: travelTimeMode,
        createdAt: DateTime.now(),
        trafficStatus: trafficStatus,
        weatherScore: weatherScore,
        routeLabel: 'Route ${routeIndex + 1}',
      );
      setState(() {
        _savedTrips.insert(0, trip);
      });
      unawaited(_persistSavedTrips());
    }
  }

  Future<void> _confirmDeleteTrip(_SavedTrip trip) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogCtx) => AlertDialog(
        backgroundColor: _isDarkMode
            ? _NeonTheme.cardDark
            : _NeonTheme.cardLight,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(18),
          side: BorderSide(
            color: _isDarkMode
                ? _NeonTheme.cyanBorder
                : const Color(0xffE2E8F0),
          ),
        ),
        title: Text(
          'Delete this saved trip?',
          style: TextStyle(
            fontSize: 16,
            fontWeight: FontWeight.w800,
            color: _isDarkMode
                ? _NeonTheme.textPrimaryDark
                : _NeonTheme.textPrimaryLight,
          ),
        ),
        content: Text(
          '${trip.origin} → ${trip.destination}',
          style: TextStyle(
            fontSize: 13,
            color: _isDarkMode
                ? _NeonTheme.textSecondaryDark
                : _NeonTheme.textSecondaryLight,
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogCtx).pop(false),
            child: Text(
              'Cancel',
              style: TextStyle(
                color: _isDarkMode
                    ? _NeonTheme.textSecondaryDark
                    : _NeonTheme.textSecondaryLight,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: _NeonTheme.dangerRed,
              foregroundColor: Colors.white,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(10),
              ),
            ),
            onPressed: () => Navigator.of(dialogCtx).pop(true),
            child: const Text(
              'Delete',
              style: TextStyle(fontWeight: FontWeight.w800),
            ),
          ),
        ],
      ),
    );

    if (confirmed == true) {
      setState(() {
        _savedTrips.removeWhere((t) => t.id == trip.id);
      });
      await _persistSavedTrips();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Trip removed'),
            backgroundColor: _NeonTheme.electricBlue,
          ),
        );
      }
    }
  }

