  bool _isCurrentRouteFavourite() {
    final from = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : currentFrom.trim();
    final to = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : currentTo.trim();
    if (from.isEmpty || to.isEmpty) return false;
    return _favouriteRoutes.any(
      (f) =>
          f.origin.toLowerCase() == from.toLowerCase() &&
          f.destination.toLowerCase() == to.toLowerCase(),
    );
  }

  Future<void> _addCurrentRouteToFavourites() async {
    final from = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : currentFrom.trim();
    final to = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : currentTo.trim();

    if (from.isEmpty || to.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('No active route to favourite'),
          backgroundColor: _NeonTheme.dangerRed,
        ),
      );
      return;
    }

    if (_isCurrentRouteFavourite()) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Route already in Favourites'),
            backgroundColor: _NeonTheme.electricBlue,
          ),
        );
      }
      return;
    }

    final fav = _FavouriteRoute(
      id: '${DateTime.now().millisecondsSinceEpoch}',
      origin: from,
      destination: to,
      vehicleMode: currentVehicle,
      travelTimeMode: currentTravelTime,
      createdAt: DateTime.now(),
      routeLabel: '$from → $to',
    );

    setState(() {
      _favouriteRoutes.insert(0, fav);
    });

    await _persistFavouriteRoutes();

    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('✓ Route added to Favourites'),
          backgroundColor: _NeonTheme.safeGreen,
        ),
      );
    }
  }

  void _planFavouriteRoute(_FavouriteRoute fav) {
    fromController.text = fav.origin;
    toController.text = fav.destination;
    currentFrom = fav.origin;
    currentTo = fav.destination;
    currentFromIsCurrentLocation = false;
    currentVehicle = fav.vehicleMode;
    currentTravelTime = fav.travelTimeMode;
    setState(() {
      _hasSearchedRoute = true;
      _currentTab = _DashboardTab.planRoute;
    });
    loadRoute();
  }

