  double? _factorScore(PersonalizedSafetyResult result, String title) {
    for (final factor in result.factors) {
      if (factor.title == title ||
          (title == 'Verified blackspots' && factor.title == 'Accident Risk') ||
          (title == 'Accident Risk' && factor.title == 'Verified blackspots') ||
          (title == 'Road condition' && factor.title == 'Road Condition') ||
          (title == 'Road Condition' && factor.title == 'Road condition') ||
          (title == 'Live Traffic' && factor.title == 'Traffic') ||
          (title == 'Traffic' && factor.title == 'Live Traffic')) {
        return factor.score;
      }
    }
    return null;
  }

  String weatherText([_WeatherData? targetWeather]) {
    final w = targetWeather ?? weather;
    if (w == null) return 'Unavailable';

    final code = w.weatherCode;

    if (code == 0) return 'Clear';
    if (code >= 1 && code <= 3) return 'Cloudy';
    if (code == 45 || code == 48) return 'Fog';
    if ((code >= 51 && code <= 67) || (code >= 80 && code <= 82)) return 'Rain';
    if ((code >= 71 && code <= 77) || (code >= 85 && code <= 86)) return 'Snow';
    if (code >= 95) return 'Storm';

    return 'Weather data';
  }

  String formatDuration(double minutes) {
    final hours = minutes ~/ 60;
    final mins = minutes.round() % 60;

    if (hours > 0) {
      return '${hours}h ${mins}m';
    }

    return '$mins min';
  }

  @override
  void dispose() {
    _debounceTimer?.cancel();
    WebSpeechHelper.stop();
    _cameraAnimController?.stop();
    _cameraAnimController?.dispose();
    _cameraAnimController = null;
    _heroAnimController.dispose();
    positionSubscription?.cancel();
    positionSubscription = null;
    fromController.dispose();
    toController.dispose();
    _tripsSearchController.dispose();
    _favouritesSearchController.dispose();
    super.dispose();
  }

  void _updateAnimationLifecycle() {
    if (_currentTab == _DashboardTab.home) {
      if (!_heroAnimController.isAnimating) {
        _heroAnimController.repeat(reverse: true);
      }
    } else {
      if (_heroAnimController.isAnimating) {
        _heroAnimController.stop();
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    _updateAnimationLifecycle();
    final width = MediaQuery.sizeOf(context).width;
    final compact = width < 1140;
    final ultraCompact = width < 600;

    return Scaffold(
      backgroundColor: _isDarkMode ? _NeonTheme.bgDark : _NeonTheme.bgLight,
      appBar: PreferredSize(
        preferredSize: const Size.fromHeight(68),
        child: _buildTopNavbar(compact: compact, ultraCompact: ultraCompact),
      ),
      body: Row(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (!compact) ...[
            _buildSidebar(),
            const SizedBox(width: 4),
          ],
          Expanded(
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 280),
              switchInCurve: Curves.easeOutCubic,
              switchOutCurve: Curves.easeInCubic,
              transitionBuilder: (child, animation) {
                return FadeTransition(
                  opacity: animation,
                  child: SlideTransition(
                    position: Tween<Offset>(
                      begin: const Offset(0.0, 0.015),
                      end: Offset.zero,
                    ).animate(animation),
                    child: child,
                  ),
                );
              },
              child: KeyedSubtree(
                key: ValueKey<_DashboardTab>(_currentTab),
                child: _buildCurrentTabContent(context, compact: compact),
              ),
            ),
          ),
        ],
      ),
      bottomNavigationBar: compact ? _buildBottomNavBar() : null,
    );
  }

