  Widget _buildNavActionButton({
    required String label,
    required IconData icon,
    required VoidCallback onTap,
    Color? customColor,
  }) {
    final activeColor =
        customColor ??
        (_isDarkMode
            ? _NeonTheme.textSecondaryDark
            : _NeonTheme.textSecondaryLight);
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(12),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
          decoration: BoxDecoration(
            color: customColor != null
                ? customColor.withValues(alpha: 0.12)
                : (_isDarkMode ? const Color(0xff101C30) : const Color(0xffF1F5F9)),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: customColor != null
                  ? customColor.withValues(alpha: 0.40)
                  : (_isDarkMode ? const Color(0xff1E3456) : const Color(0xffE2E8F0)),
              width: 1,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icon, size: 14.5, color: activeColor),
              const SizedBox(width: 5),
              Text(
                label,
                style: TextStyle(
                  fontSize: 11.5,
                  fontWeight: FontWeight.w700,
                  color: activeColor,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildNavTabButton({
    required String label,
    required IconData icon,
    required _DashboardTab tab,
  }) {
    final isSelected = _currentTab == tab;
    final isHomeTab = tab == _DashboardTab.planRoute;
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: () {
          setState(() {
            _currentTab = tab;
          });
        },
        borderRadius: BorderRadius.circular(12),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 220),
          curve: Curves.easeOutCubic,
          padding: const EdgeInsets.symmetric(horizontal: 13, vertical: 7),
          decoration: BoxDecoration(
            gradient: isSelected
                ? const LinearGradient(
                    colors: [Color(0xff1687FF), Color(0xff00D9FF)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  )
                : null,
            color: isSelected && !_isDarkMode ? const Color(0xff2563EB) : (isSelected ? null : Colors.transparent),
            borderRadius: BorderRadius.circular(14),
            border: Border.all(
              color: isSelected
                  ? const Color(0xff00D9FF).withValues(alpha: 0.6)
                  : Colors.transparent,
              width: 1.1,
            ),
            boxShadow: isSelected
                ? [
                    BoxShadow(
                      color: const Color(0xff00D9FF).withValues(alpha: 0.35),
                      blurRadius: 10,
                      offset: const Offset(0, 2),
                    ),
                  ]
                : null,
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                icon,
                size: 15,
                color: isSelected
                    ? (isHomeTab
                          ? Colors.white
                          : (_isDarkMode
                                ? _NeonTheme.neonCyan
                                : const Color(0xff2563EB)))
                    : (_isDarkMode
                          ? _NeonTheme.textSecondaryDark
                          : const Color(0xff475569)),
              ),
              const SizedBox(width: 6),
              Text(
                label,
                style: TextStyle(
                  fontSize: 12,
                  fontWeight: isSelected ? FontWeight.w800 : FontWeight.w600,
                  letterSpacing: 0.2,
                  color: isSelected
                      ? (isHomeTab
                            ? Colors.white
                            : (_isDarkMode
                                  ? Colors.white
                                  : const Color(0xff2563EB)))
                      : (_isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : const Color(0xff475569)),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildSidebarItem({
    required IconData icon,
    required String label,
    required _DashboardTab tab,
    VoidCallback? customTap,
  }) {
    final isSelected = _currentTab == tab;
    return _SidebarItemInteractive(
      icon: icon,
      label: label,
      isSelected: isSelected,
      isDarkMode: _isDarkMode,
      onTap: () {
        if (customTap != null) {
          customTap();
        } else {
          setState(() => _currentTab = tab);
        }
      },
    );
  }

