  Widget _buildBottomNavBar() {
    int currentIndex = 0;
    if (_currentTab == _DashboardTab.home) {
      currentIndex = 0;
    } else if (_currentTab == _DashboardTab.planRoute) {
      currentIndex = 1;
    } else if (_currentTab == _DashboardTab.journeyMode) {
      currentIndex = 2;
    } else if (_currentTab == _DashboardTab.myTrips) {
      currentIndex = 3;
    } else {
      currentIndex = 4;
    }

    return Container(
      decoration: BoxDecoration(
        color: _isDarkMode
            ? const Color(0xEB0A1120)
            : const Color(0xF2FFFFFF),
        border: Border(
          top: BorderSide(
            color: _isDarkMode
                ? _NeonTheme.cyanBorder.withValues(alpha: 0.35)
                : const Color(0xffE2E8F0),
            width: 1,
          ),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: _isDarkMode ? 0.30 : 0.05),
            blurRadius: 10,
            offset: const Offset(0, -2),
          ),
        ],
      ),
      child: SafeArea(
        top: false,
        child: SizedBox(
          height: 60,
          child: BottomNavigationBar(
            currentIndex: currentIndex,
            onTap: (index) {
              if (index == 0) {
                setState(() => _currentTab = _DashboardTab.home);
              } else if (index == 1) {
                setState(() => _currentTab = _DashboardTab.planRoute);
              } else if (index == 2) {
                setState(() => _currentTab = _DashboardTab.journeyMode);
              } else if (index == 3) {
                setState(() => _currentTab = _DashboardTab.myTrips);
              } else if (index == 4) {
                _showMobileMoreSheet(context);
              }
            },
            backgroundColor: Colors.transparent,
            elevation: 0,
            selectedItemColor: _NeonTheme.neonCyan,
            unselectedItemColor: _isDarkMode
                ? _NeonTheme.textSecondaryDark
                : _NeonTheme.textSecondaryLight,
            selectedFontSize: 11,
            unselectedFontSize: 10,
            selectedLabelStyle: const TextStyle(fontWeight: FontWeight.w800),
            unselectedLabelStyle: const TextStyle(fontWeight: FontWeight.w500),
            type: BottomNavigationBarType.fixed,
            items: const [
              BottomNavigationBarItem(
                icon: Icon(Icons.home_rounded),
                label: 'Home',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.explore_rounded),
                label: 'Explore',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.navigation_rounded),
                label: 'Live Nav',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.history_rounded),
                label: 'Trips',
              ),
              BottomNavigationBarItem(
                icon: Icon(Icons.grid_view_rounded),
                label: 'More',
              ),
            ],
          ),
        ),
      ),
    );
  }

  // ignore: unused_element
  void _showMobileMoreSheet(BuildContext context) {
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: _isDarkMode ? _NeonTheme.cardDark : Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (ctx) {
        return SafeArea(
          child: SingleChildScrollView(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 16),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Center(
                  child: Container(
                    width: 36,
                    height: 4,
                    decoration: BoxDecoration(
                      color: _isDarkMode ? Colors.white24 : Colors.black12,
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                Text(
                  _isTamil ? 'அனைத்து அம்சங்கள்' : 'More Features & Tools',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.w800,
                    color: _isDarkMode
                        ? _NeonTheme.textPrimaryDark
                        : _NeonTheme.textPrimaryLight,
                  ),
                ),
                const SizedBox(height: 14),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    _buildMobileMoreItem(
                      ctx,
                      icon: Icons.groups_rounded,
                      color: _NeonTheme.safeGreen,
                      label: 'Community',
                      onTap: () {
                        setState(
                          () => _currentTab = _DashboardTab.community,
                        );
                      },
                    ),
                    _buildMobileMoreItem(
                      ctx,
                      icon: Icons.emergency_rounded,
                      color: _NeonTheme.dangerRed,
                      label: 'Emergency',
                      onTap: () {
                        setState(
                          () => _currentTab = _DashboardTab.emergency,
                        );
                      },
                    ),
                    _buildMobileMoreItem(
                      ctx,
                      icon: Icons.shield_rounded,
                      color: _NeonTheme.neonCyan,
                      label: 'Insights',
                      onTap: () {
                        setState(
                          () => _currentTab = _DashboardTab.safetyInsights,
                        );
                      },
                    ),
                    _buildMobileMoreItem(
                      ctx,
                      icon: Icons.star_rounded,
                      color: _NeonTheme.neonAmber,
                      label: 'Favourites',
                      onTap: () {
                        setState(
                          () => _currentTab = _DashboardTab.favouriteRoutes,
                        );
                      },
                    ),
                    _buildMobileMoreItem(
                      ctx,
                      icon: Icons.compare_arrows_rounded,
                      color: _NeonTheme.neonCyan,
