      case _DashboardTab.planRoute:
        if (loading) {
          return Center(
            child: Container(
              padding: const EdgeInsets.all(32),
              decoration: BoxDecoration(
                color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
