              ),
            ),
          );
        }
        if (errorMessage.isNotEmpty) {
          return Center(
            child: Container(
              margin: const EdgeInsets.all(24),
              padding: const EdgeInsets.all(28),
              constraints: const BoxConstraints(maxWidth: 480),
              decoration: BoxDecoration(
                color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
                borderRadius: BorderRadius.circular(22),
                border: Border.all(
                  color: _NeonTheme.dangerRed.withValues(alpha: 0.6),
                  width: 1.2,
                ),
                boxShadow: [
                  BoxShadow(
                    color: _NeonTheme.dangerRed.withValues(alpha: 0.2),
                    blurRadius: 16,
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Icon(
                    Icons.error_outline_rounded,
                    size: 48,
                    color: _NeonTheme.dangerRed,
                  ),
                  const SizedBox(height: 14),
                  Text(
                    'Route Computation Error',
                    style: TextStyle(
                      fontSize: 17,
                      fontWeight: FontWeight.w800,
                      color: _isDarkMode
                          ? _NeonTheme.textPrimaryDark
                          : _NeonTheme.textPrimaryLight,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    errorMessage,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      fontSize: 13,
                      color: _isDarkMode
                          ? _NeonTheme.textSecondaryDark
                          : _NeonTheme.textSecondaryLight,
                    ),
                  ),
                  const SizedBox(height: 20),
                  Wrap(
                    spacing: 12,
                    runSpacing: 12,
                    alignment: WrapAlignment.center,
                    children: [
                      ElevatedButton.icon(
                        style: ElevatedButton.styleFrom(
                          backgroundColor: _NeonTheme.neonCyan,
                          foregroundColor: Colors.black,
                          padding: const EdgeInsets.symmetric(
                            horizontal: 20,
                            vertical: 12,
                          ),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onPressed: loadRoute,
                        icon: const Icon(Icons.refresh_rounded, size: 18),
                        label: const Text(
                          'Try Again',
                          style: TextStyle(fontWeight: FontWeight.w800),
                        ),
                      ),
                      OutlinedButton.icon(
                        style: OutlinedButton.styleFrom(
                          foregroundColor: _NeonTheme.neonCyan,
                          side: const BorderSide(color: _NeonTheme.cyanBorder),
                          padding: const EdgeInsets.symmetric(
                            horizontal: 16,
                            vertical: 12,
                          ),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onPressed: () =>
                            setState(() => _hasSearchedRoute = false),
                        icon: const Icon(Icons.edit_road_rounded, size: 18),
                        label: const Text(
                          'Edit Journey',
                          style: TextStyle(fontWeight: FontWeight.w700),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          );
        }
        return _buildMapDashboard(context, compact: compact);

      case _DashboardTab.community:
        return _buildCommunityView(context, compact: compact);

      case _DashboardTab.emergency:
        return _buildEmergencyView(context, compact: compact);

      case _DashboardTab.myTrips:
        return _buildTripsHistoryView();

      case _DashboardTab.favouriteRoutes:
        return _buildFavouriteRoutesView();

      case _DashboardTab.safetyAnalytics:
        return _buildSafetyAnalyticsView();

      case _DashboardTab.nearbyPlaces:
        return _buildSmartNearbyPlacesView();

      case _DashboardTab.journeyMode:
        return _buildJourneyModeView();

      case _DashboardTab.safetyInsights:
        return _buildSafetyInsightsView();

      case _DashboardTab.routeCompare:
        return _buildSmartRouteComparisonView();

      case _DashboardTab.settings:
        return _buildSettingsView();

      case _DashboardTab.about:
        return _buildAboutView();
    }
  }

  void _onSearchAiSafeRoute() {
    if (loading) return; // Ignore duplicate taps while route search is in flight
    final from = fromController.text.trim();
    final to = toController.text.trim();

    if ((!currentFromIsCurrentLocation && from.isEmpty) || to.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter a starting point and destination'),
          backgroundColor: _NeonTheme.dangerRed,
        ),
      );
      return;
    }

    setState(() {
      currentFrom = from;
      currentTo = to;
      _activeSearchField = _SearchFieldType.none;
      _hasSearchedRoute = true;
      _searchCardExpanded = false;
      _currentTab = _DashboardTab.planRoute;
      if (_selectedFacilityCategories.isNotEmpty) {
        _syncFacilityGroupsFromCategories();
      } else if (_selectedFacilityGroups.isNotEmpty) {
        _syncCategoriesFromFacilityGroups();
      }
    });

    loadRoute();
  }

