          Text(
            'Plan your journey',
            style: TextStyle(
              fontSize: 22,
              fontWeight: FontWeight.w900,
              letterSpacing: -0.3,
              color: _isDarkMode
                  ? _NeonTheme.textPrimaryDark
                  : _NeonTheme.textPrimaryLight,
            ),
          ),
          const SizedBox(height: 5),
          Text(
            'Choose your starting point and destination in Tamil Nadu.',
            style: TextStyle(
              fontSize: 13,
              color: _isDarkMode
                  ? _NeonTheme.textSecondaryDark
                  : _NeonTheme.textSecondaryLight,
            ),
          ),
          const SizedBox(height: 22),
          // Starting Point
          TextField(
            controller: fromController,
            textInputAction: TextInputAction.next,
            onTap: () {
              setState(() {
                _activeSearchField = _SearchFieldType.start;
              });
              if (_selectedStartLocation == null && fromController.text.trim().length >= 2) {
                _onSearchFieldChanged(fromController.text, _SearchFieldType.start);
              }
            },
            onChanged: (val) => _onSearchFieldChanged(val, _SearchFieldType.start),
            style: TextStyle(
              fontSize: 14,
              color: _isDarkMode
                  ? _NeonTheme.textPrimaryDark
                  : _NeonTheme.textPrimaryLight,
            ),
            decoration: InputDecoration(
              labelText: 'Start Location',
              hintText: 'Search starting location...',
              prefixIcon: const Icon(
                Icons.trip_origin_rounded,
                color: _NeonTheme.safeGreen,
                size: 20,
              ),
              suffixIcon: fromController.text.isNotEmpty
                  ? IconButton(
                      icon: const Icon(Icons.close_rounded, size: 16),
                      onPressed: () {
                        setState(() {
                          fromController.clear();
                          currentFrom = '';
                          _selectedStartLocation = null;
                          currentFromIsCurrentLocation = false;
                          _locationSuggestions = [];
                        });
                      },
                    )
                  : null,
              filled: true,
              fillColor: _isDarkMode
                  ? _NeonTheme.cardElevatedDark
                  : const Color(0xffF8FAFC),
            ),
          ),
          const SizedBox(height: 6),
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton.icon(
              onPressed: _isLocatingGps ? null : _onUseCurrentLocationSelected,
              icon: Icon(
                currentFromIsCurrentLocation
                    ? Icons.my_location_rounded
                    : Icons.location_searching_rounded,
                size: 16,
                color: _NeonTheme.safeGreen,
              ),
              label: Text(
                currentFromIsCurrentLocation
                    ? 'Using Live GPS Location'
                    : '📍 Use my current location',
                style: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w700,
                  color: _NeonTheme.safeGreen,
                ),
              ),
            ),
          ),
          if (_activeSearchField == _SearchFieldType.start)
            _buildSuggestionDropdown(_SearchFieldType.start),
          Padding(
            padding: const EdgeInsets.only(left: 27),
            child: Container(
              height: 16,
              width: 2,
              color: _isDarkMode
                  ? _NeonTheme.cyanBorder
                  : const Color(0xffE2E8F0),
            ),
          ),
          // Destination
          TextField(
            controller: toController,
            textInputAction: TextInputAction.done,
            onTap: () {
              setState(() {
                _activeSearchField = _SearchFieldType.destination;
              });
              if (_selectedEndLocation == null && toController.text.trim().length >= 2) {
                _onSearchFieldChanged(toController.text, _SearchFieldType.destination);
              }
            },
            onChanged: (val) => _onSearchFieldChanged(val, _SearchFieldType.destination),
            onSubmitted: (_) => _onSearchAiSafeRoute(),
            style: TextStyle(
              fontSize: 14,
              color: _isDarkMode
                  ? _NeonTheme.textPrimaryDark
                  : _NeonTheme.textPrimaryLight,
            ),
            decoration: InputDecoration(
              labelText: 'Destination',
              hintText: 'Where do you want to go?',
              prefixIcon: const Icon(
                Icons.location_on_rounded,
                color: _NeonTheme.dangerRed,
                size: 22,
              ),
              suffixIcon: toController.text.isNotEmpty
                  ? IconButton(
                      icon: const Icon(Icons.close_rounded, size: 16),
                      onPressed: () {
                        setState(() {
                          toController.clear();
                          currentTo = '';
                          _selectedEndLocation = null;
                          _locationSuggestions = [];
                        });
                      },
                    )
                  : null,
              filled: true,
              fillColor: _isDarkMode
                  ? _NeonTheme.cardElevatedDark
                  : const Color(0xffF8FAFC),
            ),
          ),
          if (_activeSearchField == _SearchFieldType.destination)
            _buildSuggestionDropdown(_SearchFieldType.destination),
          const SizedBox(height: 14),
          Row(
            children: [
              const Icon(Icons.stars_rounded, size: 14, color: _NeonTheme.neonCyan),
              const SizedBox(width: 6),
              Text(
                'POPULAR TAMIL NADU CORRIDORS',
                style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.8,
                  color: _NeonTheme.neonCyan,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              _buildPopularRouteChip('Chennai', 'Coimbatore'),
              _buildPopularRouteChip('Madurai', 'Kodaikanal'),
              _buildPopularRouteChip('Trichy', 'Thanjavur'),
              _buildPopularRouteChip('Salem', 'Yercaud'),
            ],
          ),
          const SizedBox(height: 20),
          // Travel Preferences Container
          _buildLandingPreferencesSection(),
          const SizedBox(height: 24),
          // Main Button: SEARCH AI SAFE ROUTE
          SizedBox(
            width: double.infinity,
            height: 54,
            child: ElevatedButton.icon(
              onPressed: loading ? null : _onSearchAiSafeRoute,
              icon: loading
                  ? const SizedBox(
                      width: 18,
                      height: 18,
                      child: CircularProgressIndicator(
                        strokeWidth: 2.2,
                        color: Colors.white,
                      ),
                    )
                  : const Icon(Icons.explore_rounded, size: 20),
              label: AnimatedSwitcher(
                duration: const Duration(milliseconds: 200),
                child: Text(
                  loading ? 'Analyzing Safe Routes...' : 'FIND SAFE ROUTE',
                  key: ValueKey(loading),
                  style: const TextStyle(
                    fontSize: 14.5,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 0.8,
                  ),
                ),
              ),
              style: ElevatedButton.styleFrom(
                backgroundColor: _NeonTheme.electricBlue,
                foregroundColor: Colors.white,
                disabledForegroundColor: Colors.white70,
                disabledBackgroundColor: const Color(0xff1E3A8A),
                shadowColor: _NeonTheme.electricBlue.withValues(alpha: 0.5),
                elevation: 6,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(16),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildPopularRouteChip(String from, String to) {
    return InkWell(
      borderRadius: BorderRadius.circular(16),
      onTap: () {
        setState(() {
          fromController.text = from;
          toController.text = to;
          currentFrom = from;
          currentTo = to;
          currentFromIsCurrentLocation = false;
          _selectedStartLocation = null;
          _selectedEndLocation = null;
          _locationSuggestions = [];
        });
      },
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
        decoration: BoxDecoration(
          color: _isDarkMode
              ? const Color(0xff06152D)
              : const Color(0xffF1F5F9),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(
            color: _isDarkMode
                ? const Color(0x3500D9FF)
                : const Color(0xffCBD5E1),
            width: 0.9,
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              '$from ➔ $to',
              style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: _isDarkMode
                    ? _NeonTheme.textPrimaryDark
                    : _NeonTheme.textPrimaryLight,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildLandingPreferencesSection() {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardElevatedDark.withValues(alpha: 0.6)
            : const Color(0xffF1F5F9),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: _isDarkMode ? Colors.white10 : Colors.black12,
          width: 1,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(7),
                decoration: BoxDecoration(
                  color: _NeonTheme.neonCyan.withValues(alpha: 0.15),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: const Icon(
                  Icons.tune_rounded,
                  color: _NeonTheme.neonCyan,
                  size: 17,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Travel Preferences',
                      style: TextStyle(
                        fontSize: 14,
                        fontWeight: FontWeight.w800,
                        color: _isDarkMode
                            ? _NeonTheme.textPrimaryDark
                            : _NeonTheme.textPrimaryLight,
                      ),
                    ),
                    Text(
                      'Personalize your trip',
                      style: TextStyle(
                        fontSize: 11,
                        color: _isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          _landingGroupLabel('TRAVEL TIME'),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            runSpacing: 4,
            children: _landingTravelTimeOptions.map((option) {
              final selected = currentTravelTime == option;
              return ChoiceChip(
                label: Text(option),
                selected: selected,
                selectedColor: _NeonTheme.electricBlue.withValues(alpha: 0.3),
                labelStyle: TextStyle(
                  fontSize: 12,
                  fontWeight: selected ? FontWeight.w800 : FontWeight.w600,
                  color: selected
                      ? _NeonTheme.neonCyan
                      : (_isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight),
                ),
                onSelected: (_) => setState(() {
                  currentTravelTime = option;
                  if (routePoints.isNotEmpty) {
                    final eval = routeEvaluations[selectedRouteIndex];
                    _routeRiskSections = _buildRouteRiskSections(
                      routePoints: routePoints,
                      evaluation: eval,
                      segments: eval?.roadSegments ?? selectedOsmRoadSegments,
                      weather: eval?.weather ?? weather,
                      travelTime: currentTravelTime,
                    );
                  }
                }),
              );
            }).toList(),
          ),
          const SizedBox(height: 14),
          _landingGroupLabel('VEHICLE'),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            runSpacing: 4,
            children: _landingVehicleOptions.map((v) {
              final selected = currentVehicle == v;
              final icon = v == 'Car'
                  ? Icons.directions_car_rounded
                  : v == 'Bike'
                  ? Icons.two_wheeler_rounded
                  : v == 'Bus'
                  ? Icons.directions_bus_rounded
                  : Icons.directions_walk_rounded;
              return ChoiceChip(
                avatar: Icon(
                  icon,
                  size: 15,
                  color: selected
                      ? _NeonTheme.neonCyan
                      : (_isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight),
                ),
                label: Text(v),
                selected: selected,
                selectedColor: _NeonTheme.electricBlue.withValues(alpha: 0.3),
                labelStyle: TextStyle(
                  fontSize: 12,
                  fontWeight: selected ? FontWeight.w800 : FontWeight.w600,
                  color: selected
                      ? _NeonTheme.neonCyan
                      : (_isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight),
                ),
                onSelected: (_) => setState(() => currentVehicle = v),
              );
            }).toList(),
          ),
          const SizedBox(height: 14),
          _landingGroupLabel('MAIN PRIORITY'),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            runSpacing: 4,
            children: _landingPriorityOptions.map((option) {
              final selected = currentMainPriority == option;
              return ChoiceChip(
                label: Text(option),
                selected: selected,
                selectedColor: _NeonTheme.electricBlue.withValues(alpha: 0.3),
                labelStyle: TextStyle(
                  fontSize: 12,
                  fontWeight: selected ? FontWeight.w800 : FontWeight.w600,
                  color: selected
                      ? _NeonTheme.neonCyan
                      : (_isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight),
                ),
                onSelected: (_) => setState(() {
                  currentMainPriority = option;
                  currentPreference = option;
                }),
              );
            }).toList(),
          ),
          const SizedBox(height: 14),
          _landingGroupLabel('OPTIONAL FACILITIES'),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            runSpacing: 4,
            children: _landingFacilityOptions.map((facility) {
              final selected = _selectedFacilityCategories.contains(facility);
              final category = _facilityCategories.firstWhere(
                (c) => c.selectorLabel == facility,
                orElse: () => _facilityCategories.first,
              );
              return FilterChip(
                avatar: Container(
                  width: 18,
                  height: 18,
                  decoration: BoxDecoration(
                    color: category.color.withValues(
                      alpha: selected ? 0.3 : 0.15,
                    ),
                    shape: BoxShape.circle,
                  ),
                  child: Center(
                    child: Icon(category.icon, size: 11, color: category.color),
                  ),
                ),
                label: Text(
                  facility,
                  style: TextStyle(
                    fontSize: 11.5,
                    fontWeight: selected ? FontWeight.w700 : FontWeight.w500,
                    color: selected
                        ? (_isDarkMode
                              ? _NeonTheme.textPrimaryDark
                              : _NeonTheme.textPrimaryLight)
                        : (_isDarkMode
                              ? _NeonTheme.textSecondaryDark
                              : _NeonTheme.textSecondaryLight),
                  ),
                ),
                selected: selected,
                selectedColor: category.color.withValues(alpha: 0.22),
                onSelected: (value) {
                  setState(() {
                    if (value) {
                      _selectedFacilityCategories.add(facility);
                    } else {
                      _selectedFacilityCategories.remove(facility);
                    }
                    _syncFacilityGroupsFromCategories();
                  });
                },
              );
            }).toList(),
          ),
        ],
      ),
    );
  }

  Widget _landingGroupLabel(String label) {
    return Text(
      label,
      style: TextStyle(
        fontSize: 10,
        fontWeight: FontWeight.w800,
        letterSpacing: 0.8,
        color: _isDarkMode
            ? _NeonTheme.textSecondaryDark
            : _NeonTheme.textSecondaryLight,
      ),
    );
  }


  Widget _buildSuggestionDropdown([_SearchFieldType? explicitField]) {
    final effectiveField = explicitField ?? _activeSearchField;
    if (effectiveField == _SearchFieldType.none) return const SizedBox.shrink();

    final isStart = effectiveField == _SearchFieldType.start;
    final currentText = isStart ? fromController.text.trim() : toController.text.trim();

    return Container(
      margin: const EdgeInsets.only(top: 8),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: _isDarkMode ? const Color(0xf608152B) : Colors.white,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: _isDarkMode ? const Color(0x6000D9FF) : const Color(0xffE2E8F0),
          width: 1.1,
        ),
        boxShadow: [
          BoxShadow(
            color: (_isDarkMode ? const Color(0xff00D9FF) : const Color(0xff2563EB))
                .withValues(alpha: 0.15),
            blurRadius: 16,
            offset: const Offset(0, 4),
          ),
          ..._NeonTheme.cardShadow(_isDarkMode),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          // Header / Prompt
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Icon(
                    isStart ? Icons.trip_origin_rounded : Icons.location_on_rounded,
                    size: 13,
                    color: isStart ? const Color(0xff10B981) : const Color(0xffEF4444),
                  ),
                  const SizedBox(width: 6),
                  Text(
                    isStart ? 'SELECT START LOCATION' : 'SELECT DESTINATION',
                    style: TextStyle(
                      fontSize: 9,
                      fontWeight: FontWeight.w800,
                      letterSpacing: 0.6,
                      color: isStart ? const Color(0xff10B981) : const Color(0xffEF4444),
                    ),
                  ),
                ],
              ),
              InkWell(
                onTap: () {
                  setState(() {
                    _activeSearchField = _SearchFieldType.none;
                  });
                },
                borderRadius: BorderRadius.circular(4),
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                  child: Row(
                    children: [
                      Text(
                        'Close',
                        style: TextStyle(
                          fontSize: 9,
                          fontWeight: FontWeight.w700,
                          color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                        ),
                      ),
                      const SizedBox(width: 2),
                      Icon(
                        Icons.close_rounded,
                        size: 12,
                        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),

          // 1. "Use my current location" option (ONLY for Start location!)
          if (isStart) ...[
            InkWell(
              onTap: _isLocatingGps ? null : _onUseCurrentLocationSelected,
              borderRadius: BorderRadius.circular(8),
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                decoration: BoxDecoration(
                  color: const Color(0xff10B981).withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                    color: const Color(0xff10B981).withValues(alpha: 0.35),
                    width: 0.9,
                  ),
                ),
                child: Row(
                  children: [
                    Container(
                      width: 24,
                      height: 24,
                      decoration: BoxDecoration(
                        color: const Color(0xff10B981).withValues(alpha: 0.22),
                        shape: BoxShape.circle,
                      ),
                      child: const Center(
                        child: Icon(
                          Icons.my_location_rounded,
                          size: 14,
                          color: Color(0xff10B981),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(
                            '📍 Use my current location',
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w800,
                              color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                            ),
                          ),
                          Text(
                            _isLocatingGps
                                ? 'Resolving live GPS location...'
                                : 'Auto-detect device position as starting point',
                            style: const TextStyle(
                              fontSize: 9.5,
                              fontWeight: FontWeight.w600,
                              color: Color(0xff10B981),
                            ),
                          ),
                        ],
                      ),
                    ),
                    if (_isLocatingGps)
                      const SizedBox(
                        width: 13,
                        height: 13,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          color: Color(0xff10B981),
                        ),
                      )
                    else
                      const Icon(
                        Icons.chevron_right_rounded,
                        size: 16,
                        color: Color(0xff10B981),
                      ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 8),
          ],

          // 2. Loading State
          if (_isSearchingLocations) ...[
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 12),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  SizedBox(
                    width: 14,
                    height: 14,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: _isDarkMode ? _NeonTheme.neonCyan : const Color(0xff2563EB),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Text(
                    'Searching Nominatim locations...',
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                    ),
                  ),
                ],
              ),
            ),
          ] else if (_locationSearchError != null) ...[
            // 3. Error State
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 4),
              child: Row(
                children: [
                  const Icon(Icons.info_outline_rounded, size: 14, color: _NeonTheme.neonAmber),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      _locationSearchError!,
                      style: const TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                        color: _NeonTheme.neonAmber,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ] else if (currentText.length >= 2 && _locationSuggestions.isEmpty) ...[
            // 4. No Results
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 4),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(
                    Icons.location_off_rounded,
                    size: 15,
                    color: _isDarkMode ? Colors.white38 : Colors.black38,
                  ),
                  const SizedBox(width: 6),
                  Text(
                    'No matching locations found',
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                    ),
                  ),
                ],
              ),
            ),
          ] else if (_locationSuggestions.isNotEmpty) ...[
            // 5. Results List
            ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 180),
              child: ListView.separated(
                shrinkWrap: true,
                padding: EdgeInsets.zero,
                itemCount: _locationSuggestions.length,
                separatorBuilder: (ctx, i) => Divider(
                  height: 1,
                  thickness: 0.6,
                  color: _isDarkMode ? const Color(0x2500D9FF) : const Color(0x150284C7),
                ),
                itemBuilder: (context, index) {
                  final suggestion = _locationSuggestions[index];
                  return InkWell(
                    onTap: () => _onSelectLocationSuggestion(
                      suggestion,
                      effectiveField,
                    ),
                    borderRadius: BorderRadius.circular(6),
                    hoverColor: (_isDarkMode ? _NeonTheme.neonCyan : const Color(0xff2563EB))
                        .withValues(alpha: 0.08),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 7),
                      child: Row(
                        children: [
                          Container(
                            width: 22,
                            height: 22,
                            decoration: BoxDecoration(
                              color: (_isDarkMode ? _NeonTheme.neonCyan : const Color(0xff2563EB))
                                  .withValues(alpha: 0.12),
                              shape: BoxShape.circle,
                            ),
                            child: Center(
                              child: Icon(
                                isStart
                                    ? Icons.trip_origin_rounded
                                    : Icons.location_on_rounded,
                                size: 12,
                                color: isStart
                                    ? const Color(0xff10B981)
                                    : const Color(0xffEF4444),
                              ),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Text(
                                  suggestion.title,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                    fontSize: 12,
                                    fontWeight: FontWeight.w700,
                                    color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                                  ),
                                ),
                                if (suggestion.subtitle.isNotEmpty)
                                  Text(
                                    suggestion.subtitle,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      fontSize: 10,
                                      fontWeight: FontWeight.w500,
                                      color: _isDarkMode
                                          ? _NeonTheme.textSecondaryDark
                                          : const Color(0xff64748B),
                                    ),
                                  ),
                              ],
                            ),
                          ),
                          const SizedBox(width: 6),
                          Icon(
                            Icons.north_west_rounded,
                            size: 11,
                            color: _isDarkMode ? Colors.white30 : Colors.black26,
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ),
          ] else if (currentText.length < 2 && !isStart) ...[
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
              child: Text(
                'Type at least 2 characters to search OpenStreetMap locations...',
                style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w500,
                  color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                ),
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _buildPlanYourSafeJourneyCard() {
    return Container(
      padding: const EdgeInsets.all(14),
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: _isDarkMode ? const Color(0xff08152B) : Colors.white,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: _isDarkMode ? const Color(0x4000D9FF) : const Color(0xffE2E8F0),
          width: 1.1,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
        image: DecorationImage(
          image: const AssetImage('assets/images/plan_journey_bg.jpg'),
          fit: BoxFit.cover,
          alignment: const Alignment(0, -0.2),
          colorFilter: ColorFilter.mode(
            _isDarkMode
                ? const Color(0x65061226)
                : const Color(0x55ffffff),
            BlendMode.srcOver,
          ),
        ),
        gradient: LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: _isDarkMode
              ? [
                  const Color(0xeb061226),
                  const Color(0x9508152B),
                  const Color(0x600B1930),
                ]
              : [
                  const Color(0xf4ffffff),
                  const Color(0xd0ffffff),
                  const Color(0xa0ffffff),
                ],
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          // Header Row
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Container(
                        width: 26,
                        height: 26,
                        decoration: BoxDecoration(
                          gradient: const LinearGradient(
                            colors: [Color(0xff00D9FF), Color(0xff168BFF)],
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                          ),
                          borderRadius: BorderRadius.circular(7),
                        ),
                        child: const Center(
