  Widget _buildAiSafetyBriefCard() {
    final eval = routeEvaluations[selectedRouteIndex];
    final vehicle = currentVehicle.isNotEmpty ? currentVehicle : 'Car';
    final isNight = currentTravelTime == 'Evening' || currentTravelTime == 'Night';

    final reasons = <({IconData icon, Color color, String title, String detail})>[];

    // 1. Accident Risk Exposure
    final hasAccidentData = accidentSafety != null ||
        (eval?.blackspots != null &&
            eval!.blackspots.clearSampleScore != null &&
            eval.blackspots.successfulSamples > 0);
    if (hasAccidentData) {
      final detected = eval?.blackspots.detectedBlackspots ?? 0;
      final isLow = (accidentSafety ?? 80.0) >= 80.0 && detected == 0;
      reasons.add((
        icon: isLow ? Icons.shield_rounded : Icons.warning_amber_rounded,
        color: isLow ? const Color(0xff10B981) : const Color(0xffF59E0B),
        title: 'Accident Risk Exposure',
        detail: isLow
            ? 'Lower corridor accident exposure across screened NH sectors (zero blackspots in verified dataset)'
            : '$detected accident hotspot${detected == 1 ? '' : 's'} monitored along route',
      ));
    } else {
      reasons.add((
        icon: Icons.shield_outlined,
        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
        title: 'Accident Risk Exposure',
        detail: eval?.blackspots.unavailableReason ?? 'Accident history data unavailable for this sector',
      ));
    }

    // 2. Road Surface Quality
    if (roadSafety != null) {
      final isGood = roadSafety! >= 75.0;
      final roadFactor = eval?.safety.factors
          .where((f) => f.title == 'Road Condition')
          .firstOrNull;
      final isProxy = roadFactor?.source?.contains('proxy') == true ||
          (roadFactor != null && roadFactor.evidence?.contains('road class') == true && roadFactor.evidence?.contains('surface tags') != true);

      reasons.add((
        icon: Icons.add_road_rounded,
        color: isGood ? _NeonTheme.neonCyan : const Color(0xffF59E0B),
        title: 'Road Surface Quality',
        detail: isProxy
            ? (isGood
                ? 'High-grade highway corridor inferred from road class hierarchy (pavement unmeasured)'
                : 'Standard road corridor inferred via hierarchy (pavement unmeasured)')
            : (isGood
                ? 'Engineered highway surface with verified smooth pavement tags'
                : 'Moderate road surface quality detected from verified pavement tags'),
      ));
    } else {
      reasons.add((
        icon: Icons.add_road_rounded,
        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
        title: 'Road Surface Quality',
        detail: 'Road condition telemetry provisional · insufficient evidence',
      ));
    }

    // 3. Weather & Environmental Safety
    if (eval?.weather != null) {
      reasons.add((
        icon: Icons.cloud_done_rounded,
        color: const Color(0xff38BDF8),
        title: 'Weather & Visibility',
        detail: 'Suitable for travel: ${eval!.weather!.temperature.round()}°C with favorable conditions',
      ));
    } else {
      reasons.add((
        icon: Icons.cloud_off_rounded,
        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
        title: 'Weather & Visibility',
        detail: 'Real-time weather station radar unavailable',
      ));
    }

    // 4. Lighting / Night Safety or Vehicle Profile
    if (isNight) {
      if (lightingSafety != null) {
        reasons.add((
          icon: Icons.lightbulb_rounded,
          color: const Color(0xffFBBF24),
          title: 'Night Travel Lighting',
          detail: '${lightingSafety!.round()}% lighting coverage along verified road sectors',
        ));
      } else {
        reasons.add((
          icon: Icons.nightlight_round,
          color: const Color(0xffF59E0B),
          title: 'Night Travel Caution',
          detail: 'Lighting telemetry unavailable for this route — drive with dipped beams',
        ));
      }
    } else {
      final String vehicleDetail;
      switch (vehicle) {
        case 'Bike':
          vehicleDetail = 'Optimized for two-wheelers: curve alerts and lane surface checked';
          break;
        case 'Bus':
          vehicleDetail = 'Commercial transit verified: broad turning radii and wide highway lanes';
          break;
        case 'Walk':
          vehicleDetail = 'Pedestrian safety check: continuous walkways and safe crossings';
          break;
        case 'Car':
        default:
          vehicleDetail = 'Divided multilane highway prioritized with wide overtaking margins';
          break;
      }
      reasons.add((
        icon: vehicle == 'Bike'
            ? Icons.two_wheeler_rounded
            : (vehicle == 'Bus'
                ? Icons.directions_bus_rounded
                : (vehicle == 'Walk' ? Icons.directions_walk_rounded : Icons.directions_car_rounded)),
        color: const Color(0xffA855F7),
        title: '$vehicle Safety Profile',
        detail: vehicleDetail,
      ));
    }

    // 5. Active Safety Mode Intelligence
    final safetyMode = _personalProfile.safetyMode;
    if (safetyMode == 'Women Safety') {
      final lightingText = lightingSafety != null
          ? '${lightingSafety!.round()}% lighting verified'
          : 'Lighting telemetry unavailable';
      reasons.add((
        icon: Icons.shield_rounded,
        color: const Color(0xffEC4899),
        title: 'Women Safety Intelligence',
        detail: '$lightingText. Emergency corridors prioritized. Note: Corridor evidence is partial — stay alert.',
      ));
    } else if (safetyMode == 'Senior Friendly') {
      final accessText = accessibilitySafety != null
          ? '${accessibilitySafety!.round()}% accessibility'
          : 'Smooth highway priority';
      reasons.add((
        icon: Icons.elderly_rounded,
        color: const Color(0xff38BDF8),
        title: 'Senior-Friendly Support',
        detail: '$accessText. Low fatigue route selected with direct hospital coverage and gentle curves.',
      ));
    } else if (safetyMode == 'Family Safety') {
      reasons.add((
        icon: Icons.family_restroom_rounded,
        color: const Color(0xff10B981),
        title: 'Family Safety Margin',
        detail: 'Maximized safety buffer: lower accident exposure, stable weather, and emergency readiness.',
      ));
    }

    // 6. Long Journey Highway Corridor Telemetry
    final isLongTrip = (eval?.safety.tripContext == 'long' || eval?.safety.tripContext == TripContextType.long.name) ||
        ((eval?.route.distance ?? 0.0) >= 60.0);
    final isExtendedTrip = !isLongTrip &&
        ((eval?.safety.tripContext == 'medium' || eval?.safety.tripContext == TripContextType.medium.name) ||
        ((eval?.route.distance ?? 0.0) >= 20.0));

    if (isLongTrip) {
      reasons.add((
        icon: Icons.alt_route_rounded,
        color: const Color(0xff6366F1),
        title: 'Long Highway Corridor Brief',
        detail: 'Sustained intercity highway monitoring with verified roadside support and navigation continuity.',
      ));
    } else if (isExtendedTrip) {
      reasons.add((
        icon: Icons.alt_route_rounded,
        color: const Color(0xff6366F1),
        title: 'Extended Journey Safety Brief',
        detail: 'Sub-district corridor guidance with verified road transitions and service access.',
      ));
    }

    return _BreathingGlowBorderCard(
      isDarkMode: _isDarkMode,
      child: Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: _isDarkMode ? const Color(0xff0B1930) : Colors.white,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(
            color: _isDarkMode ? const Color(0x3500D9FF) : const Color(0xffE2E8F0),
            width: 1.2,
          ),
          boxShadow: _NeonTheme.cardShadow(_isDarkMode),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                Container(
                  width: 28,
                  height: 28,
                  decoration: BoxDecoration(
                    gradient: const LinearGradient(
                      colors: [Color(0xff8B5CF6), Color(0xff2563EB)],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: const Center(
                    child: Icon(Icons.psychology_rounded, color: Colors.white, size: 16),
                  ),
                ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      'AI Safety Brief',
                      style: TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w800,
                        color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                      ),
                    ),
                    Text(
                      'Why SafeRoute recommends Route ${selectedRouteIndex + 1}${safetyMode != 'General' ? ' · $safetyMode' : ''}',
                      style: TextStyle(
                        fontSize: 9.5,
                        color: _isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight,
                      ),
                    ),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2.5),
                decoration: BoxDecoration(
                  color: const Color(0xff8B5CF6).withValues(alpha: 0.16),
                  borderRadius: BorderRadius.circular(6),
                  border: Border.all(
                    color: const Color(0xff8B5CF6).withValues(alpha: 0.4),
                    width: 0.8,
                  ),
                ),
                child: const Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.auto_awesome, size: 10, color: Color(0xffA78BFA)),
                    SizedBox(width: 3),
                    Text(
                      'AI ANALYSED',
                      style: TextStyle(
                        fontSize: 8.5,
                        fontWeight: FontWeight.w800,
                        letterSpacing: 0.4,
                        color: Color(0xffA78BFA),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          for (var i = 0; i < reasons.length; i++) ...[
            if (i > 0) const SizedBox(height: 8),
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  margin: const EdgeInsets.only(top: 2),
                  width: 20,
                  height: 20,
                  decoration: BoxDecoration(
                    color: reasons[i].color.withValues(alpha: 0.14),
                    borderRadius: BorderRadius.circular(5),
                  ),
                  child: Center(
                    child: Icon(reasons[i].icon, size: 12, color: reasons[i].color),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        reasons[i].title,
                        style: TextStyle(
                          fontSize: 10.5,
                          fontWeight: FontWeight.w700,
                          color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                        ),
                      ),
                      const SizedBox(height: 1.5),
                      Text(
                        reasons[i].detail,
                        style: TextStyle(
                          fontSize: 9.5,
                          height: 1.25,
                          color: _isDarkMode
                              ? _NeonTheme.textSecondaryDark
                              : _NeonTheme.textSecondaryLight,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ],
          if (eval?.safety != null) ...[
            const SizedBox(height: 10),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
              decoration: BoxDecoration(
                color: _isDarkMode ? const Color(0xff061325) : const Color(0xffF1F5F9),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(
                  color: _isDarkMode ? const Color(0x2000D9FF) : const Color(0xffE2E8F0),
                  width: 0.8,
                ),
              ),
              child: Row(
                children: [
                  Icon(
                    Icons.info_outline_rounded,
                    size: 13,
                    color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      '${eval!.safety.evidenceSummary} · Verified real-world telemetry only',
                      style: TextStyle(
                        fontSize: 9.0,
                        color: _isDarkMode ? _NeonTheme.textSecondaryDark : const Color(0xff64748B),
                        fontStyle: FontStyle.italic,
                      ),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ],
      ),
    ),
    );
  }

  Widget _buildSafetyRiskTimelineCard() {
    return _buildSmartRouteRiskForecastCard();
  }

  Widget _buildSmartRouteRiskForecastCard() {
    final origin = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : (currentFrom.trim().isNotEmpty ? currentFrom.trim() : 'Start');
    final destination = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : (currentTo.trim().isNotEmpty ? currentTo.trim() : 'Destination');
    final eval = routeEvaluations[selectedRouteIndex];

    final currentDistance = (selectedRouteIndex < availableRoutes.length)
        ? availableRoutes[selectedRouteIndex].distance
        : (distanceKm > 0 ? distanceKm : 25.0);
    final currentDuration = (selectedRouteIndex < availableRoutes.length)
        ? availableRoutes[selectedRouteIndex].duration / 60.0
        : (durationMinutes > 0 ? durationMinutes : 35.0);

    final checkpoints = SmartRiskForecastEngine.generateCheckpoints(
      evaluation: eval,
      totalDistanceKm: currentDistance,
      totalDurationMinutes: currentDuration,
      originName: origin,
      destinationName: destination,
      vehicle: currentVehicle,
      travelTime: currentTravelTime,
      profile: _personalProfile,
    );

    if (_selectedForecastCheckpointIndex >= checkpoints.length) {
      _selectedForecastCheckpointIndex = 0;
    }
    final selectedCp = checkpoints[_selectedForecastCheckpointIndex];

    final disableMotion = MediaQuery.maybeOf(context)?.disableAnimations ?? false;

    return GlassCard(
      borderRadius: BorderRadius.circular(16),
      border: Border.all(
        color: _isDarkMode ? const Color(0x3500D9FF) : const Color(0xffE2E8F0),
        width: 1.2,
      ),
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Row(
            children: [
              Container(
                width: 28,
                height: 28,
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [Color(0xff00D9FF), Color(0xff00E59B)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: const Center(
                  child: Icon(Icons.psychology_rounded, color: Colors.white, size: 16),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      _isTamil ? 'ஸ்மார்ட் பாதை ஆபத்து கணிப்பு' : 'SMART ROUTE RISK FORECAST',
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 0.4,
                        color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                      ),
                    ),
                    Text(
                      _isTamil
                          ? 'உங்கள் பயணத்தில் ஆபத்து எவ்வாறு மாறுகிறது'
                          : 'How risk changes along your journey',
                      style: TextStyle(
                        fontSize: 9.5,
                        color: _isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight,
                      ),
                    ),
                  ],
                ),
              ),
              InkWell(
                onTap: () => _openRiskForecastDialog(routeIndex: selectedRouteIndex),
                borderRadius: BorderRadius.circular(6),
                child: const Padding(
                  padding: EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        'View Details',
                        style: TextStyle(
                          fontSize: 10.5,
                          fontWeight: FontWeight.w700,
                          color: Color(0xff00D9FF),
                        ),
                      ),
                      SizedBox(width: 3),
                      Icon(Icons.arrow_forward_rounded, size: 11, color: Color(0xff00D9FF)),
                    ],
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 14),

          // Horizontal Checkpoint Progression Line:
          // LOW         LOW         MODERATE       LOW
          // ●──────────●──────────●─────────────●
          // Start      20 km       45 km          End
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              for (var i = 0; i < checkpoints.length; i++) ...[
                Expanded(
                  child: _InteractivePressButton(
                    onPressed: () {
                      setState(() {
                        _selectedForecastCheckpointIndex = i;
                      });
                    },
                    child: Column(
                      children: [
                        // Risk Level Badge above node
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                          decoration: BoxDecoration(
                            color: checkpoints[i].riskLevel.color.withValues(alpha: 0.16),
                            borderRadius: BorderRadius.circular(4),
                            border: Border.all(
                              color: checkpoints[i].riskLevel.color.withValues(alpha: 0.45),
                              width: 0.8,
                            ),
                          ),
                          child: Text(
                            checkpoints[i].riskLevel.title(false).replaceAll(' RISK', ''),
                            style: TextStyle(
                              fontSize: 7.5,
                              fontWeight: FontWeight.w800,
                              color: checkpoints[i].riskLevel.color,
                            ),
                          ),
                        ),
                        const SizedBox(height: 5),
                        // Node circle and connecting lines
                        Builder(
                          builder: (context) {
                            final isSelected = i == _selectedForecastCheckpointIndex;
                            final isHighRisk = checkpoints[i]
                                .riskLevel
                                .title(false)
                                .toUpperCase()
                                .contains('HIGH');
                            final cpColor = checkpoints[i].riskLevel.color;
                            final prevColor =
                                i > 0 ? checkpoints[i - 1].riskLevel.color : cpColor;
                            final nextColor = i < checkpoints.length - 1
                                ? checkpoints[i + 1].riskLevel.color
                                : cpColor;

                            return Row(
                              children: [
                                Expanded(
                                  child: Container(
                                    height: 2.5,
                                    decoration: BoxDecoration(
                                      borderRadius: BorderRadius.circular(2),
                                      gradient: i == 0
                                          ? null
                                          : LinearGradient(
                                              colors: [
                                                prevColor.withValues(
                                                    alpha: _isDarkMode ? 0.75 : 0.55),
                                                cpColor.withValues(
                                                    alpha: _isDarkMode ? 0.75 : 0.55),
                                              ],
                                            ),
                                      color: i == 0 ? Colors.transparent : null,
                                      boxShadow: i > 0 && _isDarkMode
                                          ? [
                                              BoxShadow(
                                                color: prevColor.withValues(alpha: 0.35),
                                                blurRadius: 4,
                                              ),
                                            ]
                                          : null,
                                    ),
                                  ),
                                ),
                                AnimatedContainer(
                                  duration: disableMotion
                                      ? Duration.zero
                                      : const Duration(milliseconds: 260),
                                  curve: Curves.easeOutCubic,
                                  width: isSelected ? 28 : (isHighRisk ? 24 : 22),
                                  height: isSelected ? 28 : (isHighRisk ? 24 : 22),
                                  decoration: BoxDecoration(
                                    color: cpColor.withValues(
                                        alpha: isSelected ? 0.28 : (isHighRisk ? 0.22 : 0.16)),
                                    shape: BoxShape.circle,
                                    border: Border.all(
                                      color: cpColor,
                                      width: isSelected ? 2.6 : (isHighRisk ? 2.0 : 1.8),
                                    ),
                                    boxShadow: [
                                      BoxShadow(
                                        color: cpColor.withValues(
                                          alpha: isSelected ? 0.75 : (isHighRisk ? 0.60 : 0.28),
                                        ),
                                        blurRadius: isSelected ? 12 : (isHighRisk ? 9 : 5),
                                        spreadRadius: isSelected ? 2 : (isHighRisk ? 1 : 0),
                                      ),
                                      if (isSelected && _isDarkMode)
                                        BoxShadow(
                                          color: Colors.white.withValues(alpha: 0.4),
                                          blurRadius: 6,
                                          spreadRadius: -1,
                                        ),
                                    ],
                                  ),
                                  child: Center(
                                    child: isSelected
                                        ? Container(
                                            width: 9,
                                            height: 9,
                                            decoration: BoxDecoration(
                                              color: cpColor,
                                              shape: BoxShape.circle,
                                              boxShadow: [
                                                BoxShadow(
                                                  color: Colors.white.withValues(alpha: 0.8),
                                                  blurRadius: 4,
                                                ),
                                              ],
                                            ),
                                          )
                                        : Icon(
                                            checkpoints[i].riskLevel.icon,
                                            size: isHighRisk ? 11 : 10,
                                            color: cpColor,
                                          ),
                                  ),
                                ),
                                Expanded(
                                  child: Container(
                                    height: 2.5,
                                    decoration: BoxDecoration(
                                      borderRadius: BorderRadius.circular(2),
                                      gradient: i == checkpoints.length - 1
                                          ? null
                                          : LinearGradient(
                                              colors: [
                                                cpColor.withValues(
                                                    alpha: _isDarkMode ? 0.75 : 0.55),
                                                nextColor.withValues(
                                                    alpha: _isDarkMode ? 0.75 : 0.55),
                                              ],
                                            ),
                                      color: i == checkpoints.length - 1
                                          ? Colors.transparent
                                          : null,
                                      boxShadow: i < checkpoints.length - 1 && _isDarkMode
                                          ? [
                                              BoxShadow(
                                                color: nextColor.withValues(alpha: 0.35),
                                                blurRadius: 4,
                                              ),
                                            ]
                                          : null,
                                    ),
                                  ),
                                ),
                              ],
                            );
                          },
                        ),
                        const SizedBox(height: 5),
                        // Distance label below node
                        Text(
                          checkpoints[i].label,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            fontSize: 9.5,
                            fontWeight: FontWeight.w800,
                            color: i == _selectedForecastCheckpointIndex
                                ? (_isDarkMode ? const Color(0xff00D9FF) : const Color(0xff2563EB))
                                : (_isDarkMode ? Colors.white70 : const Color(0xff334155)),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ],
          ),
          const SizedBox(height: 12),

          // Current route condition badge
          AnimatedContainer(
            duration: disableMotion ? Duration.zero : const Duration(milliseconds: 220),
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
            decoration: BoxDecoration(
              color: _isDarkMode ? const Color(0xff091222) : const Color(0xffF8FAFC),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(
                color: selectedCp.riskLevel.color.withValues(alpha: 0.45),
                width: 1.2,
              ),
              boxShadow: [
                BoxShadow(
                  color: selectedCp.riskLevel.color.withValues(alpha: _isDarkMode ? 0.20 : 0.08),
                  blurRadius: 8,
                  offset: const Offset(0, 1),
                ),
              ],
            ),
            child: Row(
              children: [
                Icon(
                  selectedCp.riskLevel.icon,
                  size: 15,
                  color: selectedCp.riskLevel.color,
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: RichText(
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    text: TextSpan(
                      style: TextStyle(
                        fontSize: 10,
                        color: _isDarkMode ? Colors.white70 : const Color(0xff334155),
                      ),
                      children: [
                        const TextSpan(text: 'Current route condition: '),
                        TextSpan(
                          text: selectedCp.riskLevel.title(_isTamil),
                          style: TextStyle(
                            fontWeight: FontWeight.w900,
                            color: selectedCp.riskLevel.color,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 6),

          // Reason text
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 4),
            child: Text(
              selectedCp.primaryReason,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                fontSize: 9,
                fontWeight: FontWeight.w500,
                color: _isDarkMode ? _NeonTheme.textSecondaryDark : _NeonTheme.textSecondaryLight,
              ),
            ),
          ),
          const SizedBox(height: 8),

          // Main factors:
          // ✓ Verified accident exposure
          // ✓ Road condition
          // ✓ Weather
          // ○ Lighting unavailable
          // ○ Traffic unavailable
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            decoration: BoxDecoration(
              color: _isDarkMode ? const Color(0xff061325) : const Color(0xffF1F5F9),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(
                color: _isDarkMode ? const Color(0x2000D9FF) : const Color(0xffE2E8F0),
                width: 0.8,
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  _isTamil ? 'முக்கிய காரணிகள்:' : 'Main factors:',
                  style: TextStyle(
                    fontSize: 9.5,
                    fontWeight: FontWeight.w800,
                    color: _isDarkMode ? Colors.white70 : const Color(0xff334155),
                  ),
                ),
                const SizedBox(height: 4),
                // Verified factors (green checkmark)
                for (final factor in selectedCp.verifiedFactors.take(3))
                  Padding(
                    padding: const EdgeInsets.only(bottom: 2),
                    child: Row(
                      children: [
                        const Icon(Icons.check_circle_rounded, size: 11, color: Color(0xff00E59B)),
                        const SizedBox(width: 5),
                        Expanded(
                          child: Text(
                            factor,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              fontSize: 9,
                              fontWeight: FontWeight.w600,
                              color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                // Unavailable factors (neutral hollow circle)
                for (final unav in selectedCp.unavailableFactors.take(2))
                  Padding(
                    padding: const EdgeInsets.only(bottom: 2),
                    child: Row(
                      children: [
                        Icon(
                          Icons.radio_button_unchecked_rounded,
                          size: 11,
                          color: _isDarkMode ? const Color(0xff64748B) : const Color(0xff94A3B8),
                        ),
                        const SizedBox(width: 5),
                        Expanded(
                          child: Text(
                            unav,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              fontSize: 9,
                              fontWeight: FontWeight.w500,
                              color: _isDarkMode ? const Color(0xff94A3B8) : const Color(0xff64748B),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
              ],
            ),
          ),
          const SizedBox(height: 10),

          // [ View Risk Details → ] Action button
          InkWell(
            onTap: () => _openRiskForecastDialog(routeIndex: selectedRouteIndex),
            borderRadius: BorderRadius.circular(8),
            child: Container(
              padding: const EdgeInsets.symmetric(vertical: 7),
              decoration: BoxDecoration(
                color: const Color(0xff00D9FF).withValues(alpha: _isDarkMode ? 0.12 : 0.08),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(
                  color: const Color(0xff00D9FF).withValues(alpha: 0.35),
                  width: 1,
                ),
              ),
              child: const Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
