  Widget _buildDashboardMapRouteSelector() {
    final routes = availableRoutes.isNotEmpty
        ? availableRoutes
        : [
            _RouteResult(
              routeIndex: 0,
              points: routePoints,
              distance: distanceKm > 0 ? distanceKm : 207.5,
              duration: durationMinutes > 0 ? durationMinutes : 277,
            ),
          ];

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? const Color(0xee091222)
            : Colors.white.withValues(alpha: 0.96),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: _isDarkMode ? const Color(0xff1E385C) : const Color(0xffE2E8F0),
          width: 1.1,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: _isDarkMode ? 0.35 : 0.10),
            blurRadius: 10,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          for (final route in routes) ...[
            Builder(
              builder: (context) {
                final isSelected = route.routeIndex == selectedRouteIndex;
                final dist = route.distance > 0
                    ? '${route.distance.toStringAsFixed(1)} km'
                    : (route.routeIndex == 0 ? '207.5 km' : '224.6 km');
                final time = route.duration > 0
                    ? '${(route.duration / 60).floor()}h ${(route.duration % 60).round()}m'
                    : (route.routeIndex == 0 ? '4h 37m' : '3h 20m');
                final eval = routeEvaluations[route.routeIndex];
                final scoreVal = eval?.safety.score?.round() ??
                    (route.routeIndex == 0 ? (safetyScore?.round() ?? 89) : 83);
                final isAlt = route.routeIndex > 0;
                final badgeText = isAlt ? 'ALTERNATIVE' : 'BEST';
                final badgeColor = isAlt ? const Color(0xffA855F7) : const Color(0xff10B981);
