        }

        // Mobile layout (width < 700): Natural vertical single-column stack
        final mobileMapHeight = constraints.maxWidth < 380
            ? 300.0
            : (constraints.maxWidth < 500 ? 330.0 : 350.0);

        return SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(10, 8, 10, 28),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              _StaggeredEntrance(
