          const SizedBox(height: 6),
          // Dynamic personalized "Why this route?" evidence points
          Builder(
            builder: (context) {
              final isNight = currentTravelTime == 'Evening' || currentTravelTime == 'Night';
              final String whyPoint1;
              if (_personalProfile.safetyMode == 'Women Safety') {
                whyPoint1 = isNight
                    ? (lightingSafety != null ? 'Better night lighting evidence' : 'Women Safety corridor check')
                    : 'Prioritized Women Safety factors';
              } else if (_personalProfile.safetyMode == 'Senior Friendly') {
                whyPoint1 = accessibilitySafety != null
                    ? 'Higher accessibility confidence'
                    : 'Senior-Friendly smooth corridor';
              } else if (_personalProfile.safetyMode == 'Family Safety') {
                whyPoint1 = 'Stronger family safety margin';
              } else if (_effectivePriority == 'Fastest') {
                whyPoint1 = 'Optimal transit time & duration';
              } else {
                whyPoint1 = 'Matches $_effectivePriority profile';
              }

              final hasAccidentData = accidentSafety != null ||
                  (eval?.blackspots != null &&
                      eval!.blackspots.clearSampleScore != null &&
                      eval.blackspots.successfulSamples > 0);
              final String whyPoint2;
              if (hasAccidentData && accidentSafety != null && accidentSafety! >= 80.0) {
                whyPoint2 = 'Lower verified NH accident exposure';
              } else if (hasAccidentData && (eval?.blackspots.detectedBlackspots ?? 0) == 0) {
                whyPoint2 = '0 blackspots across screened NH corridors';
              } else if (hasAccidentData) {
                whyPoint2 = 'Monitored accident corridor';
              } else {
                whyPoint2 = 'Accident history unavailable for corridor';
              }

              final String whyPoint3;
              if (roadSafety != null && roadSafety! >= 75.0) {
                whyPoint3 = 'Smoother verified road condition';
              } else if (eval?.safety.verifiedCount != null && eval!.safety.verifiedCount >= 3) {
                whyPoint3 = '${eval.safety.verifiedCount} verified safety factors';
              } else {
                whyPoint3 = 'Engineered route alignment';
              }

              final String whyPoint4;
              if (eval?.weather != null) {
                whyPoint4 = 'Suitable for current weather';
              } else if (isNight && lightingSafety != null) {
                whyPoint4 = 'Verified night lighting sectors';
              } else {
                whyPoint4 = 'Better overall safety/time balance';
              }

              return Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    children: [
                      Expanded(child: _buildWhyThisRouteItem(whyPoint1)),
                      const SizedBox(width: 8),
