  Widget _buildMiniFactorChip(SafetyFactor factor) {
    final bool isLightingDay =
        factor.title == 'Lighting' && currentTravelTime == 'Day';
    final bool isIncluded =
        isLightingDay || (factor.score != null && factor.relevant);
    final double score = factor.score ?? 0.0;
    final Color factorColor = isLightingDay
        ? _NeonTheme.safeGreen
        : (isIncluded
              ? (score >= 70
                    ? _NeonTheme.safeGreen
                    : score >= 40
                    ? _NeonTheme.warningGold
                    : _NeonTheme.dangerRed)
              : (_isDarkMode
                    ? _NeonTheme.textSecondaryDark
                    : _NeonTheme.textSecondaryLight));

    final String displayScore = isLightingDay
        ? 'Day'
        : (isIncluded
              ? '${score.round()}%'
              : (factor.title == 'Traffic' ? 'N/A' : 'Unmapped'));

    final String labelDetail = factor.scoreLabel.isNotEmpty
        ? ' • '
        : '';
    final String statusDetail = isIncluded
        ? (isLightingDay ? 'Daylight' : '${score.round()}%')
        : (factor.unavailableReason ?? 'Data unavailable');

    return Tooltip(
      message: '${factor.title}: ${factor.source ?? 'Verified data'}$labelDetail • $statusDetail',
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 4.5),
        decoration: BoxDecoration(
          color: _isDarkMode
              ? _NeonTheme.cardDark.withValues(alpha: 0.7)
              : Colors.white,
          borderRadius: BorderRadius.circular(7),
          border: Border.all(
            color: isIncluded
                ? factorColor.withValues(alpha: 0.3)
                : (_isDarkMode ? Colors.white10 : Colors.black12),
            width: 0.8,
          ),
        ),
        child: Row(
          children: [
            Icon(
              factor.icon,
              size: 11,
              color: isIncluded
                  ? factorColor
                  : (_isDarkMode ? Colors.white38 : Colors.black38),
            ),
            const SizedBox(width: 4),
            Expanded(
              child: Text(
                factor.title,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  fontSize: 9.5,
                  fontWeight: FontWeight.w700,
                  color: _isDarkMode
                      ? _NeonTheme.textPrimaryDark
                      : _NeonTheme.textPrimaryLight,
                ),
              ),
            ),
            const SizedBox(width: 2),
            Text(
              displayScore,
              style: TextStyle(
                fontSize: 8.5,
                fontWeight: FontWeight.w800,
                color: isIncluded
                    ? factorColor
                    : (_isDarkMode ? Colors.white38 : Colors.black38),
              ),
            ),
          ],
        ),
      ),
    );
  }

