  Widget _buildFactorOverviewTile(SafetyFactor factor) {
    final bool isLightingDay =
        factor.title == 'Lighting' && currentTravelTime == 'Day';
    final bool isIncluded =
        isLightingDay || (factor.score != null && factor.relevant);
    final double score = factor.score ?? 0.0;
    final Color tileColor = isLightingDay
        ? _NeonTheme.safeGreen
        : (isIncluded
              ? (score >= 70
                    ? _NeonTheme.safeGreen
                    : score >= 40
                    ? _NeonTheme.warningGold
                    : _NeonTheme.dangerRed)
              : (_isDarkMode
                    ? _NeonTheme.textSecondaryDark
                    : _NeonTheme.textSecondaryLight));

    final String prefix = isIncluded ? '✓ ' : '— ';
    final String statusBadge = isIncluded ? 'Verified' : 'Unavailable';
    final String statusDetail = isLightingDay
        ? 'Daylight'
        : (isIncluded
              ? '${score.round()}% · ${factor.status ?? 'Verified'}'
              : (factor.unavailableReason ?? 'Unavailable for route'));

    return Container(
      constraints: const BoxConstraints(minHeight: 56),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardElevatedDark
            : const Color(0xffF8FAFC),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
          color: isIncluded
              ? tileColor.withValues(alpha: 0.25)
              : (_isDarkMode ? Colors.white10 : Colors.black12),
          width: 1,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Row(
            children: [
              Icon(factor.icon, size: 14, color: tileColor),
              const SizedBox(width: 5),
              Text(
                prefix,
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w900,
                  color: isIncluded
                      ? _NeonTheme.safeGreen
                      : (_isDarkMode ? Colors.white38 : Colors.black38),
                ),
              ),
              Expanded(
                child: Text(
                  factor.title,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w700,
                    color: _isDarkMode
                        ? _NeonTheme.textPrimaryDark
                        : _NeonTheme.textPrimaryLight,
                  ),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                decoration: BoxDecoration(
                  color: isIncluded
                      ? _NeonTheme.safeGreen.withValues(alpha: 0.15)
                      : (_isDarkMode ? Colors.white10 : Colors.black.withValues(alpha: 0.05)),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  statusBadge,
                  style: TextStyle(
                    fontSize: 8.5,
                    fontWeight: FontWeight.w700,
                    color: isIncluded
                        ? _NeonTheme.safeGreen
                        : (_isDarkMode ? Colors.white38 : Colors.black38),
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 4),
          Row(
            children: [
              Container(
                width: 6,
                height: 6,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: isIncluded
                      ? tileColor
                      : (_isDarkMode ? Colors.white24 : Colors.black26),
                ),
              ),
              const SizedBox(width: 5),
              Expanded(
                child: Text(
                  statusDetail,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontSize: 9.5,
                    fontWeight: FontWeight.w600,
                    color: isIncluded
                        ? tileColor
                        : (_isDarkMode
                              ? _NeonTheme.textSecondaryDark
                              : _NeonTheme.textSecondaryLight),
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

String _getContextAwareRouteInsight() {
    if (routeEvaluations.isEmpty && !_hasSearchedRoute) {
      return _isTamil
          ? 'பயண வழியைத் திட்டமிட்ட பின் சூழல் விழிப்புணர்வு பாதுகாப்பு பகுப்பாய்வு இங்கு தோன்றும்.'
          : 'Plan a route to view context-aware safety intelligence based on verified road data and environmental conditions.';
    }

    final currentEval = routeEvaluations[selectedRouteIndex];
    final currentScore = currentEval?.safety.score ?? safetyScore;
    final otherIndex = selectedRouteIndex == 0 ? 1 : 0;
    final otherEval = routeEvaluations[otherIndex];
    final otherScore = otherEval?.safety.score;

    final hasMultipleRoutes = availableRoutes.length > 1;

    // Check if we have comparison between two corridors
    if (hasMultipleRoutes && currentEval != null && otherEval != null) {
      final currentDist = currentEval.route.distance;
      final otherDist = otherEval.route.distance;
      final isLonger = currentDist > otherDist + 0.5;
      final isShorter = currentDist < otherDist - 0.5;
      final distDiff = (currentDist - otherDist).abs().toStringAsFixed(1);

      // Explicit context-aware explanation: SafeRoute prioritizes safety over raw distance
      if (isLonger &&
          currentScore != null &&
          otherScore != null &&
          currentScore >= otherScore) {
        return _isTamil
            ? 'சூழல் சார்ந்த வழிப்பாதை: குறைந்த தூரத்தை விட பாதுகாப்பிற்கு முன்னுரிமை அளிக்கப்படுகிறது (+$distDiff கி.மீ) - விபத்து அபாயம் குறைவாகவும் சரிபார்க்கப்பட்ட சாலை கட்டமைப்பு கொண்ட வழி தேர்ந்தெடுக்கப்பட்டுள்ளது.'
            : 'Context-Aware Routing: Selected corridor adds +$distDiff km over the shortest path to prioritize verified road safety, avoiding identified hazard zones.';
      }

      if (currentScore != null &&
          otherScore != null &&
          currentScore > otherScore + 3) {
        final scoreDiff = (currentScore - otherScore).round();
        return _isTamil
            ? 'பரிந்துரைக்கப்பட்டது: குறைந்த விபத்து அபாயம் மற்றும் சிறந்த சாலை நிலைமைகளின் காரணமாக (+$scoreDiff% அதிக பாதுகாப்பு).'
            : 'Recommended because of lower observed accident risk and better road conditions (+$scoreDiff% safety margin over alternative corridor).';
      }

      if (currentScore != null &&
          otherScore != null &&
          (currentScore - otherScore).abs() <= 3) {
        if (isShorter) {
          return _isTamil
              ? 'இரு வழிகளும் ஒத்த பாதுகாப்பு நிலைகளைக் கொண்டுள்ளன; குறைந்த தூரம் ($distDiff கி.மீ குறைவு) கொண்ட உகந்த வழி தேர்ந்தெடுக்கப்பட்டுள்ளது.'
              : 'Both corridors exhibit comparable safety scores; selected route provides optimal travel efficiency with verified road infrastructure.';
        }
        return _isTamil
            ? 'இரு வழிகளிலும் சரிபார்க்கப்பட்ட பாதுகாப்பு தரவுகள் சமமாக உள்ளன; பரிந்துரைக்கப்பட்ட முதன்மை பாதை பயன்பாட்டில் உள்ளது.'
            : 'Corridors exhibit comparable verified safety ratings; optimal primary corridor selected for your current vehicle and time.';
      }
    }

    // Single route or general evidence summary
    if (currentScore != null && currentScore >= 70) {
      final blackspotClear = !isNearBlackspot;
      if (blackspotClear) {
        return _isTamil
            ? 'பரிந்துரைக்கப்பட்டது: சரிபார்க்கப்பட்ட விபத்து அபாய மண்டலங்கள் இல்லாததாலும், சாதகமான சாலை நிலைமைகளாலும் இந்த வழி தேர்ந்தெடுக்கப்பட்டது.'
            : 'Recommended because of lower observed risk, clear accident history, and verified road infrastructure along this corridor.';
      }
      return _isTamil
          ? 'சரிபார்க்கப்பட்ட சாலை கட்டமைப்பு மற்றும் தற்போதைய வானிலை தரவுகளின் அடிப்படையில் தேர்ந்தெடுக்கப்பட்டது.'
          : 'Recommended based on verified OpenStreetMap road attributes, daylight visibility, and current environmental conditions.';
    }

    if (recommendationReasons.isNotEmpty) {
      return recommendationReasons.first;
    }
    if (routeRecommendation.reason.isNotEmpty) {
      return routeRecommendation.reason;
    }

    return _isTamil
        ? 'சரிபார்க்கப்பட்ட விபத்து பதிவுகள் மற்றும் சாலை கட்டமைப்பு தரவுகளின் அடிப்படையில் தேர்ந்தெடுக்கப்பட்ட உகந்த வழி.'
        : 'Optimal context-aware route selected based on verified road data, environmental factors, and hazard blackspots.';
  }

