  // ignore: unused_element
  Widget _buildPersonalSafetyProfileSummaryCard() {
    final eval = routeEvaluations[selectedRouteIndex];
    final hasEval = eval != null;
    final match = hasEval && _personalProfile.isConfigured
        ? PreferenceMatchEvaluator.evaluate(
            evaluation: eval,
            profile: _personalProfile,
            isDay: _isDaytimeTravel(currentTravelTime),
          )
        : null;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0xffE2E8F0),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              const Icon(
                Icons.person_pin_rounded,
                color: _NeonTheme.neonCyan,
                size: 18,
              ),
              const SizedBox(width: 8),
              Text(
                'PERSONAL SAFETY PROFILE',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.8,
                  color: _isDarkMode
                      ? _NeonTheme.neonCyan
                      : _NeonTheme.electricBlue,
                ),
              ),
              const Spacer(),
              if (match != null)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 6,
                    vertical: 2,
                  ),
                  decoration: BoxDecoration(
                    color: match.matchColor.withValues(alpha: 0.18),
