  Widget _buildCommunityHazardMarker(_CommunityRoadHazard hazard) {
    Color borderColor;
    IconData badgeIcon;
    Color badgeColor;

    if (hazard.status == 'Confirmed') {
      borderColor = _NeonTheme.safeGreen;
      badgeIcon = Icons.check_rounded;
      badgeColor = _NeonTheme.safeGreen;
    } else if (hazard.status == 'Disputed') {
      borderColor = _NeonTheme.warningGold;
      badgeIcon = Icons.priority_high_rounded;
      badgeColor = _NeonTheme.warningGold;
    } else if (hazard.status == 'Resolved') {
      borderColor = Colors.white38;
      badgeIcon = Icons.done_all_rounded;
      badgeColor = Colors.white54;
    } else {
      borderColor = _NeonTheme.neonCyan;
      badgeIcon = Icons.help_outline_rounded;
      badgeColor = _NeonTheme.neonCyan;
    }

    final catItem = _hazardCategories.firstWhere(
      (c) => c.key == hazard.category,
      orElse: () => _hazardCategories.first,
    );

    final isTargetHazardAhead = _navigationActive && _activeHazardAhead?.id == hazard.id;
    final markerWidth = isTargetHazardAhead ? 42.0 : 36.0;
    final markerHeight = isTargetHazardAhead ? 42.0 : 36.0;

    return Tooltip(
      message: '${hazard.problemType} (${hazard.status} • ${hazard.confidenceLevel})',
      child: Stack(
        clipBehavior: Clip.none,
        alignment: Alignment.center,
        children: [
          Container(
            width: markerWidth,
            height: markerHeight,
            decoration: BoxDecoration(
              color: const Color(0xfa071226),
              shape: BoxShape.circle,
              border: Border.all(color: borderColor, width: isTargetHazardAhead ? 2.8 : 2),
              boxShadow: [
                BoxShadow(
                  color: borderColor.withValues(alpha: isTargetHazardAhead ? 0.70 : 0.40),
                  blurRadius: isTargetHazardAhead ? 14 : 8,
                  spreadRadius: isTargetHazardAhead ? 3 : 1,
                ),
              ],
            ),
            child: Center(
              child: Icon(
                catItem.icon,
                size: isTargetHazardAhead ? 21 : 18,
                color: catItem.color,
              ),
            ),
          ),
          Positioned(
            right: -2,
            top: -2,
            child: Container(
              width: 14,
              height: 14,
              decoration: BoxDecoration(
                color: const Color(0xff061022),
                shape: BoxShape.circle,
                border: Border.all(color: badgeColor, width: 1.2),
              ),
              child: Center(
                child: Icon(
                  badgeIcon,
                  size: 9,
                  color: badgeColor,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  void _showWhyThisRouteDialog({int? routeIndex}) {
    final targetIndex = routeIndex ?? selectedRouteIndex;

    if (routeEvaluations.isEmpty &&
        personalizedSafetyResult.factors.isEmpty &&
        !_hasSearchedRoute) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please calculate a route first to view safety explanations.',
          ),
          backgroundColor: _NeonTheme.electricBlue,
        ),
      );
      return;
    }

    final fromText = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : (currentFrom.trim().isNotEmpty ? currentFrom.trim() : 'Origin');
    final toText = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : (currentTo.trim().isNotEmpty ? currentTo.trim() : 'Destination');

    var evals = Map<int, _RouteEvaluation>.from(routeEvaluations);
    if (!evals.containsKey(targetIndex)) {
      final selectedRoute = (targetIndex < availableRoutes.length)
          ? availableRoutes[targetIndex]
          : _RouteResult(
              points: routePoints,
              distance: distanceKm,
              duration: durationMinutes * 60,
              routeIndex: targetIndex,
            );
      evals[targetIndex] = _RouteEvaluation(
        route: selectedRoute,
        roadSegments: selectedOsmRoadSegments,
        safety: personalizedSafetyResult,
        weather: weather,
        blackspots: _BlackspotRouteAssessment(
          clearSampleScore: null,
          detectedBlackspots: blackspotDetails != null ? 1 : 0,
          successfulSamples: 0,
          segmentsChecked: 0,
          verifiedRecordCount: 0,
          segmentResults: const [],
          unavailableReason: null,
        ),
        traffic: routeEvaluations[selectedRouteIndex]?.traffic,
      );
    }

    showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return WhyThisRouteDialog(
          initialRouteIndex: targetIndex,
          allEvaluations: evals,
          origin: fromText,
          destination: toText,
          vehicle: currentVehicle,
          travelTime: currentTravelTime,
          priority: _effectivePriority,
          service: service,
          isDarkMode: _isDarkMode,
          formatDurationFn: formatDuration,
          personalProfile: _personalProfile,
        );
      },
    );
  }

