  Widget _buildInlineCategoryChip(_FacilityCategory category) {
    final selected = _selectedFacilityCategories.contains(
      category.selectorLabel,
    );
    final count = facilities.where((f) => f.categoryId == category.id).length;
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: () => unawaited(_toggleFacilityCategory(category, !selected)),
        borderRadius: BorderRadius.circular(10),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
          decoration: BoxDecoration(
            color: selected
                ? category.color.withValues(alpha: 0.18)
                : (_isDarkMode
                      ? _NeonTheme.cardElevatedDark
                      : const Color(0xffF1F5F9)),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(
              color: selected
                  ? category.color
                  : (_isDarkMode ? Colors.white12 : Colors.black12),
              width: selected ? 1.4 : 0.8,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(category.icon, size: 14, color: category.color),
              const SizedBox(width: 6),
              Text(
                category.selectorLabel,
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: selected ? FontWeight.w800 : FontWeight.w600,
                  color: selected
                      ? (_isDarkMode ? Colors.white : Colors.black87)
                      : (_isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight),
                ),
              ),
              if (selected && count > 0) ...[
                const SizedBox(width: 5),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 5,
                    vertical: 1,
                  ),
                  decoration: BoxDecoration(
                    color: category.color,
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Text(
                    '$count',
                    style: const TextStyle(
                      fontSize: 9,
                      fontWeight: FontWeight.w800,
                      color: Colors.white,
                    ),
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildRouteComparisonSummary() {
    if (availableRoutes.length <= 1) return const SizedBox.shrink();

    final recIdx = _recommendedRouteIndex;
    final safestIdx = _safestRouteIndex;
    final shortestIdx = _shortestRouteIndex;
    final fastestIdx = _fastestRouteIndex;

    _RouteResult? findRoute(int? idx) {
      if (idx == null) return null;
      for (final r in availableRoutes) {
        if (r.routeIndex == idx) return r;
      }
      return null;
    }

    final bestRoute = findRoute(recIdx);
    final safestRoute = findRoute(safestIdx);
    final shortestRoute = findRoute(shortestIdx);
    final fastestRoute = findRoute(fastestIdx);

    final bestScore = recIdx != null ? routeEvaluations[recIdx]?.safety.score : null;
    final safestScore = safestIdx != null ? routeEvaluations[safestIdx]?.safety.score : null;
    final shortestScore = shortestIdx != null ? routeEvaluations[shortestIdx]?.safety.score : null;
    final fastestScore = fastestIdx != null ? routeEvaluations[fastestIdx]?.safety.score : null;

    final categories = <Map<String, dynamic>>[
      if (bestRoute != null)
        {
          'label': 'BEST',
          'route': bestRoute,
          'color': _NeonTheme.safeGreen,
          'score': bestScore,
        },
      if (safestRoute != null)
        {
          'label': 'SAFEST',
          'route': safestRoute,
          'color': _NeonTheme.safeGreen,
          'score': safestScore,
        },
      if (shortestRoute != null)
        {
          'label': 'SHORTEST',
          'route': shortestRoute,
          'color': const Color(0xffF59E0B),
          'score': shortestScore,
        },
      if (fastestRoute != null)
        {
          'label': 'FASTEST',
          'route': fastestRoute,
          'color': const Color(0xff38BDF8),
          'score': fastestScore,
        },
    ];

    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardElevatedDark.withValues(alpha: 0.5)
            : const Color(0xffF8FAFC),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder.withValues(alpha: 0.35) : const Color(0xffE2E8F0),
          width: 0.9,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(
                Icons.analytics_rounded,
                size: 13,
                color: _NeonTheme.neonCyan,
              ),
              const SizedBox(width: 5),
              Text(
                _isTamil ? 'அறிவுசார் வழி ஒப்பீடு' : 'Intelligent Route Comparison',
                style: TextStyle(
                  fontSize: 10.5,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.4,
                  color: _isDarkMode ? Colors.white : const Color(0xff0F172A),
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          LayoutBuilder(
            builder: (context, constraints) {
              final isNarrow = constraints.maxWidth < 420;
              final tiles = categories.asMap().entries.map((entry) {
                final int idx = entry.key;
                final Map<String, dynamic> cat = entry.value;
                final String label = cat['label'] as String;
                final _RouteResult r = cat['route'] as _RouteResult;
                final Color color = cat['color'] as Color;
                final double? sc = cat['score'] as double?;
                final isSelected = r.routeIndex == selectedRouteIndex;

                final tileCard = InkWell(
                  onTap: () => _selectRoute(r),
                  borderRadius: BorderRadius.circular(8),
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 220),
                    curve: Curves.easeOutCubic,
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
                    decoration: BoxDecoration(
                      color: isSelected
                          ? color.withValues(alpha: 0.16)
                          : (_isDarkMode
                              ? const Color(0xff0B1528)
                              : Colors.white),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(
                        color: isSelected
                            ? color
                            : (_isDarkMode ? Colors.white12 : Colors.black12),
                        width: isSelected ? 1.4 : 0.8,
                      ),
                      boxShadow: isSelected
                          ? [
                              BoxShadow(
                                color: color.withValues(alpha: 0.35),
                                blurRadius: 8,
                                offset: const Offset(0, 1),
                              ),
                            ]
                          : (label == 'BEST'
                              ? [
                                  BoxShadow(
                                    color: color.withValues(alpha: 0.25),
                                    blurRadius: 6,
                                    offset: const Offset(0, 1),
                                  ),
                                ]
                              : null),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                              decoration: BoxDecoration(
                                color: color.withValues(alpha: 0.2),
                                borderRadius: BorderRadius.circular(4),
                                boxShadow: label == 'BEST'
                                    ? [
                                        BoxShadow(
                                          color: color.withValues(alpha: 0.35),
                                          blurRadius: 6,
                                          offset: const Offset(0, 1),
                                        ),
                                      ]
                                    : null,
                              ),
                              child: Text(
                                label,
                                style: TextStyle(
                                  fontSize: 7.5,
                                  fontWeight: FontWeight.w800,
                                  color: color,
                                ),
                              ),
                            ),
                            const SizedBox(width: 4),
                            Text(
                              'Route ${r.routeIndex + 1}',
                              style: TextStyle(
                                fontSize: 9.5,
                                fontWeight: FontWeight.w800,
                                color: isSelected
                                    ? color
                                    : (_isDarkMode ? Colors.white : const Color(0xff0F172A)),
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 3),
                        Text(
                          '${r.distance.toStringAsFixed(1)} km · ${formatDuration(service.calculateVehicleTime(r.distance, currentVehicle))}',
                          style: TextStyle(
                            fontSize: 9,
                            fontWeight: FontWeight.w600,
                            color: _isDarkMode ? Colors.white70 : const Color(0xff475569),
                          ),
                        ),
                        const SizedBox(height: 1),
                        Text(
                          sc != null
                              ? 'Safety: ${sc.round()}%'
                              : (_routeEvaluationLoading ? 'Evaluating...' : 'Score: N/A'),
                          style: TextStyle(
                            fontSize: 8.5,
                            fontWeight: FontWeight.w700,
                            color: sc != null ? _NeonTheme.safeGreen : (_isDarkMode ? Colors.white38 : Colors.black38),
                          ),
                        ),
                      ],
                    ),
                  ),
                );

                return _StaggeredEntrance(
                  delayMs: idx * 50,
                  slideOffset: const Offset(0.04, 0),
                  child: tileCard,
                );
              }).toList();

              if (isNarrow) {
                return Wrap(
                  spacing: 6,
                  runSpacing: 6,
                  children: tiles.map((t) => SizedBox(width: (constraints.maxWidth - 6) / 2, child: t)).toList(),
                );
              }

              return Row(
                children: tiles.map((t) => Expanded(child: Padding(padding: const EdgeInsets.symmetric(horizontal: 2), child: t))).toList(),
              );
            },
          ),
          if (routeRecommendation.isAvailable && routeRecommendation.reason.isNotEmpty) ...[
            const SizedBox(height: 6),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
              decoration: BoxDecoration(
                color: _NeonTheme.safeGreen.withValues(alpha: 0.08),
                borderRadius: BorderRadius.circular(6),
                border: Border.all(
                  color: _NeonTheme.safeGreen.withValues(alpha: 0.25),
                  width: 0.7,
                ),
              ),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Icon(
                    Icons.check_circle_outline_rounded,
                    size: 11,
                    color: _NeonTheme.safeGreen,
                  ),
                  const SizedBox(width: 5),
                  Expanded(
                    child: Text(
                      routeRecommendation.reason,
                      style: TextStyle(
                        fontSize: 9,
                        height: 1.25,
                        color: _isDarkMode ? Colors.white70 : const Color(0xff334155),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _buildAlternativeRoutePill(_RouteResult route) {
    final isSelected = route.routeIndex == selectedRouteIndex;
    final isRoute1 = route.routeIndex == 0;
    final badges = _getRouteCategoryBadges(route.routeIndex);
    final disableMotion = MediaQuery.maybeOf(context)?.disableAnimations ?? false;

    // Route 1 = Cyan / Electric Blue, Route 2 = Neon Violet
    final routeAccent = isRoute1 ? _NeonTheme.neonCyan : const Color(0xffC084FC);
    final routeBase = isRoute1 ? const Color(0xff0284C7) : const Color(0xff9333EA);
    final primaryColor = isSelected ? routeAccent : routeBase;
    final selectedBg = isRoute1
        ? (_isDarkMode ? const Color(0xff0B1F3D) : const Color(0xffEFF6FF))
        : (_isDarkMode ? const Color(0xff1C1033) : const Color(0xffFAF5FF));

    return _InteractivePressButton(
      onPressed: () => _selectRoute(route),
      child: AnimatedContainer(
        duration: disableMotion ? Duration.zero : const Duration(milliseconds: 240),
        curve: Curves.easeOutCubic,
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          color: isSelected
              ? selectedBg
              : (_isDarkMode
                    ? _NeonTheme.cardElevatedDark
                    : const Color(0xffF1F5F9)),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color: isSelected
                ? primaryColor
                : (_isDarkMode ? Colors.white12 : Colors.black12),
            width: isSelected ? 1.6 : 1,
          ),
          boxShadow: isSelected
              ? [
                  BoxShadow(
                    color: primaryColor.withValues(alpha: _isDarkMode ? 0.35 : 0.20),
                    blurRadius: 10,
                    spreadRadius: 1,
                    offset: const Offset(0, 2),
                  ),
                ]
              : null,
        ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Wrap(
                crossAxisAlignment: WrapCrossAlignment.center,
                spacing: 4,
                runSpacing: 2,
                children: [
                  Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(
                        isSelected
                            ? Icons.radio_button_checked_rounded
                            : Icons.radio_button_off_rounded,
                        size: 14,
                        color: isSelected
                            ? primaryColor
                            : (_isDarkMode
                                  ? _NeonTheme.textSecondaryDark
                                  : _NeonTheme.textSecondaryLight),
                      ),
                      const SizedBox(width: 5),
                      Text(
                        'Route ${route.routeIndex + 1}',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w800,
                          color: isSelected
                              ? primaryColor
                              : (_isDarkMode ? Colors.white : Colors.black87),
                        ),
                      ),
                    ],
                  ),
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 4,
                      vertical: 1,
                    ),
                    decoration: BoxDecoration(
                      color: isSelected
                          ? primaryColor.withValues(alpha: 0.2)
                          : routeBase.withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Text(
                      isSelected ? 'ACTIVE' : 'ALT',
                      style: TextStyle(
                        fontSize: 7.5,
                        fontWeight: FontWeight.w800,
                        color: isSelected
                            ? primaryColor
                            : routeBase,
                      ),
                    ),
                  ),
                  for (final b in badges) ...[
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 4,
                        vertical: 1,
                      ),
                      decoration: BoxDecoration(
                        color: _getRouteBadgeColor(b).withValues(alpha: 0.2),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: _getRouteBadgeColor(b).withValues(alpha: 0.5),
                          width: 0.6,
                        ),
                      ),
                      child: Text(
                        b,
                        style: TextStyle(
                          fontSize: 7.5,
                          fontWeight: FontWeight.w800,
                          color: _getRouteBadgeColor(b),
                        ),
                      ),
                    ),
                  ],
                  if (_personalProfile.isConfigured &&
                      routeEvaluations.containsKey(route.routeIndex)) ...[
                    Builder(
                      builder: (context) {
                        final m = PreferenceMatchEvaluator.evaluate(
                          evaluation: routeEvaluations[route.routeIndex]!,
                          profile: _personalProfile,
                          isDay: _isDaytimeTravel(currentTravelTime),
                        );
                        return Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 4,
                            vertical: 1,
                          ),
                          decoration: BoxDecoration(
                            color: m.matchColor.withValues(alpha: 0.18),
                            borderRadius: BorderRadius.circular(4),
                          ),
                          child: Text(
                            '${m.matchPercentage.round()}% MATCH',
                            style: TextStyle(
                              fontSize: 7.5,
                              fontWeight: FontWeight.w800,
                              color: m.matchColor,
                            ),
                          ),
                        );
                      },
                    ),
                  ],
                ],
              ),
              const SizedBox(height: 3),
              Text(
                '${route.distance.toStringAsFixed(1)} km · ${formatDuration(service.calculateVehicleTime(route.distance, currentVehicle))}',
                style: TextStyle(
                  fontSize: 10,
                  color: _isDarkMode
                      ? _NeonTheme.textSecondaryDark
                      : _NeonTheme.textSecondaryLight,
                ),
              ),
              const SizedBox(height: 2),
              Builder(
                builder: (context) {
                  final eval = routeEvaluations[route.routeIndex];
                  final sc = eval?.safety.score;
                  final hasScore = sc != null;
                  final scoreColor = hasScore
                      ? (sc >= 80 ? _NeonTheme.safeGreen : const Color(0xffF59E0B))
                      : (_isDarkMode ? Colors.white38 : Colors.black38);

                  return Row(
                    children: [
                      Icon(
                        Icons.shield_rounded,
                        size: 11,
                        color: scoreColor,
                      ),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Text(
                          hasScore
                              ? 'Safety Score ${sc.round()}%'
                              : (_routeEvaluationLoading
                                  ? 'Evaluating safety...'
                                  : 'Safety score unavailable'),
                          style: TextStyle(
                            fontSize: 9.5,
                            fontWeight: FontWeight.w700,
                            color: scoreColor,
                          ),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ],
                  );
                },
              ),
              const SizedBox(height: 6),
              _buildAlternativeWhyRouteButton(route, isSelected),
            ],
          ),
        ),
    );
  }

