  Widget _buildSafetyFactorsBreakdown() {
    final factors = personalizedSafetyResult.factors;
    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: _isDarkMode ? _NeonTheme.cardDark : _NeonTheme.cardLight,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: _isDarkMode ? _NeonTheme.cyanBorder : const Color(0xffE2E8F0),
          width: 1.2,
        ),
        boxShadow: _NeonTheme.cardShadow(_isDarkMode),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              Icon(
                Icons.analytics_rounded,
                color: _isDarkMode ? _NeonTheme.neonCyan : const Color(0xff2563EB),
                size: 18,
              ),
              const SizedBox(width: 8),
              Text(
                'TRIP SAFETY FACTORS BREAKDOWN',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.8,
                  color: _isDarkMode
                      ? _NeonTheme.neonCyan
                      : _NeonTheme.electricBlue,
                ),
              ),
            ],
          ),
          const SizedBox(height: 14),
          for (final factor in factors) ...[
            _buildFactorBar(factor),
            const SizedBox(height: 12),
          ],
          const SizedBox(height: 6),
          _buildSafetyScoreTransparencyTable(),
        ],
      ),
    );
  }

  Widget _buildFactorBar(SafetyFactor factor) {
    final isIncluded = factor.score != null && factor.relevant;
    final score = factor.score ?? 0.0;
    final barColor = isIncluded
        ? (score >= 70
              ? _NeonTheme.safeGreen
              : score >= 40
              ? _NeonTheme.warningGold
              : _NeonTheme.dangerRed)
        : (_isDarkMode ? Colors.white24 : Colors.black26);

    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardElevatedDark
            : const Color(0xffF1F5F9),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: _isDarkMode ? Colors.white10 : Colors.black12,
          width: 1,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Title + Status + Weight + Score
          Row(
            children: [
              Icon(
                factor.icon,
                size: 16,
                color: isIncluded
                    ? barColor
                    : (_isDarkMode
                          ? _NeonTheme.textSecondaryDark
                          : _NeonTheme.textSecondaryLight),
              ),
              const SizedBox(width: 8),
              Text(
                isIncluded ? '✓ ' : '— ',
                style: TextStyle(
                  fontSize: 12.5,
                  fontWeight: FontWeight.w900,
                  color: isIncluded
                      ? _NeonTheme.safeGreen
                      : (_isDarkMode ? Colors.white38 : Colors.black38),
                ),
              ),
              Text(
                factor.title,
                style: TextStyle(
                  fontSize: 12.5,
                  fontWeight: FontWeight.w700,
                  color: _isDarkMode
                      ? _NeonTheme.textPrimaryDark
                      : _NeonTheme.textPrimaryLight,
                ),
              ),
              const SizedBox(width: 6),
              Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 5,
                  vertical: 1,
                ),
                decoration: BoxDecoration(
                  color: isIncluded
                      ? _NeonTheme.safeGreen.withValues(alpha: 0.15)
                      : (_isDarkMode ? Colors.white10 : Colors.black.withValues(alpha: 0.05)),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  isIncluded ? 'Verified' : 'Unavailable',
                  style: TextStyle(
                    fontSize: 9,
                    fontWeight: FontWeight.w700,
                    color: isIncluded
                        ? (_isDarkMode ? _NeonTheme.safeGreen : const Color(0xff15803D))
                        : (_isDarkMode ? Colors.white38 : Colors.black38),
                  ),
                ),
              ),
              const SizedBox(width: 6),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 1),
                decoration: BoxDecoration(
                  color: isIncluded
                      ? (_isDarkMode
                          ? _NeonTheme.neonCyan.withValues(alpha: 0.12)
                          : const Color(0xff2563EB).withValues(alpha: 0.10))
                      : (_isDarkMode ? Colors.white10 : Colors.black12),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  isIncluded && factor.weight > 0
                      ? '${(factor.weight * 100).toStringAsFixed(0)}% weight'
                      : 'Excluded from score',
                  style: TextStyle(
                    fontSize: 9,
                    fontWeight: FontWeight.w700,
                    color: isIncluded
                        ? (_isDarkMode ? _NeonTheme.neonCyan : const Color(0xff2563EB))
                        : (_isDarkMode
                              ? _NeonTheme.textSecondaryDark
                              : _NeonTheme.textSecondaryLight),
                  ),
                ),
              ),
              const Spacer(),
              Text(
                isIncluded
                    ? '${score.toStringAsFixed(0)}%'
                    : 'Unavailable',
                style: TextStyle(
                  fontSize: 12.5,
                  fontWeight: FontWeight.w800,
                  color: isIncluded
                      ? barColor
                      : (_isDarkMode
                            ? _NeonTheme.textSecondaryDark
                            : _NeonTheme.textSecondaryLight),
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          // Futuristic Neon Progress Track
          Stack(
            children: [
              Container(
                height: 5.5,
                decoration: BoxDecoration(
                  color: _isDarkMode ? Colors.white10 : Colors.black12,
                  borderRadius: BorderRadius.circular(3),
                ),
              ),
              if (isIncluded)
                TweenAnimationBuilder<double>(
                  key: ValueKey('factor_bar_${factor.title}_${score.round()}'),
                  tween: Tween<double>(
                    begin: 0.0,
                    end: (score / 100).clamp(0.0, 1.0),
                  ),
                  duration: const Duration(milliseconds: 700),
                  curve: Curves.easeOutCubic,
                  builder: (context, animFactor, _) {
                    return FractionallySizedBox(
                      widthFactor: animFactor,
                      child: Container(
                        height: 5.5,
                        decoration: BoxDecoration(
                          color: barColor,
                          borderRadius: BorderRadius.circular(3),
                          boxShadow: _isDarkMode
                              ? [
                                  BoxShadow(
                                    color: barColor.withValues(alpha: 0.5),
                                    blurRadius: 4,
                                  ),
                                ]
                              : null,
                        ),
                      ),
                    );
                  },
                ),
            ],
          ),
          const SizedBox(height: 5),
          // Reason / Detail
          Text(
            isIncluded
                ? '✓ ${factor.scoreLabel.isNotEmpty ? factor.scoreLabel : 'Included · ${(factor.weight * 100).toStringAsFixed(0)}% normalized weight'}'
                : !factor.relevant
                ? 'âœ— ${factor.unavailableReason ?? 'Not relevant for $currentTravelTime travel'}'
                : '⚠ ${factor.unavailableReason ?? 'Data unavailable on checked segments'}',
            style: TextStyle(
              fontSize: 10,
              color: isIncluded
                  ? barColor
                  : (_isDarkMode
                        ? _NeonTheme.textSecondaryDark
                        : _NeonTheme.textSecondaryLight),
            ),
          ),
if (factor.source != null && isIncluded) ...[
            const SizedBox(height: 2),
            Text(
              'Source: ${factor.source}',
              style: TextStyle(
                fontSize: 9.5,
                color: _isDarkMode
                    ? _NeonTheme.textSecondaryDark
                    : _NeonTheme.textSecondaryLight,
              ),
            ),
          ],
        ],
      ),
    );
  }

