    final currentEval = routeEvaluations[selectedRouteIndex];
    final weatherTime = currentEval?.weather != null
        ? _formatTimeAgo(currentEval!.weather!.fetchedAt)
        : (weather != null ? _formatTimeAgo(weather!.fetchedAt) : 'offline');

    return Container(
      decoration: BoxDecoration(
        color: _isDarkMode
            ? _NeonTheme.cardElevatedDark
            : const Color(0xffF8FAFC),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: _isDarkMode
              ? _NeonTheme.cyanBorder.withValues(alpha: 0.35)
              : const Color(0xffE2E8F0),
          width: 1,
        ),
