  Widget _buildTripsFilterChip(String filter) {
    final isSelected = _tripsFilterMode == filter;
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: () => setState(() => _tripsFilterMode = filter),
        borderRadius: BorderRadius.circular(8),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
          decoration: BoxDecoration(
            color: isSelected
                ? _NeonTheme.neonCyan.withValues(alpha: 0.16)
                : (_isDarkMode
                      ? _NeonTheme.cardElevatedDark
                      : const Color(0xffF1F5F9)),
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: isSelected
                  ? _NeonTheme.neonCyan
                  : (_isDarkMode ? Colors.white10 : Colors.black12),
              width: isSelected ? 1.4 : 1,
            ),
          ),

          child: Text(
            filter,
            style: TextStyle(
              fontSize: 11,
              fontWeight: isSelected ? FontWeight.w800 : FontWeight.w600,
              color: isSelected
                  ? _NeonTheme.neonCyan
                  : (_isDarkMode
                        ? _NeonTheme.textSecondaryDark
                        : _NeonTheme.textSecondaryLight),
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _confirmClearAllTrips() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogCtx) => AlertDialog(
        backgroundColor: _isDarkMode
            ? _NeonTheme.cardDark
            : _NeonTheme.cardLight,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(18),
          side: BorderSide(
            color: _isDarkMode
                ? _NeonTheme.cyanBorder
                : const Color(0xffE2E8F0),
          ),
        ),
        title: Text(
          'Clear all saved trips?',
          style: TextStyle(
            fontSize: 16,
            fontWeight: FontWeight.w800,
            color: _isDarkMode
                ? _NeonTheme.textPrimaryDark
                : _NeonTheme.textPrimaryLight,
          ),
        ),
        content: Text(
          'This will remove all saved trips from your browser storage.',
          style: TextStyle(
            fontSize: 13,
            color: _isDarkMode
                ? _NeonTheme.textSecondaryDark
                : _NeonTheme.textSecondaryLight,
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogCtx).pop(false),
            child: Text(
              'Cancel',
              style: TextStyle(
                color: _isDarkMode
                    ? _NeonTheme.textSecondaryDark
                    : _NeonTheme.textSecondaryLight,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: _NeonTheme.dangerRed,
              foregroundColor: Colors.white,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(10),
              ),
            ),
            onPressed: () => Navigator.of(dialogCtx).pop(true),
            child: const Text(
              'Clear All',
              style: TextStyle(fontWeight: FontWeight.w800),
            ),
          ),
        ],
      ),
    );

    if (confirmed == true) {
      setState(() {
        _savedTrips.clear();
      });
      await _persistSavedTrips();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('All trips cleared'),
            backgroundColor: _NeonTheme.electricBlue,
          ),
        );
      }
    }
  }

  Widget _buildSavedTripCard(_SavedTrip trip) {
    final score = trip.safetyScore;
    final scoreColor = score != null && score >= 70
        ? _NeonTheme.safeGreen
        : score != null && score >= 40
            ? _NeonTheme.warningGold
            : _NeonTheme.dangerRed;

    final imageAsset = _getRouteLandscapeAsset(
      origin: trip.origin,
      destination: trip.destination,
      routeLabel: trip.routeLabel,
    );
    final categoryTag = _getRouteCategoryTag(
      origin: trip.origin,
      destination: trip.destination,
      routeLabel: trip.routeLabel,
    );
    final categoryColor = _getRouteCategoryColor(categoryTag);

    return GlassCard(
      borderRadius: BorderRadius.circular(18),
      enableHover: true,
      border: Border.all(
        color: _isDarkMode
            ? _NeonTheme.cyanBorder.withValues(alpha: 0.4)
            : const Color(0xffCBD5E1),
        width: 1.2,
      ),
      padding: EdgeInsets.zero,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          // Top Landscape Thumbnail Banner
          SizedBox(
            height: 72,
            child: Stack(
              fit: StackFit.expand,
              children: [
                ClipRRect(
                  borderRadius:
                      const BorderRadius.vertical(top: Radius.circular(18)),
                  child: Image.asset(
                    imageAsset,
                    fit: BoxFit.cover,
                    errorBuilder: (context, error, stackTrace) => Container(
                      color: _isDarkMode
                          ? const Color(0xff06152D)
                          : const Color(0xffE2E8F0),
                      child: Center(
                        child: Icon(Icons.route_rounded,
                            color: categoryColor, size: 24),
                      ),
                    ),
                  ),
                ),
                Positioned.fill(
                  child: Container(
                    decoration: BoxDecoration(
                      borderRadius:
                          const BorderRadius.vertical(top: Radius.circular(18)),
                      gradient: LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: [
                          Colors.transparent,
                          (_isDarkMode
                                  ? _NeonTheme.cardDark
                                  : _NeonTheme.cardLight)
                              .withValues(alpha: 0.90),
                        ],
                      ),
                    ),
                  ),
                ),
                // Route Category Pill on top left
                Positioned(
                  top: 8,
                  left: 10,
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
                    decoration: BoxDecoration(
                      color: (_isDarkMode
                              ? const Color(0xff020B1C)
                              : Colors.white)
                          .withValues(alpha: 0.88),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(
                        color: categoryColor.withValues(alpha: 0.5),
                        width: 0.8,
                      ),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
