  Widget _buildSafetyAnalyticsView() {
    final activeEval =
        routeEvaluations.isNotEmpty &&
            selectedRouteIndex < routeEvaluations.length
        ? routeEvaluations[selectedRouteIndex]
        : null;
    return SafetyAnalyticsDashboardView(
      isDarkMode: _isDarkMode,
      activeRouteEvaluation: activeEval,
      personalProfile: _personalProfile,
      onPlanRoute: () => setState(() => _currentTab = _DashboardTab.planRoute),
      onViewSavedRoute: (record) {
        final trip = _SavedTrip(
          id: record.id,
          origin: record.origin,
          destination: record.destination,
          distanceKm: record.distanceKm,
          durationMinutes: record.durationMinutes,
          safetyScore: record.safetyScore,
          routeIndex: 0,
          vehicleMode: record.vehicleMode,
          travelTimeMode: record.travelTimeMode,
          createdAt: record.createdAt,
          trafficStatus: record.trafficStatus,
          weatherScore: record.weatherScore,
          routeLabel: record.routeLabel,
        );
        _viewSavedTripRoute(trip);
      },
      onOpenRiskForecast: _openRiskForecastDialog,
      onOpenWhyThisRoute: () => _showWhyThisRouteDialog(),
      onOpenSafetyProfile: _openSafetyProfileDialog,
    );
  }

