  void _onStartJourneyButtonPressed() {
    if (!_hasSearchedRoute || routePoints.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            _isTamil
                ? 'பயணத்தைத் தொடங்க முதலில் ஒரு வழியைத் திட்டமிடுங்கள்'
                : 'Please calculate a route first before starting a journey',
          ),
          backgroundColor: _NeonTheme.cardDark,
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }

    if (availableRoutes.isNotEmpty &&
        selectedRouteIndex >= 0 &&
        selectedRouteIndex < availableRoutes.length) {
      final selectedRoute = availableRoutes[selectedRouteIndex];
      routePoints = selectedRoute.points;
      distanceKm = selectedRoute.distance;
      durationMinutes = service.calculateVehicleTime(
        selectedRoute.distance,
        currentVehicle,
      );
    }

    final currentScore =
        safetyScore ?? routeEvaluations[selectedRouteIndex]?.safety.score;
    final traffic = routeEvaluations[selectedRouteIndex]?.traffic;
    final trafficStatus = traffic != null && traffic.coveragePercent > 0
        ? traffic.status
        : null;

    final weatherScore = _calculateWeatherSafetyScore(weather);
    final weatherCond = weather != null ? weatherText(weather) : null;
    final weatherTemp = weather != null
        ? '${weather!.temperature.round()}°C'
        : null;

    final originText = fromController.text.trim().isNotEmpty
        ? fromController.text.trim()
        : (currentFrom.trim().isNotEmpty
              ? currentFrom.trim()
              : 'Active Origin');
    final destinationText = toController.text.trim().isNotEmpty
        ? toController.text.trim()
        : (currentTo.trim().isNotEmpty
              ? currentTo.trim()
              : 'Active Destination');

    String? rLevel;
    String? rSummary;
    try {
      final forecast = SmartRiskForecastEngine.evaluate(
        evaluation: routeEvaluations[selectedRouteIndex],
        vehicle: currentVehicle,
        travelTime: currentTravelTime,
      );
      rLevel = forecast.overallLevel.name;
      rSummary = forecast.whyRiskNarrative;
    } catch (_) {
      rLevel = null;
      rSummary = null;
    }

    final badge = _getRouteFullBadgeLabel(selectedRouteIndex);
    final dynamicRouteLabel = badge.isNotEmpty
        ? 'Route ${selectedRouteIndex + 1} • $badge'
        : 'Route ${selectedRouteIndex + 1}';

    final newJourney = SafeRouteJourney(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      origin: originText,
      destination: destinationText,
      routeIndex: selectedRouteIndex,
      routeLabel: dynamicRouteLabel,
      routeSafetyScore: currentScore,
      distanceKm: distanceKm,
      estimatedDurationMinutes: durationMinutes,
      vehicleMode: currentVehicle,
      travelTimeMode: currentTravelTime,
      startedTimestamp: DateTime.now(),
      journeyState: JourneyState.active,
      trafficStatus: trafficStatus,
      weatherScore: weatherScore,
      weatherCondition: weatherCond,
      weatherTemperature: weatherTemp,
      riskLevel: rLevel,
      riskExplanation: rSummary,
      roadReportsSubmitted: 0,
      nearbyPlacesViewed: facilities.length,
    );

    setState(() {
      _activeJourney = newJourney;
      _currentTab = _DashboardTab.journeyMode;
      _followMe = true;
    });

    if (!_navigationActive) {
      unawaited(_startNavigation());
    }

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          _isTamil
              ? '🚗 SafeRoute பயணம் தொடங்கியது! பாதுகாப்புத் தரவு கண்காணிக்கப்படுகிறது.'
              : '🚗 SafeRoute Journey started! Real-time safety is being monitored.',
        ),
        backgroundColor: NeonTheme.cardDark,
        behavior: SnackBarBehavior.floating,
        duration: const Duration(seconds: 3),
      ),
    );
  }

  void _onPauseJourney() {
    if (_activeJourney == null) return;
    if (_activeTripSharingSession != null && currentPosition != null) {
      unawaited(
        LiveTripSharingService.updateLocation(
          updateToken: _activeTripSharingSession!.updateToken,
          latitude: currentPosition!.latitude,
          longitude: currentPosition!.longitude,
          status: 'paused',
        ),
      );
    }
    setState(() {
      _activeJourney = _activeJourney!.copyWith(
        journeyState: JourneyState.paused,
      );
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(_isTamil ? 'பயணம் இடைநிறுத்தப்பட்டது' : 'Journey paused'),
        duration: const Duration(seconds: 2),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  void _onResumeJourney() {
    if (_activeJourney == null) return;
    if (_activeTripSharingSession != null && currentPosition != null) {
      unawaited(
        LiveTripSharingService.updateLocation(
          updateToken: _activeTripSharingSession!.updateToken,
          latitude: currentPosition!.latitude,
          longitude: currentPosition!.longitude,
          status: 'active',
        ),
      );
    }
    setState(() {
      _activeJourney = _activeJourney!.copyWith(
        journeyState: JourneyState.active,
      );
      _followMe = true;
    });
    if (!_navigationActive) {
      unawaited(_startNavigation());
    }
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          _isTamil ? 'பயணம் மீண்டும் தொடங்கப்பட்டது' : 'Journey resumed',
        ),
        duration: const Duration(seconds: 2),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  Future<void> _onEndJourney({bool isCancel = false}) async {
    if (_activeJourney == null) return;
    if (_navigationActive) {
      unawaited(_stopNavigation());
    }
    final completed = _activeJourney!.copyWith(
      endedTimestamp: DateTime.now(),
      journeyState: isCancel ? JourneyState.cancelled : JourneyState.completed,
    );

    await JourneyHistoryService.saveJourney(completed);

    setState(() {
      _activeJourney = null;
    });

    if (_activeTripSharingSession != null) {
      final updateTok = _activeTripSharingSession!.updateToken;
      final destName = _activeTripSharingSession!.destination;
      _activeTripSharingSession = null;
      if (isCancel) {
        unawaited(LiveTripSharingService.stopSharing(updateTok));
      } else {
        unawaited(LiveTripSharingService.completeTrip(updateTok));
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) {
            showDialog<void>(
              context: context,
              barrierDismissible: true,
              builder: (ctx) => SafeArrivalDialog(
                destination: destName,
                isDarkMode: _isDarkMode,
                isTamil: _isTamil,
              ),
            );
          }
        });
      }
    }

    if (!mounted) return;

    await showDialog<void>(
      context: context,
      builder: (dialogContext) => JourneySummaryDialog(
        journey: completed,
        isDarkMode: _isDarkMode,
        onViewHistory: () {
          Navigator.of(dialogContext).pop();
          setState(() {
            _currentTab = _DashboardTab.journeyMode;
          });
        },
      ),
    );
  }

  void _onRefreshJourneySafety() {
    if (_activeJourney == null) return;
    final currentScore =
        safetyScore ?? routeEvaluations[selectedRouteIndex]?.safety.score;
    final traffic = routeEvaluations[selectedRouteIndex]?.traffic;
    final trafficStatus = traffic != null && traffic.coveragePercent > 0
        ? traffic.status
        : null;

    setState(() {
      _activeJourney = _activeJourney!.copyWith(
        routeSafetyScore: currentScore ?? _activeJourney!.routeSafetyScore,
        trafficStatus: trafficStatus ?? _activeJourney!.trafficStatus,
        weatherScore:
            _calculateWeatherSafetyScore(weather) ??
            _activeJourney!.weatherScore,
        weatherCondition:
            (weather != null ? weatherText(weather) : null) ??
            _activeJourney!.weatherCondition,
        weatherTemperature: weather != null
            ? '${weather!.temperature.round()}°C'
            : _activeJourney!.weatherTemperature,
      );
    });

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          _isTamil
              ? 'பயண பாதுகாப்பு அளவீடுகள் புதுப்பிக்கப்பட்டன'
              : 'Journey safety metrics refreshed',
        ),
        duration: const Duration(seconds: 2),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  Widget _buildJourneyModeView() {
    final totalMeters = _calculateTotalRouteMeters(routePoints);
    final currentProgress =
        _getCurrentUserRouteProgressMeters().clamp(0.0, totalMeters);
    final traveledKm = currentProgress / 1000.0;
    final remainingMeters = math.max(0.0, totalMeters - currentProgress);
    final remainingKm = remainingMeters / 1000.0;
    final progressFraction = totalMeters > 0
        ? (currentProgress / totalMeters).clamp(0.0, 1.0)
        : 0.0;
    final progressPercent = (progressFraction * 100).round();
    final remainingMinutes =
        service.calculateVehicleTime(remainingKm, currentVehicle).round();

    final navStatus = !_navigationActive
        ? 'GPS unavailable'
        : (_isOffRoute
            ? 'Off Route'
            : (_destinationStage == _DestinationProximityStage.reached
                ? 'Arrived'
                : 'On Route'));

    return SafeRouteJourneyModeView(
      isDarkMode: _isDarkMode,
      activeJourney: _activeJourney,
      personalProfile: _personalProfile,
      mapWidget: _mapView(isLiveNavigation: true),
      currentPosition: currentPosition,
      isNavigationActive: _navigationActive,
      isOffRoute: _isOffRoute,
      distanceFromRouteMeters: _distanceFromRouteMeters,
      navigationStatus: navStatus,
      distanceRemainingKm: remainingKm,
      traveledKm: traveledKm,
      progressPercent: progressPercent,
      etaMinutes: remainingMinutes,
      isFollowingUser: _followMe,
      onToggleFollowMe: _toggleFollowMe,
      onStartJourney: _onStartJourneyButtonPressed,
      onPauseJourney: _onPauseJourney,
      onResumeJourney: _onResumeJourney,
      onEndJourney: () => _onEndJourney(),
      onRefreshSafety: _onRefreshJourneySafety,
      onOpenEmergency: _openEmergencyDialog,
      onOpenNearbyPlaces: (category) {
        if (category != null) {
          final match = _facilityCategories.where(
            (c) =>
                c.selectorLabel.toLowerCase().contains(
                  category.toLowerCase(),
                ) ||
                c.label.toLowerCase().contains(category.toLowerCase()),
          );
          if (match.isNotEmpty) {
            _selectedFacilityCategories.clear();
            _selectedFacilityCategories.add(match.first.selectorLabel);
          }
        }
        setState(() {
          _currentTab = _DashboardTab.nearbyPlaces;
        });
      },
      onReportRoadProblem: _openReportProblemDialog,
      onOpenSafetyProfile: _openSafetyProfileDialog,
      onOpenRiskForecast: () => _openRiskForecastDialog(),
      onPlanRoute: () {
        setState(() {
          _currentTab = _DashboardTab.planRoute;
        });
      },
    );
  }

