            badgeColor: _NeonTheme.safeGreen,
            icon: Icons.groups_rounded,
            trailing: SafeRoutePrimaryButton(
              label: _isTamil ? 'அபாயத்தை தெரிவிக்கவும்' : 'Report Road Hazard',
