  Widget _facilityPanelStatus(List<_FacilityCategory> selected) {
    final String message;
    final Color iconColor;
    final IconData icon;
    if (_isLoadingFacilities) {
      message = 'Finding real facilities along this route...';
      iconColor = _NeonTheme.neonCyan;
      icon = Icons.sync_rounded;
    } else if (_facilitiesUnavailable ||
        (_facilityResultsIncomplete && facilities.isEmpty)) {
      message = 'Facility service temporarily unavailable.';
      iconColor = _NeonTheme.dangerRed;
      icon = Icons.cloud_off_rounded;
    } else if (facilities.isNotEmpty) {
      message = '${facilities.length} real facilities found along this route.';
      iconColor = _NeonTheme.safeGreen;
      icon = Icons.check_circle_outline_rounded;
    } else {
      message = 'No mapped facilities found along this route.';
      iconColor = _isDarkMode
          ? _NeonTheme.textSecondaryDark
          : _NeonTheme.textSecondaryLight;
      icon = Icons.search_off_rounded;
    }

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
      decoration: BoxDecoration(
        color: iconColor.withValues(alpha: 0.1),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: iconColor.withValues(alpha: 0.3), width: 1),
      ),
      child: Row(
        children: [
          Icon(icon, size: 14, color: iconColor),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              message,
              style: TextStyle(
                fontSize: 11.5,
                fontWeight: FontWeight.w600,
                color: _isDarkMode
                    ? _NeonTheme.textPrimaryDark
                    : _NeonTheme.textPrimaryLight,
              ),
            ),
          ),
          if (!_isLoadingFacilities &&
              (_facilitiesUnavailable || _facilityResultsIncomplete))
            TextButton(
              style: TextButton.styleFrom(
                visualDensity: VisualDensity.compact,
                padding: const EdgeInsets.symmetric(horizontal: 8),
              ),
              onPressed: () => unawaited(_retryFacilitySearch()),
              child: const Text(
                'Retry',
                style: TextStyle(fontSize: 11, color: _NeonTheme.neonCyan),
              ),
            ),
        ],
      ),
    );
  }

