class _FeedbackDialog extends StatefulWidget {
  final SafeRouteService service;
  final bool isDarkMode;

  const _FeedbackDialog({required this.service, required this.isDarkMode});

  @override
  State<_FeedbackDialog> createState() => _FeedbackDialogState();
}

class _FeedbackDialogState extends State<_FeedbackDialog> {
  int _rating = 5;
  String _selectedCategory = 'Route Problem';
  final TextEditingController _commentController = TextEditingController();
  final TextEditingController _emailController = TextEditingController();
  bool _isSubmitting = false;
  String? _errorMessage;
  bool _isSuccess = false;

  static const List<String> _categories = [
    'Route Problem',
    'Safety Information',
    'Traffic Information',
    'Map Problem',
    'Accessibility',
    'Feature Request',
    'Other',
  ];

  static const List<Map<String, dynamic>> _ratingOptions = [
    {'score': 1, 'emoji': '😡', 'label': 'Very Poor'},
    {'score': 2, 'emoji': '😕', 'label': 'Poor'},
    {'score': 3, 'emoji': '😐', 'label': 'Average'},
    {'score': 4, 'emoji': '🙂', 'label': 'Good'},
    {'score': 5, 'emoji': '🤩', 'label': 'Excellent'},
  ];

  @override
  void dispose() {
    _commentController.dispose();
    _emailController.dispose();
    super.dispose();
  }

  Future<void> _handleSubmit() async {
    final comment = _commentController.text.trim();
    if (comment.isEmpty) {
      setState(() {
        _errorMessage = 'Please enter your comments or feedback.';
      });
      return;
    }

    if (_rating < 1 || _rating > 5) {
      setState(() {
        _errorMessage = 'Please select a rating between 1 and 5.';
      });
      return;
    }

    setState(() {
      _isSubmitting = true;
      _errorMessage = null;
    });

    try {
      final result = await widget.service.submitUserFeedback(
        rating: _rating,
        category: _selectedCategory,
        comment: comment,
        email: _emailController.text.trim().isNotEmpty
            ? _emailController.text.trim()
            : null,
      );

      if (!mounted) return;

      if (result['success'] == true) {
        setState(() {
          _isSubmitting = false;
          _isSuccess = true;
          _errorMessage = null;
          _commentController.clear();
          _emailController.clear();
          _rating = 5;
          _selectedCategory = 'Route Problem';
        });
      } else {
        setState(() {
          _isSubmitting = false;
          _errorMessage =
              result['error']?.toString() ?? 'Failed to submit feedback.';
        });
      }
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _isSubmitting = false;
        _errorMessage = 'Failed to submit feedback: $e';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final isDark = widget.isDarkMode;
    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 24),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 480),
        child: Container(
          padding: const EdgeInsets.all(22),
          decoration: BoxDecoration(
            color: isDark ? _NeonTheme.cardDark : _NeonTheme.cardLight,
            borderRadius: BorderRadius.circular(24),
            border: Border.all(
              color: isDark ? _NeonTheme.cyanBorder : const Color(0xffE2E8F0),
              width: 1.3,
            ),
            boxShadow: _NeonTheme.cardShadow(isDark),
          ),
          child: SingleChildScrollView(
            child: _isSuccess ? _buildSuccessContent() : _buildFormContent(),
          ),
        ),
      ),
    );
  }

