}

class RouteExplanationEngine {
  static WhyThisRouteAnalysis generate({
    required _RouteEvaluation targetEvaluation,
    required Map<int, _RouteEvaluation> allEvaluations,
    required String origin,
    required String destination,
    required String vehicle,
    required String travelTime,
    required String priority,
    required SafeRouteService service,
    required String Function(double minutes) formatDurationFn,
  }) {
    final safety = targetEvaluation.safety;
    final isDay = travelTime == 'Day';

    SafetyFactor? findFactor(String key) {
      for (final f in safety.factors) {
        if (f.title == key ||
            (key == 'Accident Risk' && f.title == 'Verified blackspots') ||
            (key == 'Road Condition' && f.title == 'Road condition') ||
            (key == 'Traffic' && f.title == 'Live Traffic')) {
          return f;
        }
      }
      return null;
    }

    // 1. Accident Risk
    final accFactor = findFactor('Accident Risk');
    final accScore = accFactor?.score;
    final isAccAvailable =
        accFactor != null && accFactor.relevant && accScore != null;
    final String accComm;
    final String tamilAccComm;
    if (isAccAvailable) {
      if (accScore >= 70) {
        accComm = 'This route has a relatively lower accident-risk score.';
        tamilAccComm =
            'இந்த வழி ஒப்பீட்டளவில் குறைவான விபத்து அபாயத்தைக் கொண்டுள்ளது.';
      } else if (accScore >= 40) {
        accComm = 'Moderate accident risk observed along monitored sections.';
        tamilAccComm =
            'கண்காணிக்கப்படும் பகுதிகளில் மிதமான விபத்து அபாயம் உள்ளது.';
      } else {
        accComm = 'Higher accident risk detected along sections of this route.';
        tamilAccComm = 'இந்த வழியின் சில பகுதிகளில் அதிக விபத்து அபாயம் கண்டறியப்பட்டுள்ளது.';
      }
    } else {
      accComm = 'Accident risk data is currently unavailable, so it was not included in this explanation.';
      tamilAccComm = 'விபத்து அபாய தரவு தற்போது கிடைக்கவில்லை, எனவே இது சேர்க்கப்படவில்லை.';
    }

    // 2. Road Condition
    final roadFactor = findFactor('Road Condition');
    final roadScore = roadFactor?.score;
    final isRoadAvailable =
        roadFactor != null && roadFactor.relevant && roadScore != null;
    final String roadComm;
    final String tamilRoadComm;
    if (isRoadAvailable) {
      if (roadScore >= 65) {
        roadComm = 'Road conditions on this route are comparatively better.';
        tamilRoadComm =
            'இந்த வழியில் சாலை நிலைகள் ஒப்பீட்டளவில் சிறப்பாக உள்ளன.';
      } else if (roadScore >= 40) {
        roadComm = 'Moderate road conditions with mixed pavement quality.';
        tamilRoadComm = 'மிதமான சாலை நிலைகள் மற்றும் கலவையான தரம்.';
      } else {
        roadComm =
            'Rougher or unpaved road segments detected along this corridor.';
        tamilRoadComm = 'கரடுமுரடான அல்லது செப்பனிடப்படாத சாலைப் பகுதிகள் கண்டறியப்பட்டுள்ளன.';
      }
    } else {
      roadComm = 'Road condition data is currently unavailable, so it was not included in this explanation.';
      tamilRoadComm =
          'சாலை நிலை தரவு தற்போது கிடைக்கவில்லை, எனவே இது சேர்க்கப்படவில்லை.';
    }

    // 3. Traffic
    final trafficFactor = findFactor('Traffic');
    final trafficScore = trafficFactor?.score;
    final isTrafficAvailable =
        trafficFactor != null && trafficFactor.relevant && trafficScore != null;
    final String trafficComm;
    final String tamilTrafficComm;
    if (isTrafficAvailable) {
      if (trafficScore >= 70 ||
          targetEvaluation.traffic?.status == 'Low Traffic') {
        trafficComm = 'Current traffic conditions are favorable.';
        tamilTrafficComm = 'தற்போதைய போக்குவரத்து நிலை சாதகமாக உள்ளது.';
      } else if (trafficScore >= 40 ||
          targetEvaluation.traffic?.status == 'Moderate Traffic') {
        trafficComm =
            'Moderate traffic conditions observed with manageable speeds.';
        tamilTrafficComm =
            'நிர்வகிக்கக்கூடிய வேகத்துடன் மிதமான போக்குவரத்து காணப்படுகிறது.';
      } else {
        trafficComm = 'Heavy traffic congestion or reduced speeds reported on this route.';
        tamilTrafficComm = 'அதிக போக்குவரத்து நெரிசல் அல்லது மெதுவான வேகம் கண்டறியப்பட்டுள்ளது.';
      }
    } else {
      trafficComm = 'Traffic data is currently unavailable, so it was not included in this explanation.';
      tamilTrafficComm = 'போக்குவரத்து தரவு தற்போது கிடைக்கவில்லை, எனவே இது சேர்க்கப்படவில்லை.';
    }

    // 4. Weather
    final weatherFactor = findFactor('Weather');
    final weatherScore = weatherFactor?.score;
    final isWeatherAvailable =
        weatherFactor != null && weatherFactor.relevant && weatherScore != null;
    final String weatherComm;
    final String tamilWeatherComm;
    if (isWeatherAvailable) {
      if (weatherScore >= 70) {
        weatherComm = 'Current weather conditions are favorable for travel.';
        tamilWeatherComm = 'தற்போதைய வானிலை பயணத்திற்கு சாதகமாக உள்ளது.';
      } else if (weatherScore >= 40) {
        weatherComm = 'Mild weather conditions observed along the route.';
        tamilWeatherComm = 'வழியில் மிதமான வானிலை நிலவுகிறது.';
      } else {
        weatherComm = 'Adverse weather conditions (rain or high wind) detected on this route.';
        tamilWeatherComm =
            'இந்த வழியில் மழை அல்லது பலத்த காற்று போன்ற பாதகமான வானிலை உள்ளது.';
      }
    } else {
      weatherComm = 'Weather data is currently unavailable, so it was not included in this explanation.';
      tamilWeatherComm =
          'வானிலை தரவு தற்போது கிடைக்கவில்லை, எனவே இது சேர்க்கப்படவில்லை.';
    }

    // 5. Lighting
    final lightFactor = findFactor('Lighting');
    final lightScore = isDay ? null : lightFactor?.score;
    final isLightAvailable =
        !isDay &&
        lightFactor != null &&
        lightFactor.relevant &&
        lightScore != null;
    final String lightComm;
    final String tamilLightComm;
    if (isDay) {
      lightComm = 'Lighting conditions are not evaluated for daytime travel.';
      tamilLightComm = 'பகல் நேர பயணத்திற்கு வெளிச்ச நிலை கணக்கிடப்படவில்லை.';
    } else if (isLightAvailable) {
      if (lightScore >= 65) {
        lightComm = 'Lighting conditions are favorable.';
        tamilLightComm = 'வெளிச்ச நிலை சாதகமாக உள்ளது.';
      } else {
        lightComm = 'Limited street lighting recorded on night segments.';
        tamilLightComm =
            'இரவு நேரப் பகுதிகளில் குறைந்த தெருவிளக்கு வசதி பதிவாகியுள்ளது.';
      }
    } else {
      lightComm = 'Street lighting data is currently unavailable, so it was not included in this explanation.';
      tamilLightComm =
          'தெருவிளக்கு தரவு தற்போது கிடைக்கவில்லை, எனவே இது சேர்க்கப்படவில்லை.';
    }

    // 6. Accessibility
    final accessFactor = findFactor('Accessibility');
    final accessScore = accessFactor?.score;
    final isAccessAvailable =
        accessFactor != null && accessFactor.relevant && accessScore != null;
    final String accessComm;
    final String tamilAccessComm;
    if (isAccessAvailable) {
      if (accessScore >= 65) {
        accessComm = 'This route has better accessibility conditions.';
        tamilAccessComm =
            'இந்த வழி சிறந்த அணுகல்தன்மை நிலைமைகளைக் கொண்டுள்ளது.';
      } else if (accessScore >= 40) {
        accessComm = 'Standard accessibility infrastructure along this route.';
        tamilAccessComm = 'இந்த வழியில் வழக்கமான அணுகல்தன்மை வசதிகள் உள்ளன.';
      } else {
        accessComm = 'Limited accessibility infrastructure reported along this corridor.';
        tamilAccessComm =
            'குறைந்த நடைபாதை மற்றும் அணுகல் வசதிகள் கண்டறியப்பட்டுள்ளன.';
      }
    } else {
      accessComm = 'Accessibility data is currently unavailable, so it was not included in this explanation.';
      tamilAccessComm =
          'அணுகல்தன்மை தரவு தற்போது கிடைக்கவில்லை, எனவே இது சேர்க்கப்படவில்லை.';
    }

    final factors = [
      RouteFactorAnalysis(
        key: 'accident',
        title: 'Accident Risk',
        icon: Icons.shield_rounded,
        score: isAccAvailable ? accScore : null,
        isAvailable: isAccAvailable,
        unavailableReason: accFactor?.unavailableReason,
        commentary: accComm,
        tamilCommentary: tamilAccComm,
      ),
      RouteFactorAnalysis(
        key: 'road',
        title: 'Road Condition',
        icon: Icons.add_road_rounded,
        score: isRoadAvailable ? roadScore : null,
        isAvailable: isRoadAvailable,
        unavailableReason: roadFactor?.unavailableReason,
        commentary: roadComm,
        tamilCommentary: tamilRoadComm,
      ),
      RouteFactorAnalysis(
        key: 'traffic',
        title: 'Traffic',
        icon: Icons.traffic_rounded,
        score: isTrafficAvailable ? trafficScore : null,
        isAvailable: isTrafficAvailable,
        unavailableReason: trafficFactor?.unavailableReason,
        commentary: trafficComm,
        tamilCommentary: tamilTrafficComm,
      ),
      RouteFactorAnalysis(
        key: 'weather',
        title: 'Weather',
        icon: Icons.cloud_rounded,
        score: isWeatherAvailable ? weatherScore : null,
        isAvailable: isWeatherAvailable,
        unavailableReason: weatherFactor?.unavailableReason,
        commentary: weatherComm,
        tamilCommentary: tamilWeatherComm,
      ),
      RouteFactorAnalysis(
        key: 'lighting',
        title: 'Lighting',
        icon: Icons.lightbulb_rounded,
        score: isLightAvailable ? lightScore : null,
        isAvailable: isLightAvailable,
        unavailableReason: isDay
            ? 'Not evaluated for day travel'
            : lightFactor?.unavailableReason,
        commentary: lightComm,
        tamilCommentary: tamilLightComm,
      ),
      RouteFactorAnalysis(
        key: 'accessibility',
        title: 'Accessibility',
        icon: Icons.accessible_rounded,
        score: isAccessAvailable ? accessScore : null,
        isAvailable: isAccessAvailable,
        unavailableReason: accessFactor?.unavailableReason,
        commentary: accessComm,
        tamilCommentary: tamilAccessComm,
      ),
    ];

    // Travel calculations
    final targetDistance = targetEvaluation.route.distance;
    final targetMins = service.calculateVehicleTime(targetDistance, vehicle);
    final formattedDuration = formatDurationFn(targetMins);
    final targetScore = targetEvaluation.safety.score;

    // Alternative comparison
    final otherEvaluations = allEvaluations.values
        .where((e) => e.route.routeIndex != targetEvaluation.route.routeIndex)
        .toList();

    final positiveHighlights = <String>[];
    final tradeOffHighlights = <String>[];
    final tamilPositiveHighlights = <String>[];
    final tamilTradeOffHighlights = <String>[];
    String comparativeNarrative = '';
    String tamilComparativeNarrative = '';

    if (otherEvaluations.isNotEmpty) {
      final other = otherEvaluations.first;
      final otherScore = other.safety.score ?? 0.0;
      final currentScore = targetScore ?? 0.0;
      final otherMins = service.calculateVehicleTime(
        other.route.distance,
        vehicle,
      );
      final scoreDelta = currentScore - otherScore;
      final timeDeltaMins = (targetMins - otherMins).round();

      double? getScore(PersonalizedSafetyResult res, String k) {
        for (final f in res.factors) {
          if (f.title == k ||
              (k == 'Accident Risk' && f.title == 'Verified blackspots') ||
              (k == 'Road Condition' && f.title == 'Road condition')) {
            return f.score;
          }
        }
        return null;
      }

      final targetAcc = getScore(targetEvaluation.safety, 'Accident Risk');
      final otherAcc = getScore(other.safety, 'Accident Risk');
      final targetRoad = getScore(targetEvaluation.safety, 'Road Condition');
      final otherRoad = getScore(other.safety, 'Road Condition');
      final targetWeather = getScore(targetEvaluation.safety, 'Weather');
      final otherWeather = getScore(other.safety, 'Weather');
      final targetTraffic = getScore(targetEvaluation.safety, 'Traffic');
      final otherTraffic = getScore(other.safety, 'Traffic');

      final reasons = <String>[];
      final tamilReasons = <String>[];

      if (scoreDelta > 2) {
        positiveHighlights.add('Safer (+${scoreDelta.round()} pts)');
        tamilPositiveHighlights.add(
          'அதிக பாதுகாப்பு (+${scoreDelta.round()} புள்ளிகள்)',
        );
      } else if (scoreDelta < -2) {
        tradeOffHighlights.add(
          'Lower safety score (-${(-scoreDelta).round()} pts)',
        );
        tamilTradeOffHighlights.add(
          'குறைந்த பாதுகாப்பு மதிப்பெண் (-${(-scoreDelta).round()} புள்ளிகள்)',
        );
      }

      if (targetRoad != null &&
          otherRoad != null &&
          targetRoad > otherRoad + 3) {
        positiveHighlights.add('Better road condition');
        tamilPositiveHighlights.add('சிறந்த சாலை நிலை');
        reasons.add('better road conditions');
        tamilReasons.add('சிறந்த சாலை நிலை');
      }
      if (targetAcc != null && otherAcc != null && targetAcc > otherAcc + 3) {
        positiveHighlights.add('Lower accident risk');
        tamilPositiveHighlights.add('குறைந்த விபத்து அபாயம்');
        reasons.add('lower accident risk');
        tamilReasons.add('குறைந்த விபத்து அபாயம்');
      }
      if (targetWeather != null &&
          otherWeather != null &&
          targetWeather > otherWeather + 3) {
        positiveHighlights.add('Better weather');
        tamilPositiveHighlights.add('சிறந்த வானிலை');
        reasons.add('favorable weather');
        tamilReasons.add('சாதகமான வானிலை');
      }
      if (targetTraffic != null &&
          otherTraffic != null &&
          targetTraffic > otherTraffic + 3) {
        positiveHighlights.add('Smoother traffic');
        tamilPositiveHighlights.add('சீரான போக்குவரத்து');
        reasons.add('smoother traffic flow');
        tamilReasons.add('சீரான போக்குவரத்து');
      }

      final absTimeDelta = (-timeDeltaMins);
      if (timeDeltaMins >= 2) {
        tradeOffHighlights.add('Slightly longer (+${timeDeltaMins}m)');
        tamilTradeOffHighlights.add(
          'சற்று கூடுதல் நேரம் (+$timeDeltaMins நிமிடம்)',
        );
      } else if (timeDeltaMins <= -2) {
        positiveHighlights.add('Faster route (-${absTimeDelta}m)');
        tamilPositiveHighlights.add('விரைவான வழி (-$absTimeDelta நிமிடம்)');
      }

      if (!isTrafficAvailable) {
        tradeOffHighlights.add('Traffic data unavailable');
        tamilTradeOffHighlights.add('போக்குவரத்து தரவு கிடைக்கவில்லை');
      }

      final targetNum = targetEvaluation.route.routeIndex + 1;
      final otherNum = other.route.routeIndex + 1;

      if (scoreDelta > 2) {
        if (reasons.isNotEmpty) {
          comparativeNarrative =
              'Route $targetNum has a higher safety score than Route $otherNum (${currentScore.round()}% vs ${otherScore.round()}%), mainly because of ${reasons.join(' and ')}.';
          tamilComparativeNarrative =
              'வழி $targetNum, வழி $otherNum-ஐ விட அதிக பாதுகாப்பு மதிப்பெண்ணைப் பெற்றுள்ளது (${currentScore.round()}% vs ${otherScore.round()}%), முக்கியமாக ${tamilReasons.join(' மற்றும் ')} காரணமாக.';
        } else {
          comparativeNarrative =
              'Route $targetNum has a higher safety score than Route $otherNum (${currentScore.round()}% vs ${otherScore.round()}%).';
          tamilComparativeNarrative =
              'வழி $targetNum, வழி $otherNum-ஐ விட அதிக பாதுகாப்பு மதிப்பெண்ணைப் பெற்றுள்ளது (${currentScore.round()}% vs ${otherScore.round()}%).';
        }
        if (timeDeltaMins >= 2) {
          comparativeNarrative +=
              ' Route $otherNum is faster by ${timeDeltaMins}m, but Route $targetNum provides a higher safety score.';
          tamilComparativeNarrative +=
              ' வழி $otherNum $timeDeltaMins நிமிடம் விரைவானது, ஆனால் வழி $targetNum அதிக பாதுகாப்பை வழங்குகிறது.';
        }
      } else if (scoreDelta < -2) {
        if (timeDeltaMins <= -2) {
          comparativeNarrative =
              'Route $targetNum is faster by ${absTimeDelta}m, but Route $otherNum provides a higher safety score (${otherScore.round()}% vs ${currentScore.round()}%).';
          tamilComparativeNarrative =
              'வழி $targetNum $absTimeDelta நிமிடம் விரைவானது, ஆனால் வழி $otherNum அதிக பாதுகாப்பு மதிப்பெண்ணை வழங்குகிறது (${otherScore.round()}% vs ${currentScore.round()}%).';
        } else {
          comparativeNarrative =
              'Route $otherNum has a higher safety score (${otherScore.round()}% vs ${currentScore.round()}%). Consider reviewing Route $otherNum for safer transit.';
          tamilComparativeNarrative =
              'வழி $otherNum அதிக பாதுகாப்பு மதிப்பெண்ணைக் கொண்டுள்ளது (${otherScore.round()}% vs ${currentScore.round()}%). பாதுகாப்பான பயணத்திற்கு வழி $otherNum-ஐ பரிசீலிக்கவும்.';
        }
      } else {
        comparativeNarrative =
            'Both Route $targetNum and Route $otherNum offer similar safety levels (${currentScore.round()}% vs ${otherScore.round()}%).';
        tamilComparativeNarrative =
            'வழி $targetNum மற்றும் வழி $otherNum இரண்டும் ஒத்த பாதுகாப்பு நிலைகளைக் கொண்டுள்ளன (${currentScore.round()}% vs ${otherScore.round()}%).';
        if (timeDeltaMins <= -2) {
          comparativeNarrative +=
              ' Route $targetNum is faster by ${absTimeDelta}m.';
          tamilComparativeNarrative +=
              ' வழி $targetNum $absTimeDelta நிமிடம் விரைவானது.';
        }
      }
    } else {
      positiveHighlights.add('Evaluated primary route');
      tamilPositiveHighlights.add('மதிப்பாய்வு செய்யப்பட்ட முதன்மை வழி');
      if (!isTrafficAvailable) {
        tradeOffHighlights.add('Traffic data unavailable');
        tamilTradeOffHighlights.add('போக்குவரத்து தரவு கிடைக்கவில்லை');
      }
      comparativeNarrative =
          'Showing direct safety evaluation for the primary route. Real metrics indicate calculated safety index of ${targetScore?.round() ?? '--'}%.';
      tamilComparativeNarrative =
          'முதன்மை வழிக்கான நேரடி பாதுகாப்பு பகுப்பாய்வு. கணக்கிடப்பட்ட பாதுகாப்பு குறியீடு ${targetScore?.round() ?? '--'}%.';
    }

    // Safety vs Time calculations across all evaluations
    final evalsList = allEvaluations.values.isNotEmpty
        ? allEvaluations.values.toList()
        : [targetEvaluation];
    _RouteEvaluation safest = evalsList.first;
    _RouteEvaluation fastest = evalsList.first;

    for (final e in evalsList) {
      if ((e.safety.score ?? 0.0) > (safest.safety.score ?? 0.0)) {
        safest = e;
      }
      final eMins = service.calculateVehicleTime(e.route.distance, vehicle);
      final fMins = service.calculateVehicleTime(
        fastest.route.distance,
        vehicle,
      );
      if (eMins < fMins) {
        fastest = e;
      }
    }

    final safestDuration = service.calculateVehicleTime(
      safest.route.distance,
      vehicle,
    );
    final fastestDuration = service.calculateVehicleTime(
      fastest.route.distance,
      vehicle,
    );

    final String safetyVsTimeNarrative;
    final String tamilSafetyVsTimeNarrative;
    if (safest.route.routeIndex == fastest.route.routeIndex) {
      safetyVsTimeNarrative =
          'Optimal choice: Route ${safest.route.routeIndex + 1} is both the safest (${safest.safety.score?.round() ?? '--'}/100) and fastest (${formatDurationFn(safestDuration)}) route.';
      tamilSafetyVsTimeNarrative =
          'சிறந்த தேர்வு: வழி ${safest.route.routeIndex + 1} பாதுகாப்பான (${safest.safety.score?.round() ?? '--'}/100) மற்றும் வேகமான (${formatDurationFn(safestDuration)}) வழியாகும்.';
    } else {
      final timeSaved = (safestDuration - fastestDuration).round();
      safetyVsTimeNarrative =
          'Route ${fastest.route.routeIndex + 1} is faster by ${timeSaved}m, while Route ${safest.route.routeIndex + 1} provides the highest safety score (${safest.safety.score?.round() ?? '--'}/100) with lower accident exposure.';
      tamilSafetyVsTimeNarrative =
          'வழி ${fastest.route.routeIndex + 1} $timeSaved நிமிடம் விரைவானது, அதேசமயம் வழி ${safest.route.routeIndex + 1} அதிக பாதுகாப்பு மதிப்பெண்ணை (${safest.safety.score?.round() ?? '--'}/100) வழங்குகிறது.';
    }

    // Recommendation Badge
    final String badge;
    final String tamilBadge;
    final Color badgeColor;
    final IconData badgeIcon;

    if (otherEvaluations.isEmpty) {
      if ((targetScore ?? 0.0) >= 70) {
        badge = 'Recommended for safety';
        tamilBadge = 'பாதுகாப்பிற்கு பரிந்துரைக்கப்படுகிறது';
        badgeColor = _NeonTheme.safeGreen;
        badgeIcon = Icons.verified_user_rounded;
      } else {
        badge = 'Proceed with caution';
        tamilBadge = 'எச்சரிக்கையுடன் செல்லவும்';
        badgeColor = _NeonTheme.warningGold;
        badgeIcon = Icons.warning_amber_rounded;
      }
    } else {
      final bestScore = safest.safety.score ?? 0.0;
      final currentScore = targetScore ?? 0.0;
      final isTopTier = currentScore >= bestScore - 2;
      final otherTopTier = otherEvaluations.any(
        (o) => (o.safety.score ?? 0.0) >= bestScore - 2,
      );

      if (isTopTier &&
          otherTopTier &&
          currentScore <= bestScore + 2 &&
          bestScore - (otherEvaluations.first.safety.score ?? 0.0) <= 2) {
        badge = 'Both routes have similar safety levels';
        tamilBadge = 'இரு வழிகளிலும் ஒத்த பாதுகாப்பு நிலைகள்';
        badgeColor = _NeonTheme.neonCyan;
        badgeIcon = Icons.compare_arrows_rounded;
      } else if (targetEvaluation.route.routeIndex == safest.route.routeIndex) {
        badge = 'Recommended for safety';
        tamilBadge = 'பாதுகாப்பிற்கு பரிந்துரைக்கப்படுகிறது';
        badgeColor = _NeonTheme.safeGreen;
        badgeIcon = Icons.verified_user_rounded;
      } else {
        badge =
            'Consider Route ${safest.route.routeIndex + 1} for better safety';
        tamilBadge =
            'அதிக பாதுகாப்பிற்கு வழி ${safest.route.routeIndex + 1}-ஐ பரிசீலிக்கவும்';
        badgeColor = _NeonTheme.warningGold;
        badgeIcon = Icons.info_outline_rounded;
      }
    }

    return WhyThisRouteAnalysis(
      targetRouteIndex: targetEvaluation.route.routeIndex,
      targetRouteLabel: 'Route ${targetEvaluation.route.routeIndex + 1}',
      origin: origin,
      destination: destination,
      safetyScore: targetScore,
      distanceKm: targetDistance,
      durationMinutes: targetMins,
      formattedDuration: formattedDuration,
      factors: factors,
      positiveHighlights: positiveHighlights,
      tradeOffHighlights: tradeOffHighlights,
      tamilPositiveHighlights: tamilPositiveHighlights,
      tamilTradeOffHighlights: tamilTradeOffHighlights,
      comparativeNarrative: comparativeNarrative,
      tamilComparativeNarrative: tamilComparativeNarrative,
      recommendationBadge: badge,
      tamilRecommendationBadge: tamilBadge,
      recommendationBadgeColor: badgeColor,
      recommendationBadgeIcon: badgeIcon,
      safestRouteIndex: safest.route.routeIndex,
      safestRouteScore: safest.safety.score,
      safestRouteDurationMinutes: safestDuration,
      fastestRouteIndex: fastest.route.routeIndex,
      fastestRouteScore: fastest.safety.score,
      fastestRouteDurationMinutes: fastestDuration,
      safetyVsTimeNarrative: safetyVsTimeNarrative,
      tamilSafetyVsTimeNarrative: tamilSafetyVsTimeNarrative,
    );
  }
}

class WhyThisRouteDialog extends StatefulWidget {
  final int initialRouteIndex;
  final Map<int, _RouteEvaluation> allEvaluations;
  final String origin;
  final String destination;
  final String vehicle;
  final String travelTime;
  final String priority;
  final SafeRouteService service;
  final bool isDarkMode;
  final String Function(double minutes) formatDurationFn;
  final PersonalSafetyProfile? personalProfile;

  const WhyThisRouteDialog({
    super.key,
    required this.initialRouteIndex,
    required this.allEvaluations,
    required this.origin,
    required this.destination,
    required this.vehicle,
    required this.travelTime,
    required this.priority,
    required this.service,
    required this.isDarkMode,
    required this.formatDurationFn,
    this.personalProfile,
  });

  @override
  State<WhyThisRouteDialog> createState() => _WhyThisRouteDialogState();
}

class _WhyThisRouteDialogState extends State<WhyThisRouteDialog> {
  late int _currentRouteIndex;
  bool _isTamil = false;

  @override
  void initState() {
    super.initState();
    _currentRouteIndex = widget.initialRouteIndex;
    if (!widget.allEvaluations.containsKey(_currentRouteIndex) &&
        widget.allEvaluations.isNotEmpty) {
      _currentRouteIndex = widget.allEvaluations.keys.first;
    }
  }

  @override
  Widget build(BuildContext context) {
    final isDark = widget.isDarkMode;
    final targetEval =
        widget.allEvaluations[_currentRouteIndex] ??
        widget.allEvaluations.values.first;

    final analysis = RouteExplanationEngine.generate(
      targetEvaluation: targetEval,
      allEvaluations: widget.allEvaluations,
      origin: widget.origin,
      destination: widget.destination,
      vehicle: widget.vehicle,
      travelTime: widget.travelTime,
      priority: widget.priority,
      service: widget.service,
      formatDurationFn: widget.formatDurationFn,
    );

    final score = analysis.safetyScore;
    final scoreColor = score != null && score >= 70
        ? _NeonTheme.safeGreen
        : score != null && score >= 40
        ? _NeonTheme.warningGold
        : _NeonTheme.dangerRed;

    final mediaQuery = MediaQuery.of(context);
    final isMobile = mediaQuery.size.width < 600;

    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: EdgeInsets.symmetric(
        horizontal: isMobile ? 12 : 24,
        vertical: 20,
      ),
      child: Container(
        constraints: BoxConstraints(
          maxWidth: 640,
          maxHeight: mediaQuery.size.height * 0.92,
        ),
        decoration: BoxDecoration(
          color: isDark ? _NeonTheme.cardDark : _NeonTheme.cardLight,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: isDark ? _NeonTheme.cyanBorder : const Color(0xffE2E8F0),
            width: 1.2,
          ),
          boxShadow: _NeonTheme.cardShadow(isDark),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // Top Header Bar
            _buildDialogHeader(isDark),
            // Scrollable Content
            Flexible(
              child: SingleChildScrollView(
                padding: const EdgeInsets.symmetric(
                  horizontal: 18,
                  vertical: 12,
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    // Route Selection Pills (if multiple alternatives exist)
                    if (widget.allEvaluations.length > 1) ...[
                      _buildRouteSelectorTabs(isDark),
                      const SizedBox(height: 14),
                    ],
                    // Route Context & Score Card
                    _buildRouteContextCard(analysis, scoreColor, isDark),
                    const SizedBox(height: 14),
                    // Based on Your Preferences (Personal Safety Profile)
                    if (widget.personalProfile != null &&
                        (widget.personalProfile!.isConfigured || widget.personalProfile!.safetyMode != 'General')) ...[
                      _buildPersonalPreferencesCard(analysis, isDark),
                      const SizedBox(height: 14),
                    ],
                    // "Why Route X?" Comparison & Highlights
                    _buildComparisonCard(analysis, isDark),
                    const SizedBox(height: 14),
                    // Safety Factor Score Breakdown (All 6 Factors)
                    _buildFactorsBreakdown(analysis, isDark),
                    const SizedBox(height: 14),
                    // Safety vs Time Trade-off Section
                    _buildSafetyVsTimeSection(analysis, isDark),
                    const SizedBox(height: 14),
                    // Recommendation Badge at bottom
                    _buildRecommendationBanner(analysis, isDark),
                    const SizedBox(height: 16),
                  ],
                ),
              ),
            ),
            // Footer Action Button
            _buildDialogFooter(isDark),
          ],
        ),
      ),
    );
  }

  Widget _buildDialogHeader(bool isDark) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(18, 16, 14, 8),
      child: Row(
        children: [
          Container(
            padding: const EdgeInsets.all(7),
            decoration: BoxDecoration(
              color: _NeonTheme.neonCyan.withValues(alpha: 0.16),
              borderRadius: BorderRadius.circular(10),
            ),
            child: const Icon(
              Icons.auto_awesome,
              color: _NeonTheme.neonCyan,
              size: 20,
            ),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  WhyThisRouteLocalization.title(_isTamil),
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.w800,
                    color: isDark
                        ? _NeonTheme.textPrimaryDark
                        : _NeonTheme.textPrimaryLight,
                  ),
                ),
                Text(
                  WhyThisRouteLocalization.subtitle(_isTamil),
                  style: TextStyle(
                    fontSize: 11,
                    color: isDark
                        ? _NeonTheme.textSecondaryDark
                        : _NeonTheme.textSecondaryLight,
                  ),
                ),
              ],
            ),
          ),
          // Language Toggle Chip
          InkWell(
            onTap: () {
              setState(() {
                _isTamil = !_isTamil;
              });
            },
            borderRadius: BorderRadius.circular(8),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
              decoration: BoxDecoration(
                color: _isTamil
                    ? _NeonTheme.neonAmber.withValues(alpha: 0.2)
                    : _NeonTheme.neonCyan.withValues(alpha: 0.15),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(
                  color: _isTamil ? _NeonTheme.neonAmber : _NeonTheme.neonCyan,
                  width: 0.8,
                ),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(
                    Icons.translate_rounded,
                    size: 12,
                    color: _isTamil
                        ? _NeonTheme.neonAmber
                        : _NeonTheme.neonCyan,
                  ),
                  const SizedBox(width: 4),
                  Text(
                    _isTamil ? 'தமிழ்' : 'English',
                    style: TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w800,
                      color: _isTamil
                          ? _NeonTheme.neonAmber
                          : _NeonTheme.neonCyan,
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(width: 4),
          IconButton(
            icon: const Icon(Icons.close_rounded, size: 20),
            onPressed: () => Navigator.of(context).pop(),
            color: isDark
                ? _NeonTheme.textSecondaryDark
                : _NeonTheme.textSecondaryLight,
          ),
        ],
      ),
    );
  }

  Widget _buildRouteSelectorTabs(bool isDark) {
    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: Row(
        children: [
          for (final entry in widget.allEvaluations.entries) ...[
            InkWell(
              onTap: () {
                setState(() {
                  _currentRouteIndex = entry.key;
                });
              },
              borderRadius: BorderRadius.circular(8),
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 6,
                ),
                decoration: BoxDecoration(
                  color: entry.key == _currentRouteIndex
                      ? _NeonTheme.neonCyan.withValues(alpha: 0.2)
                      : (isDark
                            ? Colors.white.withValues(alpha: 0.05)
                            : Colors.black.withValues(alpha: 0.04)),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                    color: entry.key == _currentRouteIndex
                        ? _NeonTheme.neonCyan
                        : (isDark ? Colors.white12 : Colors.black12),
                    width: entry.key == _currentRouteIndex ? 1.4 : 0.8,
                  ),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(
                      entry.key == _currentRouteIndex
                          ? Icons.radio_button_checked_rounded
                          : Icons.radio_button_off_rounded,
                      size: 12,
                      color: entry.key == _currentRouteIndex
                          ? _NeonTheme.neonCyan
                          : (isDark
                                ? _NeonTheme.textSecondaryDark
                                : _NeonTheme.textSecondaryLight),
                    ),
                    const SizedBox(width: 5),
                    Text(
                      'Route ${entry.key + 1}',
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                        color: entry.key == _currentRouteIndex
                            ? _NeonTheme.neonCyan
                            : (isDark ? Colors.white70 : Colors.black87),
                      ),
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(width: 8),
          ],
        ],
      ),
    );
  }

